395	// parseVitalityEvents decodes log lines best-effort: blank lines are skipped,
396	// malformed or incomplete lines (e.g. a torn tail after power loss) are
397	// counted and dropped rather than failing the layer, and unknown event types
398	// are ignored for forward compatibility.
399	func parseVitalityEvents(data []byte) (events []vitalityEvent, malformed int) {
400		for line := range bytes.Lines(data) {
401			line = bytes.TrimSpace(line)
402			if len(line) == 0 {
403				continue
404			}
405			var event vitalityEvent
406			if err := json.Unmarshal(line, &event); err != nil || event.FactID == "" || event.At.IsZero() {
407				malformed++
408				continue
409			}
410			if event.Type != vitalityEventServed {
411				continue
412			}
413			events = append(events, event)
414		}
415		return events, malformed
416	}
417	
418	// mergeVitalityEvents folds events (in log order) into the rollup and evicts
419	// overflow. The fold is deterministic given the log: "last" fields follow
420	// event time, with log order breaking exact ties.
421	func mergeVitalityEvents(rollup *vitalityRollup, events []vitalityEvent) {
422		for _, event := range events {
423			at := event.At.UTC()
424			entry := rollup.Facts[event.FactID]
425			if entry == nil {
426				entry = &vitalityFactRollup{FirstServed: at}
427				rollup.Facts[event.FactID] = entry
428			}
429			entry.Served++
430			if entry.FirstServed.IsZero() || at.Before(entry.FirstServed) {
431				entry.FirstServed = at
432			}
433			if !at.Before(entry.LastServed) {
434				entry.LastServed = at
435				entry.LastSurface = event.Surface
436				entry.LastHead = event.Head
437				entry.LastTaskSHA = event.TaskSHA
438			}
439			if event.Surface != "" {
440				if entry.Surfaces == nil {
441					entry.Surfaces = map[string]int{}
442				}
443				entry.Surfaces[event.Surface]++
444			}
445		}

