   490	//  1. fold the log's unabsorbed suffix into the rollup and persist it with a
   491	//     marker naming the exact log content now absorbed;
   492	//  2. truncate the log, then clear the marker.
   493	//
   494	// A crash after (1) leaves the marker matching the log, so the next run skips
   495	// the already-absorbed prefix instead of double-counting. A crash after the
   496	// truncate leaves a stale marker over an empty log, which the next run simply
   497	// clears. Rerunning with no new events writes nothing, so compaction is
   498	// idempotent, and the rollup is a pure function of the event sequence, so it
   499	// is deterministic.
   500	//
   501	// A corrupt rollup is self-healing: it is rebuilt from whatever the log still
   502	// holds (the corrupt file's history is unrecoverable by definition), because
   503	// receipts are droppable evidence and must never wedge the layer.
   504	func compactVitalityLocked(brainDir, branch string) (vitalityRollup, vitalityCompactStats, error) {
   505		var stats vitalityCompactStats
   506		data, err := readVitalityLog(brainDir, branch)
   507		if err != nil {
   508			return newVitalityRollup(), stats, err
   509		}
   510		rollup, rollupErr := loadVitalityRollup(brainDir, branch)
   511		if rollupErr != nil {
   512			rollup = newVitalityRollup()
   513			stats.RollupReset = true
   514		}
   515		absorbed := int64(0)
   516		if m := rollup.Log; m.AbsorbedBytes > 0 && m.AbsorbedBytes <= int64(len(data)) &&
   517			vitalityContentSHA(data[:m.AbsorbedBytes]) == m.AbsorbedSHA256 {
   518			absorbed = m.AbsorbedBytes
   519		}
   520		events, malformed := parseVitalityEvents(data[absorbed:])
   521		stats.NewEvents = len(events)
   522		stats.Malformed = malformed
   523		dirty := stats.RollupReset
   524		if len(events) > 0 {
   525			mergeVitalityEvents(&rollup, events)
   526			dirty = true
   527		}
   528		if len(data) > 0 {
   529			rollup.Log = vitalityLogMarker{AbsorbedBytes: int64(len(data)), AbsorbedSHA256: vitalityContentSHA(data)}
   530			if err := writeVitalityRollup(brainDir, branch, rollup); err != nil {
   531				return rollup, stats, err
   532			}
   533			if err := writeBrainRelativeFileAtomic(brainDir, factsVitalityLogRelPath(branch), nil, 0o600); err != nil {
   534				return rollup, stats, err
   535			}
   536			rollup.Log = vitalityLogMarker{}
   537			dirty = true
   538		} else if rollup.Log != (vitalityLogMarker{}) {
   539			rollup.Log = vitalityLogMarker{}
   540			dirty = true
   541		}
   542		if dirty {
   543			if err := writeVitalityRollup(brainDir, branch, rollup); err != nil {
   544				return rollup, stats, err
   545			}
   546		}
   547		return rollup, stats, nil
   548	}
   549	
   550	// vitalityViewStats describes the freshness and health of a vitality view.
   551	type vitalityViewStats struct {
   552		PendingEvents  int
   553		MalformedLines int
   554		LogBytes       int64
   555		RollupCorrupt  bool
   556	}
   557	
   558	// loadVitalityView returns the branch's rollup with the log's unabsorbed
   559	// events folded in — the up-to-date picture without forcing a compaction
   560	// write. It prefers to read under the vitality lock so it never interleaves
   561	// with a concurrent compaction, but degrades to a lock-free read (the files
   562	// are replaced atomically) rather than failing.
   563	func loadVitalityView(brainDir, branch string) (vitalityRollup, vitalityViewStats, error) {
   564		var (
   565			rollup vitalityRollup
   566			stats  vitalityViewStats
   567			err    error
   568		)
   569		read := func() error {
   570			var rollupErr error
   571			rollup, rollupErr = loadVitalityRollup(brainDir, branch)
   572			if rollupErr != nil {
   573				rollup = newVitalityRollup()
   574				stats.RollupCorrupt = true
   575			}
   576			data, logErr := readVitalityLog(brainDir, branch)
   577			if logErr != nil {
   578				return logErr
   579			}
   580			stats.LogBytes = int64(len(data))
   581			absorbed := int64(0)
   582			if m := rollup.Log; m.AbsorbedBytes > 0 && m.AbsorbedBytes <= int64(len(data)) &&
   583				vitalityContentSHA(data[:m.AbsorbedBytes]) == m.AbsorbedSHA256 {
   584				absorbed = m.AbsorbedBytes
   585			}
   586			events, malformed := parseVitalityEvents(data[absorbed:])
   587			stats.PendingEvents = len(events)
   588			stats.MalformedLines = malformed
   589			mergeVitalityEvents(&rollup, events)
   590			rollup.Log = vitalityLogMarker{}
   591			return nil
   592		}
   593		ran := false
   594		err = withVitalityLock(brainDir, func() error {
   595			ran = true
   596			return read()
   597		})
   598		if !ran && errors.Is(err, errFileLockTimeout) {
   599			// Contention is not a read failure: compaction replacements are atomic and
   600			// the log parser tolerates a torn append tail. Path/symlink/setup failures
   601			// are not contention and must never bypass the lock path's safety checks.
   602			stats = vitalityViewStats{}
   603			err = read()
   604		}
   605		return rollup, stats, err
   606	}
