func TestWriteTimeGuardKeepsGuideDistinctFromInstructions(t *testing.T) {
	for _, target := range []string{filepath.FromSlash(Path), "AGENTS.md"} {
		t.Run(target, func(t *testing.T) {
			repo := t.TempDir()
