			if err := os.Mkdir(repo, 0o755); err != nil {
				t.Fatal(err)
			}
			victimPath := filepath.Join(base, "victim.md")
			victim := []byte("# outside the repository\n")
			if err := os.WriteFile(victimPath, victim, 0o644); err != nil {
				t.Fatal(err)
			}
