	if err := os.WriteFile(victimPath, victim, 0o644); err != nil {
		t.Fatal(err)
	}
	absentPath := filepath.Join(base, "absent.md")
	symlinkForTest(t, filepath.Join("..", "victim.md"), filepath.Join(repo, "AGENTS.md"))
