		"empty password":          "https://alice:@api.entire.io",
	} {
		t.Run(name, func(t *testing.T) {
			got, err := Validate(raw)
			if err == nil {
				t.Fatalf("Validate(%q) = %q, nil; a base URL with credentials must be refused", raw, got)
