	paths := NormalizePaths([]string{"constraints.invariants.general"})
	id := RecordID("the index is derived from the ndjson truth", paths)
	if id != recordIDNDJSONTruth {
		t.Fatalf("RecordID = %s, want %s", id, recordIDNDJSONTruth)
