func TestInitAgentsRefusesManagedTargetCollisionsBeforeWriting(t *testing.T) {
	skipIfSymlinksUnrepresentable(t)
	t.Run("guide symlinks to AGENTS", func(t *testing.T) {
		repo := t.TempDir()
		guideDir := filepath.Join(repo, ".entire")
