package brainwire

import (
	"bytes"
	"crypto/rand"
	"encoding/json"
	"testing"
	"unicode/utf8"
)

// FuzzCanonicalizeIdempotent asserts the property the whole signing scheme rests on:
// canonical form is a FIXED POINT. If Canonicalize(Canonicalize(x)) can ever differ
// from Canonicalize(x), a signature verified over re-canonicalized bytes is verifying
// something other than what the signer signed.
//
// It also asserts every accepted output is itself acceptable and valid UTF-8, so the
// encoder can never emit bytes its own decoder rejects.
func FuzzCanonicalizeIdempotent(f *testing.F) {
	f.Add([]byte(`{"manifest":{"repo_key":"gh/o/r","generated_at":"2026-01-02T03:04:05Z","brain_schema_version":"1.0"}}`))
	f.Add([]byte(`{"manifest":{"repo_key":"a<b>c&d","generated_at":"2026-01-02T03:04:05.000Z","brain_schema_version":"1.0"}}`))
	f.Add([]byte(`{"manifest":{"brain_schema_version":"1.0","generated_at":"2026-01-02t03:04:05z","repo_key":"r"},"snapshots":[]}`))
	f.Add([]byte(`{"manifest":{"repo_key":"r","generated_at":"2026-01-02T03:04:05Z","brain_schema_version":"1.0"},"facts":[{"branch":"main","content":{"digest":"sha256:aa","size":0}}]}`))

	f.Fuzz(func(t *testing.T, raw []byte) {
		once, err := Canonicalize(raw)
		if err != nil {
			return // rejected input is fine; only accepted input carries obligations
		}
		if !utf8.Valid(once) {
			t.Fatalf("canonical output is not valid UTF-8: %q", once)
		}
		twice, err := Canonicalize(once)
		if err != nil {
			t.Fatalf("canonical output was rejected by its own canonicalizer: %v\ninput=%q\nonce=%q", err, raw, once)
		}
		if !bytes.Equal(once, twice) {
			t.Fatalf("canonical form is not a fixed point:\ninput=%q\nonce =%q\ntwice=%q", raw, once, twice)
		}
	})
}

// FuzzCanonicalMarshalRoundTrip asserts that the struct path and the bytes path
// agree: canonical bytes decode into a BrainArtifact and re-marshal to exactly the
// same bytes. A gap means a signature produced through one path would not verify
// through the other.
//
// Scoped deliberately to artifacts whose keys are ALL known. Unknown newer-minor
// fields pass through canonicalization on purpose (ADR 0001 additive-only: an older
// verifier must still be able to verify a newer producer's artifact), and the struct
// cannot represent them, so re-marshaling necessarily drops them. That is a property
// boundary, not a defect — asserting round-trip equality over such inputs would be
// asserting that tolerance is a bug.
func FuzzCanonicalMarshalRoundTrip(f *testing.F) {
	f.Add([]byte(`{"manifest":{"repo_key":"gh/o/r","generated_at":"2026-01-02T03:04:05Z","brain_schema_version":"1.0"}}`))
	f.Add([]byte(`{"manifest":{"repo_key":"r","generated_at":"2026-01-02T03:04:05Z","brain_schema_version":"1.0"},"snapshots":[{"commit":"abc","content":{"digest":"sha256:ab","size":3}}]}`))

	f.Fuzz(func(t *testing.T, raw []byte) {
		canon, err := Canonicalize(raw)
		if err != nil {
			return
		}
		if canonicalHasUnknownKeys(t, canon) {
			return // tolerated by design; the struct path cannot round-trip it
		}
		var a BrainArtifact
		if err := CanonicalUnmarshal(canon, &a); err != nil {
			t.Fatalf("canonical bytes failed to decode into BrainArtifact: %v\ncanon=%q", err, canon)
		}
		again, err := CanonicalMarshal(a)
		if err != nil {
			t.Fatalf("decoded artifact failed to re-marshal: %v\ncanon=%q", err, canon)
		}
		if !bytes.Equal(canon, again) {
			t.Fatalf("struct path and bytes path disagree:\ncanon=%q\nagain=%q", canon, again)
		}
	})
}

// canonicalHasUnknownKeys reports whether any object in the artifact carries a key
// outside the contract, which the struct path is expected to drop.
func canonicalHasUnknownKeys(t *testing.T, canon []byte) bool {
	t.Helper()
	var top map[string]json.RawMessage
	if err := json.Unmarshal(canon, &top); err != nil {
		return true // unparseable here means "do not make round-trip claims about it"
	}
	known := map[string][]string{
		"":          {"manifest", "snapshots", "overlays", "facts"},
		"manifest":  {"repo_key", "default_branch", "generated_at", "brain_schema_version", "provider", "provider_version", "provider_schema_version"},
		"content":   {"digest", "size", "media_type", "path"},
		"snapshots": {"commit", "tree", "content"},
		"overlays":  {"base_commit", "head_commit", "branch", "content"},
		"facts":     {"branch", "content"},
	}
	has := func(set []string, k string) bool {
		for _, s := range set {
			if s == k {
				return true
			}
		}
		return false
	}
	// top level
	for k := range top {
		if !has(known[""], k) {
			return true
		}
	}
	// manifest object
	if rawManifest, ok := top["manifest"]; ok {
		var m map[string]json.RawMessage
		if json.Unmarshal(rawManifest, &m) != nil {
			return true
		}
		for k := range m {
			if !has(known["manifest"], k) {
				return true
			}
		}
	}
	// the three ref arrays, plus their nested content objects
	for _, arrKey := range []string{"snapshots", "overlays", "facts"} {
		rawArr, ok := top[arrKey]
		if !ok {
			continue
		}
		var arr []map[string]json.RawMessage
		if json.Unmarshal(rawArr, &arr) != nil {
			return true
		}
		for _, obj := range arr {
			for k := range obj {
				if !has(known[arrKey], k) {
					return true
				}
			}
			if rawContent, ok := obj["content"]; ok {
				var c map[string]json.RawMessage
				if json.Unmarshal(rawContent, &c) != nil {
					return true
				}
				for k := range c {
					if !has(known["content"], k) {
						return true
					}
				}
			}
		}
	}
	return false
}

// FuzzVerifyRejectsTamper is the security property of M1.4: over arbitrary canonical
// bytes, a signature verifies against exactly those bytes and NOTHING else. Any
// mutation — a flipped byte, a stripped field, appended trailing data — must fail
// verification, and must fail by returning an error rather than panicking, since
// VerifyBytes is an entry point for conten…834 tokens truncated…f{
				Digest:    "sha256:3333333333333333333333333333333333333333333333333333333333333333",
				Size:      4096,
				MediaType: "application/x-ndjson",
				Path:      "facts/main/facts.ndjson",
			},
		})
}

func TestBrainArtifactRoundTrip(t *testing.T) {
	original := representativeArtifact(t)

	b1, err := json.Marshal(original)
	if err != nil {
		t.Fatalf("marshal original: %v", err)
	}

	var decoded BrainArtifact
	if err := json.Unmarshal(b1, &decoded); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}

	// (a) deep-equality: the decoded artifact matches the original exactly.
	if !reflect.DeepEqual(*original, decoded) {
		t.Fatalf("round-trip changed the artifact:\n original=%#v\n decoded=%#v", *original, decoded)
	}

	// (a) byte-stability: re-marshaling the decoded artifact reproduces the
	// exact original bytes (declaration-ordered fields, ordered slices, no maps).
	b2, err := json.Marshal(decoded)
	if err != nil {
		t.Fatalf("marshal decoded: %v", err)
	}
	if !bytes.Equal(b1, b2) {
		t.Fatalf("marshal is not byte-stable:\n first=%s\nsecond=%s", b1, b2)
	}

	// The stamped version must be the local wire schema version.
	if decoded.Manifest.BrainSchemaVersion != BrainSchemaVersion {
		t.Fatalf("brain_schema_version = %q, want %q", decoded.Manifest.BrainSchemaVersion, BrainSchemaVersion)
	}
}

func TestCheckCompatibility(t *testing.T) {
	cases := []struct {
		name     string
		remote   string
		wantOK   bool
		wantWarn bool // whether warn should be non-empty
		wantErr  bool
	}{
		{name: "same version", remote: "1.0", wantOK: true},
		{name: "same major lower-or-equal minor", remote: "1.0", wantOK: true},
		{name: "same major higher minor warns", remote: "1.7", wantOK: true, wantWarn: true},
		{name: "unknown greater major errors", remote: "2.0", wantErr: true},
		{name: "unknown lesser major errors", remote: "0.9", wantErr: true},
		{name: "missing minor errors", remote: "1", wantErr: true},
		{name: "too many components errors", remote: "1.0.0", wantErr: true},
		{name: "non-numeric errors", remote: "1.x", wantErr: true},
		{name: "empty errors", remote: "", wantErr: true},
		{name: "negative errors", remote: "-1.0", wantErr: true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ok, warn, err := CheckCompatibility(tc.remote)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("CheckCompatibility(%q) = (ok=%v, warn=%q, err=nil), want error", tc.remote, ok, warn)
				}
				if ok {
					t.Fatalf("CheckCompatibility(%q): ok must be false on error", tc.remote)
				}
				return
			}
			if err != nil {
				t.Fatalf("CheckCompatibility(%q) unexpected error: %v", tc.remote, err)
			}
			if ok != tc.wantOK {
				t.Fatalf("CheckCompatibility(%q) ok = %v, want %v", tc.remote, ok, tc.wantOK)
			}
			if gotWarn := warn != ""; gotWarn != tc.wantWarn {
				t.Fatalf("CheckCompatibility(%q) warn=%q; hasWarn=%v, want %v", tc.remote, warn, gotWarn, tc.wantWarn)
			}
		})
	}
}

// TestTolerantReaderIgnoresUnknownFields proves a reader on schema 1.0 decodes an
// artifact produced by a hypothetical newer minor that added fields at every
// level. This is the tolerant-reader guarantee: a plain json.Unmarshal (no
// DisallowUnknownFields) drops unknown fields instead of failing.
func TestTolerantReaderIgnoresUnknownFields(t *testing.T) {
	// A superset payload: valid 1.0 fields plus unknown additive fields a
	// future 1.x minor might introduce, at the manifest, artifact, and
	// reference levels.
	payload := `{
		"manifest": {
			"repo_key": "gh/org/repo",
			"default_branch": "main",
			"generated_at": "2026-06-01T12:00:00Z",
			"brain_schema_version": "1.4",
			"provider": "entire-graph",
			"provider_version": "0.2.0",
			"provider_schema_version": "1.2",
			"future_manifest_field": {"nested": ["anything", 1, true]}
		},
		"snapshots": [
			{
				"commit": "abc123",
				"tree": "tree789",
				"content": {
					"digest": "sha256:1111",
					"size": 10,
					"media_type": "application/json",
					"future_content_field": "ignored"
				},
				"future_snapshot_field": 42
			}
		],
		"facts": [
			{"branch": "main", "content": {"digest": "sha256:3333"}}
		],
		"future_top_level_field": ["ignored"]
	}`

	var decoded BrainArtifact
	if err := json.Unmarshal([]byte(payload), &decoded); err != nil {
		t.Fatalf("tolerant decode failed: %v", err)
	}

	// Known fields survived.
	if decoded.Manifest.RepoKey != "gh/org/repo" {
		t.Fatalf("repo_key = %q, want gh/org/repo", decoded.Manifest.RepoKey)
	}
	if decoded.Manifest.BrainSchemaVersion != "1.4" {
		t.Fatalf("brain_schema_version = %q, want 1.4", decoded.Manifest.BrainSchemaVersion)
	}
	if decoded.Manifest.ProviderSchemaVersion != "1.2" {
		t.Fatalf("provider_schema_version = %q, want 1.2", decoded.Manifest.ProviderSchemaVersion)
	}
	if len(decoded.Snapshots) != 1 || decoded.Snapshots[0].Commit != "abc123" {
		t.Fatalf("snapshots not decoded: %#v", decoded.Snapshots)
	}
	if decoded.Snapshots[0].Content.Digest != "sha256:1111" {
		t.Fatalf("snapshot content digest = %q", decoded.Snapshots[0].Content.Digest)
	}
	if len(decoded.Facts) != 1 || decoded.Facts[0].Branch != "main" {
		t.Fatalf("facts not decoded: %#v", decoded.Facts)
	}

	// And such a newer-minor artifact is compatible with a warning.
	ok, warn, err := CheckCompatibility(decoded.Manifest.BrainSchemaVersion)
	if err != nil || !ok {
		t.Fatalf("CheckCompatibility(1.4) = (ok=%v, err=%v), want ok, no error", ok, err)
	}
	if !strings.Contains(warn, "tolerant reader") {
		t.Fatalf("expected tolerant-reader warning, got %q", warn)
	}
}

// TestLocalSchemaVersionParses guards the package invariant that the local
// BrainSchemaVersion constant is itself a valid "major.minor" version.
func TestLocalSchemaVersionParses(t *testing.T) {
	if _, _, err := parseSchemaVersion(BrainSchemaVersion); err != nil {
		t.Fatalf("BrainSchemaVersion %q is not valid major.minor: %v", BrainSchemaVersion, err)
	}
	ok, warn, err := CheckCompatibility(BrainSchemaVersion)
	if err != nil || !ok || warn != "" {
		t.Fatalf("CheckCompatibility(local) = (ok=%v, warn=%q, err=%v), want (true, \"\", nil)", ok, warn, err)
	}
}
