	offset := time.Date(2026, 6, 1, 17, 30, 0, 500000000, time.FixedZone("IST", 5*3600+1800))
	a := mustCanonicalMarshal(t, *NewBrainArtifact("r", "", sub))
	b := mustCanonicalMarshal(t, *NewBrainArtifact("r", "", whole))
