	if a != b || b != c {
		t.Fatalf("time normalization disagrees:\n sub=%s\nwhole=%s\noffset=%s", a, b, c)
	}
	if !strings.Contains(b, `"generated_at":"2026-06-01T12:00:00Z"`) {
		t.Fatalf("unexpected canonical time: %s", b)
	}
}

