		jsonB, _ := json.Marshal(b)
		if !bytes.Equal(jsonA, jsonB) {
			t.Fatalf("two byte strings verified under one signature decode to different artifacts:\nA=%q -> %s\nB=%q -> %s", rawA, jsonA, rawB, jsonB)
		}
	})
