	}
	if !strings.Contains(got, `"manifest":{"brain_schema_version":`) {
		t.Fatalf("manifest keys not lexicographic (want brain_schema_version first): %s", got)
	}
	if !strings.Contains(got, `"content":{"digest":"sha256:1111`) {
