	}
	var base, head, repo string
	for i := 0; i < len(args)-1; i++ {
		switch args[i] {
		case "--base":
			base = args[i+1]
		case "--head":
			head = args[i+1]
		case "--repo":
			repo = args[i+1]
		}
	}
	if repo == "" {
		repo = dir
	}
	stdout, stderr, err := runGitCmd(ctx, repo, "diff", "--name-status", base, head)
	if err != nil {
		return nil, stderr, fmt.Errorf("provider diff %s..%s: %w", short(base), short(head), err)
	}
