		Path:    "a.go",
		Changes: []graphEntityChange{{Type: "added", Kind: "function", Name: "Alpha", AfterStartLine: 3}},
	}))
	store := newTestStore(t)

	release, err := store.TryLock()
	if err != nil {
		t.Fatalf("hold the store lock: %v", err)
	}
	defer release()

