	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	later := now.Add(time.Hour)
	paths := NormalizePaths([]string{"project.tooling.stack"})
	id := RecordID("Uses Go 1.26", paths)
	base := Record{
		ID:         id,
		Paths:      paths,
		Text:       "Uses Go 1.26",
