	good := "{\"id\":\"fact:1\",\"paths\":[\"a.b.c\"],\"text\":\"x\",\"branch\":\"main\",\"origin\":\"authored\",\"status\":\"active\",\"provenance\":[],\"created_at\":\"2026-06-04T12:00:00Z\",\"updated_at\":\"2026-06-04T12:00:00Z\"}"
