===internal/factmerge/ndjson_batch_test.go===
package factmerge

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"unicode/utf8"
)

func utf8TestRecord(id string) Record {
	return Record{ID: id, Kind: "note", Text: "ok", Branch: "main", Status: "active"}
}

// TestWriteNDJSONWritesNothingWhenOneRecordIsUnwritable is the batch-abort fix.
//
// The UTF-8 refusal was applied INSIDE the write loop, so a batch stopped
// half-written: every record sorted before the bad one had already been handed
// to the writer, and every record after it was silently never attempted. A
// distill run that produced one fact with an invalid-UTF-8 path therefore
// aborted, and whatever the caller did with the partially-filled buffer was
// wrong either way -- truncated if it kept it, all-or-nothing lost if it did
// not.
//
// A writer that reports failure must leave the destination untouched, so the
// caller's retry is a retry and not a resume.
func TestWriteNDJSONWritesNothingWhenOneRecordIsUnwritable(t *testing.T) {
	bad := utf8TestRecord("bbb")
	bad.Paths = []string{"pkg/\xff\xfe.go"}
	records := []Record{utf8TestRecord("aaa"), bad, utf8TestRecord("ccc")}

	var buf bytes.Buffer
	err := WriteNDJSON(&buf, records)
	if err == nil {
		t.Fatal("an unwritable record was accepted")
	}
	if !errors.Is(err, ErrInvalidUTF8) {
		t.Fatalf("error = %v, want it to wrap ErrInvalidUTF8", err)
	}
	if buf.Len() != 0 {
		t.Fatalf("a failed WriteNDJSON left %d bytes behind; the batch must be all-or-nothing, got:\n%s", buf.Len(), buf.String())
	}
}

// TestWriteNDJSONErrorIdentifiesTheRecordToDrop: refusing the batch is only a
// usable answer if the caller can act on it. A formatted string cannot be acted
// on -- the caller would have to parse an error message to learn which of its
// records to drop, and a record whose own ID is the invalid field has no
// printable name at all. The typed error carries the record itself.
func TestWriteNDJSONErrorIdentifiesTheRecordToDrop(t *testing.T) {
	bad := utf8TestRecord("bbb")
	bad.Paths = []string{"pkg/\xff\xfe.go"}
	records := []Record{utf8TestRecord("aaa"), bad, utf8TestRecord("ccc")}

	var buf bytes.Buffer
	err := WriteNDJSON(&buf, records)
	var invalid *InvalidUTF8Error
	if !errors.As(err, &invalid) {
		t.Fatalf("error = %v (%T), want an *InvalidUTF8Error a caller can inspect", err, err)
	}
	if invalid.RecordID != "bbb" {
		t.Errorf("RecordID = %q, want %q", invalid.RecordID, "bbb")
	}
	if invalid.Field != "paths" {
		t.Errorf("Field = %q, want %q", invalid.Field, "paths")
	}
	// Index is into the SORTED slice WriteNDJSON just produced, which is the
	// caller's slice: it sorts in place. So the caller can drop exactly one
	// element without re-deriving which.
	if invalid.Index < 0 || invalid.Index >= len(records) {
		t.Fatalf("Index = %d, out of range for %d records", invalid.Index, len(records))
	}
	if records[invalid.Index].ID != "bbb" {
		t.Fatalf("records[%d].ID = %q, want the offending record %q", invalid.Index, records[invalid.Index].ID, "bbb")
	}

	// The documented recovery: drop that one record and retry. The retry must
	// then write every remaining record.
	kept := append(append([]Record{}, records[:invalid.Index]...), records[invalid.Index+1:]...)
	buf.Reset()
	if err := WriteNDJSON(&buf, kept); err != nil {
		t.Fatalf("retry after dropping the named record: %v", err)
	}
	got := strings.Count(strings.TrimSpace(buf.String()), "\n") + 1
	if got != len(kept) {
		t.Fatalf("retry wrote %d lines, want %d", got, len(kept))
	}
}

// TestWriteNDJSONErrorNamesAnUnprintableRecordID: when the invalid bytes are in
// the ID itself, the message must still be readable and must not smuggle raw
// invalid bytes into a log line.
func TestWriteNDJSONErrorNamesAnUnprintableRecordID(t *testing.T) {
	bad := utf8TestRecord("id-\xff\xfe")
	var buf bytes.Buffer
	err := WriteNDJSON(&buf, []Record{bad})
	var invalid *InvalidUTF8Error
	if !errors.As(err, &invalid) {
		t.Fatalf("error = %v, want an *InvalidUTF8Error", err)
	}
	if invalid.Field != "id" {
		t.Errorf("Field = %q, want %q", invalid.Field, "id")
	}
	if !utf8.ValidString(err.Error()) {
		t.Fatalf("error message carries raw invalid UTF-8: %q", err.Error())
	}
}

// TestWriteNDJSONOversizeRecordAlsoLeavesNothingBehind: the size ceiling had the
// same mid-write shape, so it gets the same all-or-nothing guarantee.
func TestWriteNDJSONOversizeRecordAlsoLeavesNothingBehind(t *testing.T) {
	huge := utf8TestRecord("zzz")
	huge.Text = strings.Repeat("x", MaxLineBytes+1)
	records := []Record{utf8TestRecord("aaa"), huge}

	var buf bytes.Buffer
	err := WriteNDJSON(&buf, records)
	if !errors.Is(err, ErrRecordTooLarge) {
		t.Fatalf("error = %v, want ErrRecordTooLarge", err)
	}
	if buf.Len() != 0 {
		t.Fatalf("a failed WriteNDJSON left %d bytes behind; the batch must be all-or-nothing", buf.Len())
	}
}

===internal/factmerge/ndjson_boundary_test.go===
package factmerge

import (
	"bytes"
	"encoding/json"
	"errors"
	"strings"
	"testing"
)

func TestNDJSONRecordSizeBoundary(t *testing.T) {
	base := Record{ID: "boundary"}
	raw, err := json.Marshal(base)
	if err != nil {
		t.Fatal(err)
	}
	for _, delta := range []int{-1, 0, 1} {
		record := base
		record.Text = strings.Repeat("x", MaxLineBytes-len(raw)+delta)
		var buf bytes.Buffer
		err := WriteNDJSON(&buf, []Record{record})
		if delta > 0 {
			if !errors.Is(err, ErrRecordTooLarge) {
				t.Fatalf("oversize write: %v", err)
			}
			raw, _ := json.Marshal(record)
			if _, err := ParseNDJSON(bytes.NewReader(raw)); err == nil {
				t.Fatal("oversize read accepted")
			}
			continue
		}
		if err != nil {
			t.Fatal(err)
		}
		for _, ending := range []string{"", "\n", "\r\n"} {
			input := append(bytes.TrimSuffix(buf.Bytes(), []byte("\n")), []byte(ending)...)
			got, err := ParseNDJSON(bytes.NewReader(input))
			if err != nil {
				t.Fatalf("delta=%d ending=%q: %v", delta, ending, err)
			}
			if len(got) != 1 || got[0].Text != record.Text {
				t.Fatal("round trip changed record")
			}
		}
	}
}

===internal/factmerge/ndjson_fuzz_test.go===
package factmerge

import (
	"bytes"
	"errors"
	"reflect"
	"strings"
	"testing"
	"time"
)

// The fact-set NDJSON blob is the shared, cross-member wire format (factsync
// pulls it from the hosted head and parses it with ParseNDJSON), so it becomes
// untrusted input the moment the brain is shared. These harnesses assert the two
// properties that matter for it: arbitrary bytes never panic, and anything the
// writer emits the reader can read back.
//
//	go test ./internal/factmerge -run xxx -fuzz FuzzParseNDJSON

func FuzzParseNDJSON(f *testing.F) {
	f.Add([]byte(`{"id":"fact:aa","paths":["a.b.c"],"text":"t","branch":"main","origin":"distilled","status":"active","provenance":[{"session_id":"s"}],"created_at":"2026-01-02T03:04:05Z","updated_at":"2026-01-02T03:04:05Z"}` + "\n"))
	f.Add([]byte("\n\n\n"))
	f.Add([]byte(`{"id":`))
	f.Add([]byte("\x00\x01 not json"))
	f.Add([]byte(`{"created_at":"not-a-time"}`))
	f.Add([]byte(`{"text":"` + strings.Repeat("<", MaxLineBytes/6+1) + `"}`))
	f.Add(append([]byte(`{"id":"`), append(bytes.Repeat([]byte("x"), 70*1024), []byte(`"}`)...)...))

	f.Fuzz(func(t *testing.T, data []byte) {
		records, err := ParseNDJSON(bytes.NewReader(data))
		if err != nil {
			return
		}
		// Re-encoding can expand a compact input through HTML escaping and
		// required fields. A size refusal is valid, but a successful write
		// must always be readable.
		var buf bytes.Buffer
		if err := WriteNDJSON(&buf, records); err != nil {
			if errors.Is(err, ErrRecordTooLarge) {
				if buf.Len() != 0 {
					t.Fatal("size refusal wrote a partial batch")
				}
				return
			}
			t.Fatalf("WriteNDJSON rejected records ParseNDJSON accepted: %v", err)
		}
		again, err := ParseNDJSON(bytes.NewReader(buf.Bytes()))
		if err != nil {
			t.Fatalf("ParseNDJSON rejected its own WriteNDJSON output: %v", err)
		}
		if len(again) != len(records) {
			t.Fatalf("round trip changed the record count: %d -> %d", len(records), len(again))
		}
	})
}

// FuzzNDJSONWriteReadRoundTrip drives the round trip from the STRUCT side: any
// record the store is willing to write must be readable back. A writer that can
// emit a line its own reader rejects is a store that bricks itself — and on the
// shared head, one member's oversized fact would brick every other member's sync.
func FuzzNDJSONWriteReadRoundTrip(f *testing.F) {
	f.Add("fact:aa", "a.b.c", "short text", "main", 1)
	f.Add("fact:bb", "a.b.c", strings.Repeat("x", 100*1024), "main", 1)
	f.Add("fact:cc", "a.b.c", "   unicode  ", "main", 3)

	f.Fuzz(func(t *testing.T, id, path, text, branch string, anchors int) {
		if anchors < 0 || anchors > 8 {
			return
		}
		rec := Record{
			ID:        id,
			Paths:     []string{path},
			Text:      text,
			Branch:    branch,
			Origin:    "distilled",
			Status:    StatusActive,
			CreatedAt: time.Unix(0, 0).UTC(),
			UpdatedAt: time.Unix(0, 0).UTC(),
		}
		for i := 0; i < anchors; i++ {
			rec.Provenance = append(rec.Provenance, Anchor{SessionID: "s"})
		}
		var buf bytes.Buffer
		if err := WriteNDJSON(&buf, []Record{rec}); err != nil {
			return // a record the writer refuses never reaches the store
		}
		got, err := ParseNDJSON(bytes.NewReader(buf.Bytes()))
		if err != nil {
			t.Fatalf("the reader rejected a record the writer emitted (%d bytes): %v", buf.Len(), err)
		}
		if len(got) != 1 || !reflect.DeepEqual(got[0], rec) {
			t.Fatalf("round trip changed the record:\nwant %#v\ngot  %#v", rec, got)
		}
	})
}

// FuzzRecordIdentity pins the content-addressing helpers: normalization must be
// idempotent and the derived id must be a pure function of the normalized form.
func FuzzRecordIdentity(f *testing.F) {
	f.Add("Some Fact Text", "a.b.c,d.e.f")
	f.Add("  spaced   out  ", "A.B.C,,zzz")
	f.Add("  ", "x")
	f.Fuzz(func(t *testing.T, text, rawPaths string) {
		paths := NormalizePaths(strings.Split(rawPaths, ","))
		if got := NormalizePaths(paths); !reflect.DeepEqual(got, paths) {
			t.Fatalf("NormalizePaths is not idempotent: %#v -> %#v", paths, got)
		}
		if NormalizeText(NormalizeText(text)) != NormalizeText(text) {
			t.Fatalf("NormalizeText is not idempotent for %q", text)
		}
		if RecordID(text, paths) != RecordID(NormalizeText(text), paths) {
			t.Fatalf("RecordID is not a function of the normalized text: %q", text)
		}
	})
}

