		t.Fatalf("round trips = %d, want %d", got, want)
	}

	refused := &nonTransientDialTransport{}
	h2 := &HTTPServer{BaseURL: "http://127.0.0.1:1", Token: "tok", Client: &http.Client{Transport: refused}}
