					w.WriteHeader(http.StatusPreconditionFailed)
					return
				case errors.Is(err, ErrNoChange):
					newFactsRef, _, _, _ = fake.facts.Current(ctx, "repo", body.Branch)
				case err != nil:
					w.WriteHeader(http.StatusBadRequest)
					return
				}
