				_ = json.NewEncoder(w).Encode(map[string]any{"ref": newRef, "version": 1, "changed": true})

			case r.Method == http.MethodPost && strings.HasSuffix(rest, "/resolve"):
				id := strings.TrimSuffix(rest, "/resolve")
