			_, err := h.ResolveProposal(ctx, ResolveProposalRequest{RepoID: "repo", Branch: "main", ProposalID: "prop-deadbeefdeadbeef", Facts: facts})
			if !errors.Is(err, ErrConflict) {
				t.Fatalf("ResolveProposal(409) = %v; want ErrConflict", err)
			}
