		{Action: "..", CandidateID: "..", TargetID: "..", Branch: "..", ProposedBy: ".."},
		{Action: "merge", CandidateID: "fact:ünïcøde", TargetID: "fact:%2f", Branch: "a b", ProposedBy: "m 3"},
	}
