	t.Helper()
	if got != want {
		t.Fatalf("request path = %q, want %q", got, want)
	}
	if cleaned := path.Clean(got); cleaned != got {
		t.Errorf("path %q is not in normal form: a normalizing hop rewrites it to %q", got, cleaned)
	}
}

