func TestProposalIDIsStableAndDiscriminating(t *testing.T) {
	base := factmerge.Proposal{Action: factmerge.ActionSupersede, CandidateID: "fact:c", TargetID: "fact:t", Branch: "main", ProposedBy: "member-B"}
