package factsync

import (
	"bytes"
	"context"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

func headFacts(t *testing.T, srv *fakeServer) []factmerge.Record {
	t.Helper()
	_, plaintext, found, err := srv.Current(context.Background(), "repo", "main")
	if err != nil {
		t.Fatalf("read head: %v", err)
	}
	if !found {
		return nil
	}
	head, err := factmerge.ParseNDJSON(bytes.NewReader(plaintext))
	if err != nil {
		t.Fatalf("parse head: %v", err)
	}
	return head
}

// A member who retracts a fact and syncs must have the retraction reach the
// shared head. Promote carries only ACTIVE source facts, so without an explicit
// retirement pass the merge is byte-identical to the head, Advance reports "no
// change", and every other member keeps reading a statement its owner declared
// false.
func TestSyncPropagatesRetraction(t *testing.T) {
	now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
	srv := &fakeServer{}
	f := fact("The service runs on port 8080.", []string{"project.tooling.stack"}, "s1", now)

	if _, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{f}, now); err != nil {
		t.Fatalf("initial sync: %v", err)
	}

	retracted := f
	retracted.Status = factmerge.StatusRetracted
	retracted.UpdatedAt = now.Add(time.Hour)
	res, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{retracted}, now.Add(time.Hour))
	if err != nil {
		t.Fatalf("retract sync: %v", err)
	}
	if !res.Published {
		t.Errorf("retraction sync reported no change; the head still carries the fact as active")
	}

	head := headFacts(t, srv)
	i := factmerge.IndexOf(head, f.ID)
	if i < 0 {
		t.Fatalf("the fact vanished from the head entirely: %+v", head)
	}
	if head[i].Status != factmerge.StatusRetracted {
		t.Fatalf("shared head still says %q after the owner retracted the fact", head[i].Status)
	}
	// Retiring must not drop the record's provenance.
	if len(head[i].Provenance) == 0 {
		t.Errorf("retired fact lost its provenance: %+v", head[i])
	}

	// Idempotent: syncing the same retired local state again changes nothing.
	again, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{retracted}, now.Add(2*time.Hour))
	if err != nil {
		t.Fatalf("second retract sync: %v", err)
	}
	if again.Published {
		t.Errorf("re-syncing an already-retired fact advanced the head again")
	}
}

// A supersede a member applied locally must reach the head too: the retired
// target flips to superseded and keeps pointing at the replacement, which is
// promoted alongside it.
func TestSyncPropagatesSupersede(t *testing.T) {
	now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
	srv := &fakeServer{}
	old := fact("The service runs on port 8080.", []string{"project.tooling.stack"}, "s1", now)

	if _, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{old}, now); err != nil {
		t.Fatalf("initial sync: %v", err)
	}

	replacement := fact("The service runs on port 9090.", []string{"project.tooling.stack"}, "s2", now.Add(time.Hour))
	retired := old
	retired.Status = factmerge.StatusSuperseded
	retired.SupersededBy = replacement.ID
	retired.UpdatedAt = now.Add(time.Hour)

	if _, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{retired, replacement}, now.Add(time.Hour)); err != nil {
		t.Fatalf("supersede sync: %v", err)
	}

	head := headFacts(t, srv)
	ti := factmerge.IndexOf(head, old.ID)
	if ti < 0 {
		t.Fatalf("superseded fact must be retained, not deleted: %+v", head)
	}
	if head[ti].Status != factmerge.StatusSuperseded || head[ti].SupersededBy != replacement.ID {
		t.Fatalf("head target not superseded: %+v", head[ti])
	}
	if factmerge.IndexOf(head, replacement.ID) < 0 {
		t.Fatalf("the replacement fact was not promoted: %+v", head)
	}
}

// Retiring must never REVIVE: a fact another member already retired on the head
// stays retired when this member still holds it as active.
func TestSyncDoesNotReviveHeadRetraction(t *testing.T) {
	now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
	srv := &fakeServer{}
	f := fact("The service runs on port 8080.", []string{"project.tooling.stack"}, "s1", now)

	if _, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{f}, now); err != nil {
		t.Fatalf("initial sync: %v", err)
	}
	retracted := f
	retracted.Status = factmerge.StatusRetracted
	if _, err := Sync(context.Background(), srv, "repo", "main", "alice@example.com", []factmerge.Record{retracted}, now.Add(time.Hour)); err != nil {
		t.Fatalf("retract sync: %v", err)
	}
	// A second member still carries it as active.
	if _, err := Sync(context.Background(), srv, "repo", "main", "bob@example.com", []factmerge.Record{f}, now.Add(2*time.Hour)); err != nil {
		t.Fatalf("peer sync: %v", err)
	}

	head := headFacts(t, srv)
	i := factmerge.IndexOf(head, f.ID)
	if i < 0 || head[i].Status != factmerge.StatusRetracted {
		t.Fatalf("a peer sync revived a retracted fact: %+v", head)
	}
}

===internal/factsync/review_test.go===
package factsync

import (
	"bytes"
	"context"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// advanceResolved pushes a resolved fact set to the head under CAS (what a reviewer's
// client does after Resolve): serialize, then Advance from the ref it read.
func advanceResolved(ctx context.Context, srv Server, oldRef string, facts []factmerge.Record) (string, error) {
	var buf bytes.Buffer
	if err := factmerge.WriteNDJSON(&buf, facts); err != nil {
		return "", err
	}
	return srv.Advance(ctx, "repo", "main", oldRef, buf.Bytes())
}

func headRecords(ctx context.Context, t *testing.T, srv Server) (string, []factmerge.Record) {
	t.Helper()
	ref, blob, found, err := srv.Current(ctx, "repo", "main")
	if err != nil || !found {
		t.Fatalf("Current: found=%v err=%v", found, err)
	}
	recs, err := factmerge.ParseNDJSON(bytes.NewReader(blob))
	if err != nil {
		t.Fatalf("parse head: %v", err)
	}
	return ref, recs
}

// TestCrossMemberConflictRoutedThenResolvedConverges is the M2.4 proof. Two members
// hold CONTRADICTORY facts on the same topic (same path, different text → different id).
// The second member's sync must NOT silently overwrite the first: it keeps both facts
// active and raises a review Proposal ROUTED to the member who raised it (ProposedBy).
// A reviewer then Accepts the supersede; advancing the resolved set converges every
// member's view (the losing fact retained as superseded, never deleted).
func TestCrossMemberConflictRoutedThenResolvedConverges(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	factX := fact("deploys use blue-green cutover", []string{"ops.deploy.strategy"}, "session-A", now)
	factY := fact("deploys use in-place rolling restart", []string{"ops.deploy.strategy"}, "session-B", now)
	if factX.ID == factY.ID {
		t.Fatal("test setup: contradictory facts must have different ids")
	}

	// Member A establishes the head — no conflict yet.
	resA, err := Sync(ctx, srv, "repo", "main", "member-A", []factmerge.Record{factX}, now)
	if err != nil {
		t.Fatalf("member-A sync: %v", err)
	}
	if len(resA.Proposals) != 0 {
		t.Fatalf("member-A raised %d proposals; want 0 (empty head, no conflict)", len(resA.Proposals))
	}

	// Member B syncs a CONTRADICTORY fact → keep-both + a routed proposal, no overwrite.
	resB, err := Sync(ctx, srv, "repo", "main", "member-B", []factmerge.Record{factY}, now)
	if err != nil {
		t.Fatalf("member-B sync: %v", err)
	}
	if len(resB.Proposals) != 1 {
		t.Fatalf("member-B raised %d proposals; want 1 (the contradiction)", len(resB.Proposals))
	}
	p := resB.Proposals[0]
	if p.ProposedBy != "member-B" {
		t.Fatalf("proposal ProposedBy = %q; want member-B (routing)", p.ProposedBy)
	}
	if p.Action != factmerge.ActionSupersede || p.CandidateID != factY.ID || p.TargetID != factX.ID {
		t.Fatalf("proposal = %+v; want supersede cand=%s target=%s", p, factY.ID, factX.ID)
	}

	// No silent overwrite: both facts are present and active in the head.
	_, recs := headRecords(ctx, t, srv)
	byID := map[string]factmerge.Record{}
	for _, r := range recs {
		byID[r.ID] = r
	}
	if byID[factX.ID].Status != factmerge.StatusActive || byID[factY.ID].Status != factmerge.StatusActive {
		t.Fatalf("post-conflict head must keep BOTH active; got X=%q Y=%q", byID[factX.ID].Status, byID[factY.ID].Status)
	}

	// A reviewer Accepts the supersede; advance the resolved set to converge everyone.
	ref, head := headRecords(ctx, t, srv)
	resolved, err := Resolve(head, p, Accept, now)
	if err != nil {
		t.Fatalf("Resolve(Accept): %v", err)
	}
	if _, err := advanceResolved(ctx, srv, ref, resolved); err != nil {
		t.Fatalf("advance resolved: %v", err)
	}

	// Converged: X retired (superseded by Y), Y active. Nothing deleted.
	_, final := headRecords(ctx, t, srv)
	fByID := map[string]factmerge.Record{}
	for _, r := range final {
		fByID[r.ID] = r
	}
	x, y := fByID[factX.ID], fByID[factY.ID]
	if x.Status != factmerge.StatusSuperseded || x.SupersededBy != factY.ID {
		t.Fatalf("after resolve, X = status %q supersededBy %q; want superseded by %s", x.Status, x.SupersededBy, factY.ID)
	}
	if y.Status != factmerge.StatusActive {
		t.Fatalf("after resolve, Y = status %q; want active", y.Status)
	}
}

// TestResolveRejectKeepsBothActive proves the Reject decision: a reviewer who judges the
// two contradictory facts as genuinely coexisting keeps both active and clears the
// cross-link — nothing dropped or superseded.
func TestResolveRejectKeepsBothActive(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	factX := fact("staging mirrors prod region", []string{"infra.staging.topology"}, "session-A", now)
	factY := fact("staging runs a single-node cluster", []string{"infra.staging.topology"}, "session-B", now)

	if _, err := Sync(ctx, srv, "repo", "main", "member-A", []factmerge.Record{factX}, now); err != nil {
		t.Fatal(err)
	}
	resB, err := Sync(ctx, srv, "repo", "main", "member-B", []factmerge.Record{factY}, now)
	if err != nil {
		t.Fatal(err)
	}
	if len(resB.Proposals) != 1 {
		t.Fatalf("want 1 proposal, got %d", len(resB.Proposals))
	}

	ref, head := headRecords(ctx, t, srv)
	resolved, err := Resolve(head, resB.Proposals[0], Reject, now)
	if err != nil {
		t.Fatalf("Resolve(Reject): %v", err)
	}
	if _, err := advanceResolved(ctx, srv, ref, resolved); err != nil {
		t.Fatalf("advance resolved: %v", err)
	}

	_, final := headRecords(ctx, t, srv)
	for _, r := range final {
		if r.Status != factmerge.StatusActive {
			t.Fatalf("reject must keep all active; %s = %q", r.ID, r.Status)
		}
	}
	if len(final) != 2 {
		t.Fatalf("reject head has %d facts; want 2 (both kept)", len(final))
	}
}

// TestSyncRequiresMemberID proves a blank memberID is rejected — otherwise a raised
// proposal would be stamped ProposedBy="" (dropped by omitempty) and be
// indistinguishable from a local one, losing cross-member routing.
func TestSyncRequiresMemberID(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)
	local := []factmerge.Record{fact("some fact", []string{"a.b.c"}, "s", now)}
	if _, err := Sync(ctx, srv, "repo", "main", "", local, now); err == nil {
		t.Fatal("Sync with empty memberID must error (routing requires it)")
	}
}

// TestResolveStaleProposalSurfaced proves Resolve does not silently no-op a proposal
// whose target/candidate has vanished (a concurrent resolution) — it returns
// ErrProposalNotApplicable so the caller re-reads and reconciles.
func TestResolveStaleProposalSurfaced(t *testing.T) {
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)
	facts := []factmerge.Record{fact("only remaining fact", []string{"misc.scratch.note"}, "s", now)}
	stale := factmerge.Proposal{Action: factmerge.ActionSupersede, CandidateID: "fact:gone", TargetID: "fact:also-gone"}
	if _, err := Resolve(facts, stale, Accept, now); err != ErrProposalNotApplicable {
		t.Fatalf("Resolve(stale, Accept) = %v; want ErrProposalNotApplicable", err)
	}
	if _, err := Resolve(facts, stale, Reject, now); err != ErrProposalNotApplicable {
		t.Fatalf("Resolve(stale, Reject) = %v; want ErrProposalNotApplicable", err)
	}
}

===internal/factsync/supersede_direction_test.go===
package factsync

import (
	"bytes"
	"context"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// An earlier note on this project flagged "promote supersede direction inverted
// (corrections lose to what they correct)". On this tree it does not reproduce, and
// this test is what keeps it that way — the direction is a one-word difference in
// factmerge.Promote and factmerge.ApplyProposal that nothing else would catch.
//
// The chain under test, end to end:
//
//	factsync.Sync         Promote(local, head, "keep-both") — source = THIS member's
//	                      facts, target = the shared head, so a conflict yields
//	                      Proposal{Candidate: the member's fact, Target: the head's}
//	factsync.Resolve      Accept routes to factmerge.ApplyProposal
//	factmerge.ApplyProposal
//	                      supersede retires the TARGET and points it at the CANDIDATE
//
// Net effect: accepting retires the statement that was already in the shared head
// and keeps the member's newer one. Inverting either half would make the correction
// the superseded record and leave the stale statement active — the exact failure the
// note described, and one that reads as a successful sync.

func mustRecord(t *testing.T, text, path, branch string, anchor factmerge.Anchor, now time.Time) factmerge.Record {
	t.Helper()
	r := factmerge.Record{
		Paths:      []string{path},
		Text:       text,
		Branch:     branch,
		Origin:     "distilled",
		Status:     factmerge.StatusActive,
		Provenance: []factmerge.Anchor{anchor},
		CreatedAt:  now,
		UpdatedAt:  now,
	}
	r.Paths = factmerge.NormalizePaths(r.Paths)
	r.ID = factmerge.RecordID(r.Text, r.Paths)
	return r
}

func TestAcceptingASyncRaisedProposalRetiresTheHeadFactNotTheCorrection(t *testing.T) {
	now := time.Date(2026, 6, 1, 12, 0, 0, 0, time.UTC)

	stale := mustRecord(t, "The service listens on port 8080.", "architecture.api.ports", "main",
		factmerge.Anchor{SessionID: "old-session"}, now.Add(-72*time.Hour))
	correction := mustRecord(t, "The service listens on port 9090 since the ingress move.", "architecture.api.ports", "main",
		factmerge.Anchor{SessionID: "new-session"}, now)

	srv := newDirectionFake(t, []factmerge.Record{stale})
	res, err := Sync(context.Background(), srv, "01HZZPROBE0000000000000000", "main", "member-a",
		[]factmerge.Record{correction}, now)
	if err != nil {
		t.Fatalf("Sync: %v", err)
	}
	if len(res.Proposals) != 1 {
		t.Fatalf("keep-both raised %d proposals, want 1 (the two statements conflict)", len(res.Proposals))
	}
	p := res.Proposals[0]
	if p.Action != factmerge.ActionSupersede {
		t.Fatalf("proposal action = %q, want %q", p.Action, factmerge.ActionSupersede)
	}
	if p.CandidateID != correction.ID {
		t.Errorf("candidate is %s; the member's own (correcting) fact %s must be the candidate", p.CandidateID, correction.ID)
	}
	if p.TargetID != stale.ID {
		t.Errorf("target is %s; the fact already in the shared head %s must be the target", p.TargetID, stale.ID)
	}

	// Accept it, and check which side actually lost.
	settled, err := Resolve(res.Facts, p, Accept, now)
	if err != nil {
		t.Fatalf("Resolve(Accept): %v", err)
	}
	byID := map[string]factmerge.Record{}
	for _, r := range settled {
		byID[r.ID] = r
	}
	got, ok := byID[stale.ID]
	if !ok {
		t.Fatal("the superseded fact was DELETED; keep-both retains it with Status=superseded (ADR-P1-G)")
	}
	if got.Status != factmerge.StatusSuperseded {
		t.Errorf("the stale head fact has status %q, want %q — the correction lost to what it corrects", got.Status, factmerge.StatusSuperseded)
	}
	if got.SupersededBy != correction.ID {
		t.Errorf("superseded_by = %q, want the correction %q", got.SupersededBy, correction.ID)
	}
	if kept, ok := byID[correction.ID]; !ok {
		t.Error("the correction is gone from the settled set")
	} else if kept.Status != factmerge.StatusActive {
		t.Errorf("the correction has status %q, want it to stay %q", kept.Status, factmerge.StatusActive)
	}
}

// directionFake is a minimal in-memory Server: the head starts at the given records
// and the first Advance wins.
type directionFake struct {
	t    *testing.T
	head []byte
	ref  string
}

func newDirectionFake(t *testing.T, head []factmerge.Record) *directionFake {
	t.Helper()
	f := &directionFake{t: t, ref: "ref-0"}
	if len(head) > 0 {
		var buf bytes.Buffer
		if err := factmerge.WriteNDJSON(&buf, head); err != nil {
			t.Fatal(err)
		}
		f.head = buf.Bytes()
	}
	return f
}

func (f *directionFake) Current(context.Context, string, string) (string, []byte, bool, error) {
	if len(f.head) == 0 {
		return "", nil, false, nil
	}
	return f.ref, f.head, true, nil
}

func (f *directionFake) Advance(_ context.Context, _, _, oldRef string, plaintext []byte) (string, error) {
	if oldRef != f.ref {
		return "", ErrConflict
	}
	f.head = plaintext
	f.ref = "ref-1"
	return f.ref, nil
}

