		"empty":              "",
		"blank":              "   ",
		"dot":                ".",
		"dotdot":             "..",
		"dotdot padded":      " .. ",
		"triple dot segment": "...",
		"slash":              "a/b",
		"leading slash":      "/admin",
		"trailing slash":     "repo/",
		"backslash":          `a\b`,
		"encoded slash":      "..%2f..",
		"query":              "x?admin=1",
		"fragment":           "x#frag",
		"space":              "repo 1",
		"percent":            "repo%41",
		"nul":                "repo\x00",
		"newline":            "repo\n",
		"traversal chain":    "../../admin",
	}
