					cursor++
				}
			}
			if _, duplicate := record.fields[key]; duplicate {
				t.Fatalf("duplicate field %q at line %d", key, lineNumber+2)
			}
			record.fields[key] = line[valueStart:cursor]
			if cursor < len(line) {
				cursor++
			}
		}
