	if err != nil || count < 0 || strconv.Itoa(count) != footer[1] {
		return nil, fmt.Errorf("footer count")
	}
	footerAt := strings.LastIndex(packet, "\nend\t")
	if footerAt < 0 {
		return nil, fmt.Errorf("footer boundary")

