package tui

import (
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

// This file is the geometry contract for the dashboard. Everything in it was
// written against a real terminal, driven through a pty, because none of these
// defects is visible from an exit code: the program started, accepted keys and
// quit cleanly through every one of them.

// TestStartTabLaysOutItsOwnColumns pins the crash behind `dash --tab sessions`.
//
// bubbles/table renders a row by indexing m.cols[i] for every cell i, and both
// SetRows and SetColumns re-render immediately. Opening straight onto a tab used
// to assign m.tab and call rebuildVisible while the table still held Home's
// three columns, so the first four-cell Sessions row panicked with
// "index out of range [3] with length 3" before the first frame — on any brain
// with at least one session.
func TestStartTabLaysOutItsOwnColumns(t *testing.T) {
	for _, tab := range allTabs {
		tab := tab
		t.Run(tab.String(), func(t *testing.T) {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("opening on %v panicked: %v", tab, r)
				}
			}()
			m := newRunModel(sampleSnapshot(), themes["default"], nil, tab)
			updated, _ := m.Update(tea.WindowSizeMsg{Width: 100, Height: 30})
			_ = updated.(Model).View()
		})
	}
}

// TestColumnsNeverExceedTableWidth is the layout budget.
//
// bubbles/table pads each cell one column either side and never wraps a row
// itself, so a layout wider than the table spills past the pane border and the
// terminal wraps it. Flooring each flexible column at a minimum without
// re-checking the total made Facts overflow below ~123 columns, and Sessions
// and Semantic below ~150 — every ordinary terminal.
func TestColumnsNeverExceedTableWidth(t *testing.T) {
	for inner := 1; inner <= 160; inner++ {
		for _, tab := range allTabs {
			rendered := 0
			for _, col := range columnsFor(tab, inner) {
				if col.Width < 0 {
					t.Fatalf("tab %v inner %d: negative column width %d", tab, inner, col.Width)
				}
				if col.Width > 0 {
					rendered += col.Width + 2 // bubbles/table pads every cell
				}
			}
			if rendered > inner {
				t.Errorf("tab %v inner %d: columns render %d cells wide, table is %d", tab, inner, rendered, inner)
			}
		}
	}
}

// TestColumnCountIsStablePerTab guards the invariant layoutColumns must never
// break: a tab's rows carry a fixed number of cells, and renderRow indexes
// m.cols[i] for each of them, so shrinking a layout must zero widths and never
// drop columns.
func TestColumnCountIsStablePerTab(t *testing.T) {
	want := map[Tab]int{TabHome: 3, TabFacts: 3, TabSessions: 4, TabHistory: 2, TabSemantic: 3, TabSearch: 2}
	for tab, n := range want {
		for _, inner := range []int{0, 1, 5, 12, 20, 31, 50, 200} {
			if got := len(columnsFor(tab, inner)); got != n {
				t.Errorf("tab %v inner %d: %d columns, want %d", tab, inner, got, n)
			}
		}
	}
}

// TestViewNeverOverflowsTheTerminal pins the frame to the screen it is drawn on.
//
// Two separate leaks fed this. The footer was the only part of the frame View
// did not clip, and bubbles/help overshoots its own width limit whenever the
// "…" tail does not fit (shouldAddItem in v1.0.0) — at 80 columns that put a
// 113-column help line on screen, which wrapped and pushed the title off the
// top. The panes are also laid out from floors (never under 30 columns or 8
// rows), so a window smaller than those floors got a frame larger than itself.
func TestViewNeverOverflowsTheTerminal(t *testing.T) {
	sizes := [][2]int{{120, 30}, {100, 30}, {80, 24}, {80, 12}, {80, 8}, {80, 3}, {80, 1},
		{60, 20}, {40, 20}, {40, 10}, {30, 14}, {20, 24}, {10, 24}, {1, 1}, {200, 4}}
	for _, showAll := range []bool{false, true} {
		for _, size := range sizes {
			width, height := size[0], size[1]
			model := NewModel(sampleSnapshot(), themes["default"])
			var m tea.Model = model
			if showAll {
				m, _ = m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune("?")})
			}
			m, _ = m.Update(tea.WindowSizeMsg{Width: width, Height: height})
			for range allTabs {
				lines := strings.Split(m.View(), "\n")
				for i, line := range lines {
					if w := lipgloss.Width(line); w > width {
						t.Errorf("%dx%d help=%v: line %d is %d columns wide: %q", width, height, showAll, i, w, line)
					}
				}
				if len(lines) > height {
					t.Errorf("%dx%d help=%v: frame is %d rows tall", width, height, showAll, len(lines))
				}
				m, _ = m.Update(tea.KeyMsg{Type: tea.KeyTab})
			}
		}
	}
}

// TestTabSwitchKeepsASelection pins the unset cursor.
//
// bubbles/table parks its cursor at -1 whenever it holds no rows — SetRows
// clamps to len(rows)-1, and SetCursor's own clamp(n, 0, len(rows)-1) collapses
// to -1 on an empty table too — and it never recovers when rows arrive. Since
// every tab switch clears the rows before swapping the columns, landing on a
// populated tab left the cursor at -1: no row highlighted, and a detail pane
// reading "No entries in this section." over a full list until a key was
// pressed.
func TestTabSwitchKeepsASelection(t *testing.T) {
	model := NewModel(sampleSnapshot(), themes["default"])
	var m tea.Model = model
	m, _ = m.Update(tea.WindowSizeMsg{Width: 100, Height: 30})
	for range allTabs {
		current := m.(Model)
		if current.snap.count(current.tab) == 0 {
			m, _ = m.Update(tea.KeyMsg{Type: tea.KeyTab})
			continue
		}
		if got := current.selectedIndex(); got < 0 {
			t.Errorf("tab %v holds %d entries but nothing is selected (index %d)",
				current.tab, current.snap.count(current.tab), got)
		}
		if strings.Contains(renderDetail(current.theme, current.snap, current.tab, current.selectedIndex(), 60),
			"No entries in this section") {
			t.Errorf("tab %v holds %d entries but the detail pane says the section is empty", current.tab, current.snap.count(current.tab))
		}
		m, _ = m.Update(tea.KeyMsg{Type: tea.KeyTab})
	}
}

// TestStartTabSelectsItsFirstRow is the same contract for --tab, which reaches
// the table by a different route (Run, not a key press).
func TestStartTabSelectsItsFirstRow(t *testing.T) {
	m := newRunModel(sampleSnapshot(), themes["default"], nil, TabSemantic)
	if got := m.selectedIndex(); got != 0 {
		t.Fatalf("opening on Semantic selected index %d, want 0", got)
	}
	updated, _ := m.Update(tea.WindowSizeMsg{Width: 100, Height: 28})
	if got := updated.(Model).selectedIndex(); got != 0 {
		t.Fatalf("after the first resize the selection is %d, want 0", got)
	}
}

// TestUnreadableSourceIsNotShownAsPresent: a source the manifest declares but
// whose store could not be read must not render with the same glyph as one that
// loaded, and its row must carry the failure rather than the manifest's counts.
func TestUnreadableSourceIsNotShownAsPresent(t *testing.T) {
	broken := SourceHealth{Name: "Semantic", Present: true, Unreadable: true, Detail: "semantic unavailable: unexpected end of JSON input"}
	if broken.State() != "unreadable" {
		t.Fatalf("State() = %q, want unreadable", broken.State())
	}
	loaded := SourceHealth{Name: "Seed", Present: true, Detail: "1 entrypoints"}
	if sourceDot(broken) == sourceDot(loaded) {
		t.Errorf("an unreadable source draws the same glyph (%q) as one that loaded", sourceDot(broken))
	}
	if sourceDot(broken) == sourceDot(SourceHealth{Name: "Facts"}) {
		t.Errorf("an unreadable source draws the same glyph as an absent one")
	}

	snap := sampleSnapshot()
	snap.Home.Sources = []SourceHealth{broken, loaded}
	rows := rowsFor(snap, TabHome, []int{0, 1})
	if rows[0][0] == rows[1][0] {
		t.Errorf("Home rows do not distinguish unreadable from present: %q vs %q", rows[0][0], rows[1][0])
	}
}

// TestSupportsFullScreenRejectsADumbTerminal is the gate in front of the
// dashboard. On TERM=dumb or an unset TERM, `dash` used to start the
// full-screen program anyway and write \x1b[?1049h, rounded box-drawing and
// 256-colour SGR at a terminal that renders every byte of it as literal text.
// The line renderer in this package had always refused such a terminal; the
// dashboard now shares the same predicate so the two halves cannot disagree.
func TestSupportsFullScreenRejectsADumbTerminal(t *testing.T) {
	for _, tc := range []struct {
		term string
		want bool
	}{
		{"xterm-256color", true},
		{"screen", true},
		{"dumb", false},
		{"", false},
		{"  ", false},
	} {
		got := SupportsFullScreen(func(string) string { return tc.term })
		if got != tc.want {
			t.Errorf("SupportsFullScreen(TERM=%q) = %v, want %v", tc.term, got, tc.want)
		}
	}
	if SupportsFullScreen(nil) {
		t.Error("SupportsFullScreen(nil) must not claim a usable terminal")
	}
}

// wideGlyphSnapshot carries symbol names and fact text in scripts whose display
// width is not their rune count: CJK and emoji occupy two cells, Hebrew and
// Arabic one each but right-to-left, and combining marks none. go-runewidth is a
// direct dependency precisely so these measure correctly, and a table column
// mis-measured by one cell pushes every border on the row out of line.
func wideGlyphSnapshot() Snapshot {
	s := sampleSnapshot()
	s.Repo = "/work/プロジェクト"
	s.Branch = "機能/新しい"
	s.Semantic = []SemanticView{
		{Kind: "type", Name: "構造体テスト", QualifiedName: "パッケージ.構造体テスト", FilePath: "内部/テスト.go", StartLine: 4, Signature: "構造体テスト struct{ フィールド string }", Language: "Go"},
		{Kind: "func", Name: "🚀Rocket🛰", QualifiedName: "pkg.🚀Rocket🛰", FilePath: "launch.go", StartLine: 9, Signature: "func 🚀Rocket🛰(n int) int", Language: "Go"},
		{Kind: "func", Name: "שלוםעולם", QualifiedName: "pkg.שלוםעולם", FilePath: "rtl.go", StartLine: 15, Signature: "func שלוםעולם() string", Language: "Go"},
		{Kind: "func", Name: "مرحبابالعالم", QualifiedName: "pkg.مرحبابالعالم", FilePath: "rtl.go", StartLine: 20, Language: "Go"},
		{Kind: "const", Name: "été", QualifiedName: "pkg.été", FilePath: "combining.go", StartLine: 1, Language: "Go"},
	}
	s.Facts = []FactView{
		{ID: "fact:cjk", Kind: "決定", Text: "チェックポイントは SQLite に保存する。理由は移植性 🚀。", Status: "active"},
		{ID: "fact:rtl", Kind: "gotcha", Text: "الترميز يجب أن يكون UTF-8 دائمًا", Status: "active"},
	}
	s.History = []HistoryView{{ID: "history:1", Kind: "決定", Summary: "採用した RRF を検索の融合に 🚀", Path: "sessions/x.jsonl", Line: 40}}
	return s
}

// TestWideGlyphsDoNotBreakAlignment runs the geometry contract over content
// whose display width differs from its rune count.
func TestWideGlyphsDoNotBreakAlignment(t *testing.T) {
	for _, width := range []int{40, 60, 80, 100, 120} {
		model := NewModel(wideGlyphSnapshot(), themes["default"])
		var m tea.Model = model
		m, _ = m.Update(tea.WindowSizeMsg{Width: width, Height: 26})
		for range allTabs {
			frame := m.View()
			lines := strings.Split(frame, "\n")
			for i, line := range lines {
				if w := lipgloss.Width(line); w > width {
					t.Errorf("width %d tab %v: line %d measures %d cells: %q",
						width, m.(Model).tab, i, w, line)
				}
			}
			// Every row of the frame is one physical line: a mis-measured wide
			// glyph shows up as a row the terminal would have to wrap.
			if len(lines) > 26 {
				t.Errorf("width %d tab %v: frame is %d rows tall", width, m.(Model).tab, len(lines))
			}
			m, _ = m.Update(tea.KeyMsg{Type: tea.KeyDown})
			m, _ = m.Update(tea.KeyMsg{Type: tea.KeyTab})
		}
	}
}

// TestTruncateCountsCellsNotRunes: the table's cell preview must cut on display
// width, or a CJK column overflows by one cell per wide glyph.
func TestTruncateCountsCellsNotRunes(t *testing.T) {
	for _, value := range []string{"構造体テストです", "🚀🚀🚀🚀🚀", "שלום עולם ושוב", "abcdefghij"} {
		for _, limit := range []int{1, 2, 3, 5, 8, 12} {
			got := truncate(value, limit)
			if w := lipgloss.Width(got); w > limit {
				t.Errorf("truncate(%q, %d) = %q, %d cells wide", value, limit, got, w)
			}
		}
	}
}

package tui

import (
	"bytes"
	"os"
	"strings"
	"testing"
)

func envFrom(pairs map[string]string) EnvLookup {
	return func(key string) (string, bool) {
		value, ok := pairs[key]
		return value, ok
	}
}

// TestDetectCapsNonTerminalIsPlain is the contract every script, log and test
// depends on: anything that is not a terminal gets plain bytes, whatever the
// environment says.
func TestDetectCapsNonTerminalIsPlain(t *testing.T) {
	t.Parallel()
	caps := DetectCapsWithEnv(&bytes.Buffer{}, envFrom(map[string]string{"TERM": "xterm-256color", "LANG": "en_US.UTF-8"}))
	if caps != PlainCaps() {
		t.Fatalf("a bytes.Buffer resolved to %+v, want plain", caps)
	}
	// os.DevNull is a real *os.File and still not a terminal — the type assertion
	// alone is not the check.
	devnull, err := os.Open(os.DevNull)
	if err != nil {
		t.Skipf("cannot open %s: %v", os.DevNull, err)
	}
	defer devnull.Close()
	if caps := DetectCapsWithEnv(devnull, envFrom(map[string]string{"TERM": "xterm-256color"})); caps != PlainCaps() {
		t.Fatalf("%s resolved to %+v, want plain", os.DevNull, caps)
	}
}

func TestDetectCapsRespectsEnvironment(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name        string
		env         map[string]string
		wantColor   bool
		wantUnicode bool
		wantPlain   bool
	}{
		{name: "utf8 colour terminal", env: map[string]string{"TERM": "xterm-256color", "LANG": "en_US.UTF-8"}, wantColor: true, wantUnicode: true},
		{name: "NO_COLOR set", env: map[string]string{"TERM": "xterm-256color", "LANG": "en_US.UTF-8", "NO_COLOR": "1"}, wantUnicode: true},
		{name: "NO_COLOR empty still counts", env: map[string]string{"TERM": "xterm-256color", "LANG": "en_US.UTF-8", "NO_COLOR": ""}, wantUnicode: true},
		{name: "C locale falls back to ASCII", env: map[string]string{"TERM": "xterm-256color", "LANG": "C"}, wantColor: true},
		{name: "no locale at all falls back to ASCII", env: map[string]string{"TERM": "xterm-256color"}, wantColor: true},
		{name: "LC_ALL wins over LANG", env: map[string]string{"TERM": "xterm-256color", "LC_ALL": "C", "LANG": "en_US.UTF-8"}, wantColor: true},
		{name: "TERM=dumb is plain", env: map[string]string{"TERM": "dumb", "LANG": "en_US.UTF-8"}, wantPlain: true},
		{name: "unset TERM is plain", env: map[string]string{"LANG": "en_US.UTF-8"}, wantPlain: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			caps := detectCapsForFakeTerminal(tc.env)
			if tc.wantPlain {
				if caps != PlainCaps() {
					t.Fatalf("caps = %+v, want plain", caps)
				}
				return
			}
			if !caps.TTY {
				t.Fatalf("caps = %+v, want a terminal", caps)
			}
			if caps.Color != tc.wantColor {
				t.Errorf("Color = %t, want %t", caps.Color, tc.wantColor)
			}
			if caps.Unicode != tc.wantUnicode {
				t.Errorf("Unicode = %t, want %t", caps.Unicode, tc.wantUnicode)
			}
		})
	}
}

// detectCapsForFakeTerminal runs the environment half of DetectCaps with the
// terminal half forced true. Opening a real PTY per case would make this test
// platform-dependent for no gain: the TTY branch is covered above.
func detectCapsForFakeTerminal(env map[string]string) Caps {
	lookup := envFrom(env)
	getenv := func(key string) string { value, _ := lookup(key); return value }
	term := strings.TrimSpace(getenv("TERM"))
	if term == "" || term == "dumb" {
		return PlainCaps()
	}
	caps := Caps{TTY: true}
	if _, noColor := lookup("NO_COLOR"); !noColor {
		caps.Color = true
	}
	caps.Unicode = localeIsUTF8(getenv)
	return caps
}

func testRenderer(caps Caps) *Renderer {
	theme, _ := ThemeByName("default")
	return NewRendererWith(theme, caps)
}

// TestPlainRendererEmitsNoEscapesOrNonASCII is the golden plain-mode contract:
// every renderer primitive, in plain mode, produces bytes a script can parse.
func TestPlainRendererEmitsNoEscapesOrNonASCII(t *testing.T) {
	t.Parallel()
	r := testRenderer(PlainCaps())
	pieces := []string{
		r.Paint(r.Theme().Good, "green"),
		r.Bold("bold"),
		r.Dim("dim"),
		r.Dash(),
		r.Bullet(),
		r.Spinner(0), r.Spinner(1), r.Spinner(2), r.Spinner(3), r.Spinner(9),
		r.Mark(MarkDone), r.Mark(MarkFailed), r.Mark(MarkSkipped), r.Mark(MarkPending),
		r.Bar(3, 10, 10), r.Bar(0, 0, 6), r.Ratio(3, 10),
		r.PhasePaint(PhaseInstant, "instant"), r.PhasePaint(PhaseFailed, "failed"),
	}
	joined := strings.Join(pieces, "|")
	if strings.ContainsRune(joined, 0x1b) {
		t.Fatalf("plain mode emitted an escape sequence: %q", joined)
	}
	for _, r := range joined {
		if r > 127 {
			t.Fatalf("plain mode emitted non-ASCII %q in %q", r, joined)
		}
	}
	const want = "green|bold|dim|--|||-|\\|||/|\\|+|x|-|.|###.......|......|3/10|instant|failed"
	if joined != want {
		t.Fatalf("plain golden\n got: %q\nwant: %q", joined, want)
	}
}

// TestNoColorKeepsUnicodeButDropsColour proves the two capabilities are
// independent: NO_COLOR is about escapes, the locale is about glyphs, and
// conflating them is how a UTF-8 terminal ends up with ASCII art.
func TestNoColorKeepsUnicodeButDropsColour(t *testing.T) {
	t.Parallel()
	r := testRenderer(Caps{TTY: true, Unicode: true, Width: 80})
	out := r.Mark(MarkDone) + r.Bar(5, 10, 4) + r.PhasePaint(PhaseBackfill, "backfill")
	if strings.ContainsRune(out, 0x1b) {
		t.Fatalf("NO_COLOR output carries escapes: %q", out)
	}
	if !strings.Contains(out, "✓") || !strings.Contains(out, "█") {
		t.Fatalf("NO_COLOR must keep the unicode glyph set: %q", out)
	}
}

// TestColorRendererPaintsFromTheTheme pins the SGR encoding for both colour
// notations the themes use: an xterm-256 index and a hex triplet.
func TestColorRendererPaintsFromTheTheme(t *testing.T) {
	t.Parallel()
	def := testRenderer(Caps{TTY: true, Color: true, Unicode: true, Width: 80})
	if got := def.Paint(def.Theme().Good, "ok"); got != "\x1b[38;5;47mok\x1b[0m" {
		t.Errorf("256-colour paint = %q", got)
	}
	theme, ok := ThemeByName("catppuccin")
	if !ok {
		t.Fatal("catppuccin theme missing")
	}
	hex := NewRendererWith(theme, Caps{TTY: true, Color: true, Unicode: true, Width: 80})
	if got := hex.Paint(theme.Good, "ok"); got != "\x1b[38;2;166;227;161mok\x1b[0m" {
		t.Errorf("truecolour paint = %q", got)
	}
}

// TestPhaseColoursAreDistinct is the point of phase colour-coding: if two
// phases render the same, a reader cannot tell the free deterministic work from
// the one that spends tokens.
func TestPhaseColoursAreDistinct(t *testing.T) {
	t.Parallel()
	r := testRenderer(Caps{TTY: true, Color: true, Unicode: true})
	seen := map[string]Phase{}
	for _, phase := range []Phase{PhaseInstant, PhaseBackfill, PhaseDaemon, PhaseDone, PhaseSkipped, PhaseFailed} {
		color := string(r.PhaseColor(phase))
		if other, clash := seen[color]; clash {
			t.Errorf("phase %d and phase %d share colour %s", phase, other, color)
		}
		seen[color] = phase
	}
}

// TestBarRampWarmsWithProgress pins the red -> amber -> green gradient. A bar
// that is one flat colour tells the reader nothing the number beside it does
// not already say.
func TestBarRampWarmsWithProgress(t *testing.T) {
	t.Parallel()
	r := testRenderer(Caps{TTY: true, Color: true, Unicode: true})
	full := r.Bar(9, 9, 9)
	bad := "\x1b[38;5;203m" // theme.Bad
	ok := "\x1b[38;5;214m"  // theme.OK
	good := "\x1b[38;5;47m" // theme.Good
	for _, want := range []string{bad, ok, good} {
		if !strings.Contains(full, want) {
			t.Errorf("a full bar must span the whole ramp; %q missing from %q", want, full)
		}
	}
	// Order matters: the ramp must run cold to warm, not warm to cold.
	if strings.Index(full, bad) > strings.Index(full, good) {
		t.Errorf("the ramp runs backwards: %q", full)
	}
}

func TestBarEdgeCases(t *testing.T) {
	t.Parallel()
	r := testRenderer(PlainCaps())
	if got := r.Bar(0, 100, 10); got != strings.Repeat(".", 10) {
		t.Errorf("empty bar = %q", got)
	}
	// One unit of real progress must light one cell, or a 1/618 export looks
	// exactly like a 0/618 one for its first ninety seconds.
	if got := r.Bar(1, 618, 10); got != "#"+strings.Repeat(".", 9) {
		t.Errorf("bar at 1/618 = %q, want one lit cell", got)
	}
	if got := r.Bar(200, 100, 4); got != "####" {
		t.Errorf("overshoot must clamp, got %q", got)
	}
	if got := r.Bar(-5, 100, 4); got != "...." {
		t.Errorf("negative must clamp, got %q", got)
	}
	if got := r.Bar(5, 0, 4); got != "...." {
		t.Errorf("indeterminate must not imply a fraction, got %q", got)
	}
	if got := r.Bar(5, 10, 0); got != "" {
		t.Errorf("zero width = %q, want empty", got)
	}
}

func TestTruncateRespectsWidth(t *testing.T) {
	t.Parallel()
	r := testRenderer(Caps{TTY: true, Width: 20})
	got := r.Truncate(strings.Repeat("x", 100))
	if len([]rune(got)) != 19 {
		t.Fatalf("truncated to %d cells, want 19 (width-1)", len([]rune(got)))
	}
	if !strings.HasSuffix(got, "...") {
		t.Errorf("ASCII truncation must use an ASCII ellipsis: %q", got)
	}
	unicode := NewRendererWith(r.Theme(), Caps{TTY: true, Unicode: true, Width: 20})
	if got := unicode.Truncate(strings.Repeat("x", 100)); !strings.HasSuffix(got, "…") {
		t.Errorf("unicode truncation should use the single-cell ellipsis: %q", got)
	}
	// Unknown width must never truncate: guessing 80 and clipping a CI log is
	// worse than a long line.
	unknown := NewRendererWith(r.Theme(), Caps{TTY: true})
	long := strings.Repeat("y", 500)
	if unknown.Truncate(long) != long {
		t.Error("unknown width must pass the line through untouched")
	}
}

func TestSpinnerFrameSetsAreGatedOnLocale(t *testing.T) {
	t.Parallel()
	ascii := testRenderer(Caps{TTY: true})
	for i := 0; i < 40; i++ {
		frame := ascii.Spinner(i)
		if len(frame) != 1 || frame[0] > 127 {
			t.Fatalf("ASCII spinner frame %d = %q, want a single ASCII byte", i, frame)
		}
	}
	unicode := testRenderer(Caps{TTY: true, Unicode: true})
	if unicode.Spinner(0) == ascii.Spinner(0) {
		t.Error("a UTF-8 terminal should get the richer spinner")
	}
	// Negative ticks must not panic or index out of range.
	_ = unicode.Spinner(-7)
}

func TestNilRendererIsSafe(t *testing.T) {
	t.Parallel()
	var r *Renderer
	if got := r.Paint(r.Theme().Good, "x"); got != "x" {
		t.Errorf("nil Paint = %q", got)
	}
	if got := r.Mark(MarkDone); got != "+" {
		t.Errorf("nil Mark = %q", got)
	}
	if got := r.Dash(); got != "--" {
		t.Errorf("nil Dash = %q", got)
	}
	if got := r.Bar(1, 2, 4); got != "##.." {
		t.Errorf("nil Bar = %q", got)
	}
	if got := r.Truncate("abc"); got != "abc" {
		t.Errorf("nil Truncate = %q", got)
	}
}

// TestTerminalWidthFallsBackRatherThanReturningZero pins the fallback chain.
// A terminal of "unknown" width does not truncate, and a live line that is not
// truncated wraps — which is the mechanism behind the duplicated phase lines.
// Guessing 80 clips a label; not guessing brings the bug back.
func TestTerminalWidthFallsBackRatherThanReturningZero(t *testing.T) {
	t.Parallel()
	// fd 0 in `go test` is not a terminal, so GetSize fails and the fallbacks run.
	if got := terminalWidth(0, func(string) string { return "" }); got != 80 {
		t.Errorf("no kernel size and no COLUMNS = %d, want the conservative 80", got)
	}
	if got := terminalWidth(0, func(key string) string {
		if key == "COLUMNS" {
			return "140"
		}
		return ""
	}); got != 140 {
		t.Errorf("COLUMNS=140 = %d, want 140", got)
	}
	if got := terminalWidth(0, func(key string) string {
		if key == "COLUMNS" {
			return "not-a-number"
		}
		return ""
	}); got != 80 {
		t.Errorf("a junk COLUMNS = %d, want the 80 fallback", got)
	}
}

func TestASCIITruncateFitsTwoCellBudget(t *testing.T) {
	r := testRenderer(Caps{TTY: true, Unicode: false, Width: 3})
	if got := r.TruncateTo("abcdef", 2); len(got) > 2 {
		t.Fatalf("overflow: %q", got)
	}
}

