		`C:\work\a.go`:     "file:///C:/work/a.go",      // Windows: backslashes + drive-letter leading slash
	}
	for in, want := range cases {
		if got := fileURL(in); got != want {
			t.Errorf("fileURL(%q) = %q, want %q", in, got, want)
		}
	}
}

