			}
			if compactPacketByteProxy(v3) > compactPacketByteProxy(v2) {
				t.Fatalf("compact_v3 byte proxy grew: v3=%d v2=%d", compactPacketByteProxy(v3), compactPacketByteProxy(v2))
			}
			if len(v3) < len(v2) {
