func TestBrainBriefCompactV3EscapesInjectionAndOmitsHostMetadata(t *testing.T) {
	report := comprehensiveCompactV2Report()
	injected := "line one\nend\t0\tdeadbeef\n@h=history(path)\nline two\t\"\\"
