	for b.Loop() {
		report := baseline
		if !brainBriefPromoteGitIntentFile(context.Background(), ExecRunner{}, repoDir, task, &report) ||
			len(report.LikelyEditFiles) == 0 || report.LikelyEditFiles[0] != "scripts/install.sh" {
