func TestBrainBriefActionTargetsAddRelevantGoPrefixTest(t *testing.T) {
	repoDir := t.TempDir()
	writeBrainBriefGoLayoutFile(t, repoDir, "internal/cli/history.go", "package cli\n")
	for _, path := range []string{
		"internal/cli/history_cache_test.go",
