	brainBriefPrioritizeActionTargets(repoDir, &report)
	wantTests := []string{
		"src/test/java/com/acme/auth/TokenServiceTest.java",
		"src/test/java/com/acme/noise/OneTest.java",
		"src/test/java/com/acme/noise/TwoTest.java",
