	}
	object, ok := value.(map[string]any)
	if !ok {
		t.Fatalf("profile field %q is %T, want object", objectName, value)
	}
	for _, field := range fields {
		if _, ok := object[field]; !ok {
			t.Errorf("profile object %q missing field %q", objectName, field)
		}
	}
}

