	}
	if got := strings.Count(packet, "\no\t") + strings.Count(packet, "\ntest_root "); got != 0 {
		t.Fatalf("context-duplicate test roots = %d, want 0:\n%s", got, packet)
	}
	if got := strings.Count(packet, "\ntest_suggestion "); got > 1 {
