		Live: brainLiveState{Head: current},
		Semantic: &brainStatusSemantic{Freshness: &staleReport{
			Severity: "unsafe",
			Axes: map[string]staleAxis{
				"head": {State: "stale", Indexed: indexed, Current: current},
