	status := brainBriefPostIndexStatus(t.TempDir(), strings.Repeat("a", 40), strings.Repeat("b", 40))
	r := &brainBriefPostIndexDeadlineRunner{}
	brainBriefPostIndexFiles(context.Background(), r, status, "fix auth token expiry")
