// factsAvailabilityFixture builds a brain that really holds one authored fact
// on the checked-out branch, with the fact source manifest derived from disk.
func factsAvailabilityFixture(t *testing.T) (Options, string, string) {
	t.Helper()
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	env.RepoRoot = repoDir
	runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
	now := time.Date(2026, 8, 10, 2, 0, 0, 0, time.UTC)
	opts := Options{Version: "test", Env: env, Runner: runner, Now: func() time.Time { return now }}
	storage, err := repoStoragePaths(context.Background(), runner, env, repoDir)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(storage.BrainDir, 0o700); err != nil {
		t.Fatal(err)
	}
	// "feature" is the branch semanticFixtureRunner reports as checked out, so
	// brief and recall both resolve to this store.
	facts := []factRecord{{
		ID:         "fact-1",
		Paths:      []string{"project.tooling.stack"},
		Text:       "the alpha subsystem stores checkpoints in postgres",
		Branch:     "feature",
		Origin:     factOriginAuthored,
		Status:     factStatusActive,
		Provenance: []factAnchor{{SessionID: "session-1"}},
		CreatedAt:  now,
		UpdatedAt:  now,
	}}
	if err := writeFacts(storage.BrainDir, "feature", facts); err != nil {
		t.Fatal(err)
	}
	if err := updateFactSourceManifest(storage.BrainDir, now); err != nil {
		t.Fatal(err)
	}
	return opts, repoDir, storage.BrainDir
}

func removeFactStore(t *testing.T, brainDir, branch string) {
	t.Helper()
	if err := os.Remove(filepath.Join(brainDir, filepath.FromSlash(factsFileRelPath(branch)))); err != nil {
		t.Fatal(err)
	}
}

// TestStatusReportsDeclaredFactBranchWithMissingStore is the honesty contract:
// the manifest's fact counts are a claim about branches, not about files.
// loadFacts reads an absent store as an empty branch, so when the store is gone
// status/brain_status keep reporting "facts: 1 across 1 branch(es)" while every
// recall surface returns nothing. The caller must be told.
func TestStatusReportsDeclaredFactBranchWithMissingStore(t *testing.T) {
	opts, repoDir, brainDir := factsAvailabilityFixture(t)

	healthy, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
	if err != nil {
		t.Fatalf("healthy status: %v", err)
	}
	if healthy.Facts == nil || healthy.Facts.Facts != 1 {
		t.Fatalf("healthy status facts = %+v, want 1 fact", healthy.Facts)
	}
	if got := statusFactsMissingBranches(t, healthy); len(got) != 0 {
		t.Fatalf("healthy status reports missing fact branches: %v", got)
	}

	removeFactStore(t, brainDir, "feature")

	// Prove the facts layer is really dead before asserting what status says.
	recallOut, err := execute(t, NewRootCommand(opts), "recall", "postgres", "--branch", "feature")
	if err != nil {
		t.Fatalf("recall after store removal: %v\n%s", err, recallOut)
	}
	if strings.Contains(recallOut, "fact-1") {
		t.Fatalf("recall still returned the fact after its store was removed:\n%s", recallOut)
	}

	degraded, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
	if err != nil {
		t.Fatalf("degraded status: %v", err)
	}
	if degraded.Facts == nil {
		t.Fatalf("degraded status dropped the facts section")
	}
	if got := statusFactsMissingBranches(t, degraded); len(got) != 1 || got[0] != "feature" {
		t.Fatalf("status facts.missing_branches = %v, want [feature]", got)
	}
	if !warningsMention(degraded.Warnings, "feature") {
		t.Fatalf("status warnings do not name the unreadable fact branch: %v", degraded.Warnings)
	}

	statusOut, err := execute(t, NewRootCommand(opts), "status")
	if err != nil {
		t.Fatalf("status: %v\n%s", err, statusOut)
	}
	if !strings.Contains(statusOut, factsFileName) {
		t.Fatalf("status output does not report the missing fact store:\n%s", statusOut)
	}

	// The MCP tool result is the surface an agent actually reads.
	var mcpOut bytes.Buffer
	input := frameMCP(`{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"brain_status","arguments":{}}}`)
	if err := runMCP(context.Background(), strings.NewReader(input), &mcpOut, opts); err != nil {
		t.Fatalf("MCP brain_status: %v", err)
	}
	responses := readMCPResponses(t, mcpOut.String())
	if len(responses) != 1 {
		t.Fatalf("MCP responses = %d", len(responses))
	}
	payload := mcpTextJSONPayload(t, responses[0])
	mcpFacts, _ := payload["facts"].(map[string]any)
	if mcpFacts == nil {
		t.Fatalf("MCP brain_status dropped the facts section: %#v", payload)
	}
	branches, _ := mcpFacts["missing_branches"].([]any)
	if len(branches) != 1 || branches[0] != "feature" {
		t.Fatalf("MCP brain_status facts.missing_branches = %#v, want [feature]", mcpFacts["missing_branches"])
	}
}

// TestBrainBriefWarnsWhenFactStoreIsMissing pins the packet surface: a brief
// that contributes zero facts from a source it reports as present must say why.
func TestBrainBriefWarnsWhenFactStoreIsMissing(t *testing.T) {
	opts, _, brainDir := factsAvailabilityFixture(t)

	out, err := execute(t, NewRootCommand(opts), "brief", "postgres checkpoint storage", "--json")
	if err != nil {
		t.Fatalf("healthy brief: %v\n%s", err, out)
	}
	if !strings.Contains(out, "fact-1") {
		t.Fatalf("healthy brief did not carry the fact:\n%s", out)
	}

	removeFactStore(t, brainDir, "feature")

	degraded, err := execute(t, NewRootCommand(opts), "brief", "postgres checkpoint storage", "--json")
	if err != nil {
		t.Fatalf("degraded brief: %v\n%s", err, degraded)
	}
	if strings.Contains(degraded, "fact-1") {
		t.Fatalf("degraded brief still carried the fact:\n%s", degraded)
	}
	if !strings.Contains(degraded, factsFileName) {
		t.Fatalf("brief reported a present facts source that contributed nothing, with no warning:\n%s", degraded)
	}
}

// TestDoctorReportsDeclaredFactBranchWithMissingStore pins the second required
// surface: doctor must not pass while a declared source is silently dead.
func TestDoctorReportsDeclaredFactBranchWithMissingStore(t *testing.T) {
	opts, repoDir, brainDir := factsAvailabilityFixture(t)

	checks, _ := brainDoctorReadOnlyReport(context.Background(), opts, repoDir)
	state, ok := factsDoctorCheckState(checks)
	if !ok || state != "ok" {
		t.Fatalf("healthy doctor facts = %q present=%v, want ok", state, ok)
	}

	removeFactStore(t, brainDir, "feature")
	checks, _ = brainDoctorReadOnlyReport(context.Background(), opts, repoDir)
	state, ok = factsDoctorCheckState(checks)
	if !ok {
		t.Fatalf("doctor has no facts check with the store absent: %+v", checks)
	}
	if state == "ok" {
		t.Fatalf("doctor facts still ok with the declared branch store absent")
	}
}

// statusFactsMissingBranches reads the facts section straight out of the
// serialized status contract, which is what every JSON/MCP caller sees.
func statusFactsMissingBranches(t *testing.T, report brainStatusReport) []string {
	t.Helper()
	data, err := json.Marshal(report.Facts)
	if err != nil {
		t.Fatalf("marshal status facts: %v", err)
	}
	var payload struct {
		MissingBranches []string `json:"missing_branches"`
	}
	if err := json.Unmarshal(data, &payload); err != nil {
		t.Fatalf("decode status facts: %v", err)
	}
	return payload.MissingBranches
}

func factsDoctorCheckState(checks []doctorCheckResult) (string, bool) {
	for _, check := range checks {
		if check.Name == "facts" {
			return check.State, true
		}
	}
	return "", false
}

func warningsMention(warnings []string, needle string) bool {
	for _, warning := range warnings {
		if strings.Contains(warning, needle) {
			return true
		}
	}
	return false
}
package cli

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/agentsetup"
)

// Only aggregate shape information comes from the cohort. Every value below is
// synthetic. Session metadata is deliberately repeated through the production
// session aliases, as it is in retained manifests.
func TestBrainManifestObservedShapesRoundTrip(t *testing.T) {
	for _, tc := range []struct {
		name                                string
		branches, sessions, warnings, bytes int
	}{
		{"session-heavy", 870, 5305, 111, 18569433},
		{"warning-heavy", 389, 2633, 6238, 17220291},
		{"larger-than-default-read-limit", 1800, 20000, 12000, 80 << 20},
	} {
		t.Run(tc.name, func(t *testing.T) {
			repo := t.TempDir()
			key, err := localRepoStorageKey(repo)
			if err != nil {
				t.Fatal(err)
			}
			dataDir := t.TempDir()
			dir := filepath.Join(dataDir, "repos", filepath.FromSlash(key))
			source := &sessionSourceManifest{}
			for i := 0; i < tc.branches; i++ {
				source.Branches = append(source.Branches, exportBranch{Branch: fmt.Sprintf("branch-%d", i), Directory: fmt.Sprintf("sessions/branch-%d", i), SessionCount: 1})
			}
			for i := 0; i < tc.sessions; i++ {
				source.Sessions = append(source.Sessions, exportSession{SessionID: fmt.Sprintf("session-%d", i), Branch: "main", LatestCheckpoint: fmt.Sprintf("%012x", i), TranscriptPath: fmt.Sprintf("sessions/main/session-%d.jsonl", i), Summary: &checkpointSummary{Intent: strings.Repeat("synthetic intent ", 30), Outcome: "synthetic outcome"}, FilesTouched: []string{"internal/example.go"}})
			}
			for i := 0; i < tc.warnings; i++ {
				source.Warnings = append(source.Warnings, fmt.Sprintf("synthetic checkpoint coverage warning %d", i))
			}
			manifest := exportManifest{SchemaVersion: brainManifestSchemaVersion, RepoKey: key, Sources: &brainSources{Sessions: source, Seed: &seedSourceManifest{}, Semantic: &semanticSourceManifest{}, History: &historySourceManifest{}, Docs: &docSourceManifest{}}}
			if tc.name != "warning-heavy" {
				manifest.Sources.Patterns = &patternSourceManifest{}
			}
			applySessionSourceAliases(&manifest)
			// Distribute synthetic metadata across session summaries; only a small
			// remainder goes in a known scalar to match exact observed byte sizes.
			manifest.BrainVersion = "x"
			normalizeBrainManifest(&manifest)
			data, err := json.MarshalIndent(manifest, "", "  ")
			if err != nil {
				t.Fatal(err)
			}
			padding := tc.bytes - len(data) - 1
			if padding < 0 {
				t.Fatalf("fixture already exceeds target by %d", -padding)
			}
			perSession := padding / (2 * tc.sessions)
			for i := range source.Sessions {
				source.Sessions[i].Summary.Outcome += strings.Repeat("x", perSession)
			}
			manifest.BrainVersion += strings.Repeat("x", padding%(2*tc.sessions))
			if err := writeBrainManifestAndReadme(dir, manifest); err != nil {
				t.Fatal(err)
			}
			info, err := os.Stat(filepath.Join(dir, exportManifestFileName))
			if err != nil || info.Size() != int64(tc.bytes) {
				t.Fatalf("size: %v, %v", info, err)
			}
			for _, reader := range []func(string) (*exportManifest, error){loadBrainManifest, loadBrainManifestForReplace} {
				got, err := reader(dir)
				if err != nil {
					t.Fatal(err)
				}
				if !reflect.DeepEqual(got, &manifest) {
					t.Fatal("manifest records changed during round trip")
				}
			}
			got, health, issue := inspectBrainManifestHealth(dir)
			if issue != nil || health.State != "current" || len(got.Sessions) != tc.sessions {
				t.Fatalf("health failed: %+v", health)
			}
			// A stored manifest must not activate Brain agent guidance.
			setupOpts := agentsetup.Options{DataDir: dataDir, StateDir: t.TempDir(), ConfigDir: t.TempDir(), ListPlugins: func() (string, error) {
				return "Managed plugin directory: /fixture\n\n  brain v1.0.0 → /fixture/entire-brain\n  graph v1.0.0 → /fixture/entire-graph\n", nil
			}}
			render := func() (string, error) { return agentsetup.Preview(repo, "graph", setupOpts) }
			guide, err := render()
			if err != nil || notGraphOnly(guide) {
				t.Fatalf("manifest affected agent activation: %v", err)
			}
			if err := agentsetup.Install(repo, render, io.Discard); err != nil {
				t.Fatal(err)
			}
			// Exercise replacement's strict read of the existing oversized manifest.
			if err := writeBrainManifestAndReadme(dir, *got); err != nil {
				t.Fatal(err)
			}
			before, err := os.ReadFile(filepath.Join(dir, exportManifestFileName))
			if err != nil {
				t.Fatal(err)
			}
			got.GeneratedAt = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
			if err := writeBrainManifestAndReadme(dir, *got); err == nil {
				t.Fatal("invalid time must fail encoding")
			}
			after, err := os.ReadFile(filepath.Join(dir, exportManifestFileName))
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(before, after) {
				t.Fatal("failed operation changed previous manifest")
			}
			if _, err := loadBrainManifest(dir); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestBrainManifestDecoderCompatibility(t *testing.T) {
	for _, tc := range []struct{ name, body, code string }{
		{"v1", `{"schema_version":1}`, ""},
		{"v2", `{"schema_version":2}`, ""},
		{"v3", `{"schema_version":3}`, ""},
		{"unknown", `{"schema_version":3,"future":{"nested":true}}`, ""},
		{"empty", ``, memoryErrStateCorrupt},
		{"malformed", `{"schema_version":3, broken}`, memoryErrStateCorrupt},
		{"truncated", `{"schema_version":3,"sessions":[`, memoryErrStateCorrupt},
		{"trailing-json", `{"schema_version":3} {}`, memoryErrStateCorrupt},
		{"trailing-garbage", `{"schema_version":3} garbage`, memoryErrStateCorrupt},
		{"missing-version", `{}`, memoryErrUnsupportedVersion},
		{"newer", `{"schema_version":4,"future":true}`, memoryErrUnsupportedVersion},
		{"older", `{"schema_version":-1}`, memoryErrUnsupportedVersion},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := writeTestManifest(t, tc.body)
			_, err := loadBrainManifest(dir)
			_, health, issue := inspectBrainManifestHealth(dir)
			if tc.code == "" {
				if err != nil || issue != nil || health.State != "current" {
					t.Fatalf("read=%v health=%+v", err, health)
				}
			} else {
				if err == nil || !strings.Contains(err.Error(), tc.code) || issue == nil || health.ErrorCode != tc.code {
					t.Fatalf("read=%v health=%+v", err, health)
				}
				if err := writeBrainManifestAndReadme(dir, exportManifest{}); err == nil {
					t.Fatal("writer must refuse invalid existing state")
				}
				after, _ := os.ReadFile(filepath.Join(dir, exportManifestFileName))
				if string(after) != tc.body {
					t.Fatal("failed rewrite changed original")
				}
			}
		})
	}
}

func TestBrainManifestReaderKeepsFileProtections(t *testing.T) {
	for _, kind := range []string{"directory", "symlink", "hardlink"} {
		t.Run(kind, func(t *testing.T) {
			dir := t.TempDir()
			path := filepath.Join(dir, exportManifestFileName)
			target := filepath.Join(t.TempDir(), "target.json")
			if err := os.WriteFile(target, []byte(`{"schema_version":3}`), 0600); err != nil {
				t.Fatal(err)
			}
			var err error
			switch kind {
			case "directory":
				err = os.Mkdir(path, 0700)
			case "symlink":
				err = os.Symlink(target, path)
			case "hardlink":
				err = os.Link(target, path)
			}
			if err != nil {
				t.Fatal(err)
			}
			if _, err := loadBrainManifest(dir); err == nil || !strings.Contains(err.Error(), memoryErrStateUnsafe) {
				t.Fatalf("unsafe read: %v", err)
			}
			_, health, _ := inspectBrainManifestHealth(dir)
			if health.State != "unsafe" {
				t.Fatalf("health: %+v", health)
			}
		})
	}
}

func TestBrainManifestLargeUnknownFieldsRemainReadOnly(t *testing.T) {
	dir := writeTestManifest(t, `{"schema_version":3,"sessions":[],"future":"`+strings.Repeat("x", 17<<20)+`"}`)
	_, dropped, err := readBrainManifest(dir, true)
	if err != nil || !dropped {
		t.Fatalf("tolerant read: dropped=%v err=%v", dropped, err)
	}
	path := filepath.Join(dir, exportManifestFileName)
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := writeBrainManifestAndReadme(dir, exportManifest{}); err == nil {
		t.Fatal("writer erased unknown fields")
	}
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(before, after) {
		t.Fatal("unknown fields were changed")
	}
	if _, err := safeReadFile(path, maxManifestBytes); err == nil {
		t.Fatal("unrelated bounded reader lost its limit")
	}
	// Explicit forced-refresh cleanup shares the dedicated decoder, while still
	// using the checked remover. This only removes synthetic test state.
	removed, err := discardManifestThisBuildCannotRewrite(dir)
	if err != nil || !removed {
		t.Fatalf("checked cleanup: removed=%v err=%v", removed, err)
	}
}
