	}
	index := docIndex{GeneratedAt: now, Records: []docRecord{
		{ID: "doc-1", Path: "seed/docs/ARCH.md", Heading: "Arch", Line: 1, Text: "the alpha subsystem uses postgres for storage"},
	}}
