			Seed: &seedSourceManifest{GeneratedAt: now, Commit: "aaa111", WorktreeMode: "head", SummaryPath: "seed/summary.md"},
			Docs: &docSourceManifest{GeneratedAt: now, IndexPath: docIndexPath, Records: 1, Files: 1},
