	if out, _, err = executeSplit(t, NewRootCommand(opts), "patterns", "skills", "form", taskID, repoDir, "--scope", "repo", "--agent", "codex", "--yes"); err == nil || !strings.Contains(err.Error(), "refusing to overwrite") {
