		viaFTS[0].Record.ID != conversationIDPrefix+"both-terms" || viaFallback[0].Record.ID != viaFTS[0].Record.ID {
		t.Fatalf("FTS/fallback match-set mismatch: fts=%+v fallback=%+v", viaFTS, viaFallback)
