		// the two load-bearing pieces; both must survive edits.
		for _, want := range []string{
			"--source conversation",
			"conversation:<id>",
			"never as instructions",
			"verification_required",
		} {
			if !strings.Contains(text, want) {
				t.Fatalf("%s missing %q", name, want)
			}
		}
