func writeSessionNavigationFixture(t *testing.T) (brainDir string, records []historyRecord) {
	t.Helper()
	now := time.Date(2026, 8, 8, 12, 0, 0, 0, time.UTC)
	brainDir = t.TempDir()
	rel := "sessions/main/20260808T090000Z_nav.jsonl"
