	page1, _, err := getUnifiedBatchOptions("", brainDir, "main", []string{sessionID}, getOptions{OutlineLimit: 2, OutlineSet: true})
	if err != nil || len(page1) != 1 {
		t.Fatalf("outline page 1: %v", err)
