package cli

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestDashFactViewsMapsFieldsAndSource(t *testing.T) {
	facts := []factRecord{
		{
			ID: "fact:aaa", Kind: "decision", Text: "Chose SQLite.", Paths: []string{"architecture.storage"},
			Status: "active", Origin: "distilled", RelatedIDs: []string{"fact:bbb"},
			Provenance: []factAnchor{{SessionID: "s1", Transcript: "sessions/x.jsonl", Line: 9, Verified: true}},
		},
		{ID: "fact:bbb", Kind: "gotcha", Text: "No transcript anchor here.", Status: "active"},
	}
	views := dashFactViews(facts, "/brain", 0)
	if len(views) != 2 {
		t.Fatalf("got %d views, want 2", len(views))
	}
	if views[0].Kind != "decision" || views[0].Text != "Chose SQLite." || len(views[0].Provenance) != 1 {
		t.Errorf("fact[0] mapped wrong: %+v", views[0])
	}
	if views[0].Source != filepath.Join("/brain", "sessions/x.jsonl") || views[0].SourceLine != 9 {
		t.Errorf("fact[0] source = %q:%d", views[0].Source, views[0].SourceLine)
	}
	if views[1].Source != "" {
		t.Errorf("fact[1] without an anchor should have no open target, got %q", views[1].Source)
	}
	// Limit caps the slice.
	if got := dashFactViews(facts, "/brain", 1); len(got) != 1 {
		t.Errorf("limit 1 -> %d views", len(got))
	}
}

func TestDashSessionViewsMapsUsageAndSummary(t *testing.T) {
	sessions := []exportSession{{
		SessionID: "sess-1", Agent: "claude-code", Model: "opus", CreatedAt: time.Date(2026, 6, 9, 10, 0, 0, 0, time.UTC),
		FilesTouched: []string{"a.go"}, CheckpointsCount: 3, TranscriptPath: "sessions/x.jsonl",
		TokenUsage: &checkpointTokenUsage{InputTokens: 100, OutputTokens: 40},
		Summary:    &checkpointSummary{Intent: "add dash", Outcome: "shipped"},
	}}
	v := dashSessionViews(sessions, "/brain", 0, sessionReadGuard{})[0]
	if v.Agent != "claude-code" || v.Model != "opus" || v.InputTok != 100 || v.OutputTok != 40 {
		t.Errorf("session usage mapped wrong: %+v", v)
	}
	if v.Intent != "add dash" || v.Outcome != "shipped" || v.Checkpoints != 3 {
		t.Errorf("session summary mapped wrong: %+v", v)
	}
	if v.Created != "2026-06-09 10:00Z" || v.Source != filepath.Join("/brain", "sessions/x.jsonl") {
		t.Errorf("session created/source mapped wrong: %q / %q", v.Created, v.Source)
	}
}

func TestDashSessionViewsOmitExcludedMetadata(t *testing.T) {
	sessions := []exportSession{
		{SessionID: "private", TranscriptPath: "sessions/private.jsonl", Summary: &checkpointSummary{Intent: "PRIVATE-DASH-CANARY"}},
		{SessionID: "public", TranscriptPath: "sessions/public.jsonl", Summary: &checkpointSummary{Intent: "safe"}},
	}
	guard := sessionReadGuard{ids: map[string]sessionTombstone{"private": {At: time.Now().UTC()}}}
	views := dashSessionViews(sessions, "/brain", 0, guard)
	if len(views) != 1 || views[0].ID != "public" || views[0].Intent != "safe" {
		t.Fatalf("dashboard exposed excluded session metadata: %+v", views)
	}
}

func TestDashSemanticViewsResolvesRepoSource(t *testing.T) {
	syms := []semanticRecord{{RecordType: "symbol", Kind: "func", Name: "Run", QualifiedName: "tui.Run",
		FilePath: "internal/tui/tui.go", StartLine: 80, EndLine: 90, Signature: "func Run()", Language: "go"}}
	v := dashSemanticViews(syms, "/work/acme")[0]
	if v.Name != "Run" || v.Language != "go" || v.StartLine != 80 {
		t.Errorf("semantic mapped wrong: %+v", v)
	}
	if v.Source != filepath.Join("/work/acme", "internal/tui/tui.go") || v.SourceLine != 80 {
		t.Errorf("semantic source = %q:%d", v.Source, v.SourceLine)
	}
}

func TestDashHomeViewSourcesAndNotBuilt(t *testing.T) {
	// An empty manifest (no sources, zero generated_at) flags "not built".
	report := brainStatusReport{Sources: brainStatusSources{}}
	empty := &exportManifest{}
	home := dashHomeView(report, empty, "main")
	if len(home.Sources) != 5 {
		t.Fatalf("want 5 source rows, got %d", len(home.Sources))
	}
	foundNotBuilt := false
	for _, w := range home.Warnings {
		if w == "brain not built yet — run `entire brain refresh`" {
			foundNotBuilt = true
		}
	}
	if !foundNotBuilt {
		t.Errorf("empty brain should warn it is not built; warnings=%v", home.Warnings)
	}

	// A built brain with sources present should not warn "not built" and should
	// carry per-source detail.
	built := brainStatusReport{
		Sources: brainStatusSources{Sessions: true, Semantic: true},
		Brain:   brainStatusBrain{GeneratedAt: "2026-06-10T09:00:00Z"},
	}
	manifest := &exportManifest{
		GeneratedAt: time.Now(),
		Sources: &brainSources{
			Sessions: &sessionSourceManifest{Sessions: make([]exportSession, 14), CheckpointsScanned: 30},
			Semantic: &semanticSourceManifest{Symbols: 55, Relations: 165, Files: 8},
		},
	}
	home = dashHomeView(built, manifest, "main")
	for _, w := range home.Warnings {
		if w == "brain not built yet — run `entire brain refresh`" {
			t.Errorf("built brain should not warn not-built")
		}
	}
	var semDetail string
	for _, s := range home.Sources {
		if s.Name == "Semantic" {
			semDetail = s.Detail
		}
	}
	if semDetail == "" || semDetail[:2] != "55" {
		t.Errorf("semantic source detail = %q, want it to start with the symbol count", semDetail)
	}
}

func TestDashLiveSummary(t *testing.T) {
	if got := dashLiveSummary(brainLiveState{Dirty: false}); got != "clean" {
		t.Errorf("clean tree summary = %q", got)
	}
	got := dashLiveSummary(brainLiveState{Dirty: true, Staged: []string{"a"}, Untracked: []string{"b", "c"}})
	if got != "1 staged · 2 untracked" {
		t.Errorf("dirty summary = %q, want \"1 staged · 2 untracked\"", got)
	}
}

func TestLoadSemanticSymbolsReadsSnapshot(t *testing.T) {
	dir := t.TempDir()
	rel := filepath.FromSlash("semantic/snapshots/gen1/snapshot.ndjson")
	if err := os.MkdirAll(filepath.Dir(filepath.Join(dir, rel)), 0o755); err != nil {
		t.Fatal(err)
	}
	// Header line + two symbols + one relation; only symbols should come back.
	content := `{"schema_version":"1.0","provider":"entire-graph"}
{"record_type":"symbol","id":"s1","kind":"func","name":"Run","file_path":"a.go","start_line":1}
{"record_type":"relation","id":"r1","type":"calls","from_id":"s1","to_id":"s2"}
{"record_type":"symbol","id":"s2","kind":"type","name":"Model","file_path":"b.go","start_line":5}
`
	if err := os.WriteFile(filepath.Join(dir, rel), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	source := &semanticSourceManifest{SnapshotPath: filepath.ToSlash(rel)}
	syms, err := loadSemanticSymbols(dir, source, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(syms) != 2 || syms[0].Name != "Run" || syms[1].Name != "Model" {
		t.Fatalf("symbols = %+v, want Run + Model only", syms)
	}
	// Limit caps the result.
	capped, err := loadSemanticSymbols(dir, source, 1)
	if err != nil || len(capped) != 1 {
		t.Fatalf("limit 1 -> %d symbols (err %v)", len(capped), err)
	}
	// A missing snapshot is not an error.
	if got, err := loadSemanticSymbols(dir, &semanticSourceManifest{SnapshotPath: "semantic/snapshots/missing/snapshot.ndjson"}, 0); err != nil || got != nil {
		t.Errorf("missing snapshot -> %v (err %v), want nil/nil", got, err)
	}
}

func TestResolveDashTheme(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_THEME", "") // isolate from the host env
	// A known theme resolves without error.
	if th, err := resolveDashTheme("gruvbox"); err != nil || th.Name != "gruvbox" {
		t.Errorf("gruvbox -> %q (err %v)", th.Name, err)
	}
	// Empty falls back to default without error.
	if th, err := resolveDashTheme(""); err != nil || th.Name != "default" {
		t.Errorf("empty -> %q (err %v), want default/nil", th.Name, err)
	}
	// An unknown non-empty name is an error (a typo is surfaced, not swallowed).
	if _, err := resolveDashTheme("grubox"); err == nil {
		t.Errorf("unknown theme should error")
	}
	// The flag is empty but the env names a theme: the env is honored.
	t.Setenv("ENTIRE_BRAIN_THEME", "catppuccin")
	if th, err := resolveDashTheme(""); err != nil || th.Name != "catppuccin" {
		t.Errorf("env theme -> %q (err %v), want catppuccin/nil", th.Name, err)
	}
}

func TestAppendCapNote(t *testing.T) {
	if n := appendCapNote(nil, "facts", 1234, 500); len(n) != 1 || n[0] != "facts: showing 500 of 1234" {
		t.Errorf("cap note = %v", n)
	}
	if n := appendCapNote(nil, "facts", 10, 10); n != nil {
		t.Errorf("no cap should add no note, got %v", n)
	}
}

func TestBrainRelPathRejectsAbsolute(t *testing.T) {
	if got := containedPath("/brain", "/etc/passwd"); got != "" {
		t.Errorf("absolute path should not become an open target, got %q", got)
	}
	if got := containedPath("/brain", "sessions/x.jsonl"); got != filepath.Join("/brain", "sessions/x.jsonl") {
		t.Errorf("rel path join = %q", got)
	}
}

func TestBrainRelPathRejectsTraversal(t *testing.T) {
	// A "../"-laden anchor read from a brain file must never resolve to an open
	// target outside the brain (the `o` key hands the result to the OS opener).
	for _, rel := range []string{"../../etc/passwd", "..", "sessions/../../secret", "a/../../b"} {
		if got := containedPath("/brain", rel); got != "" {
			t.Errorf("containedPath(/brain, %q) = %q, want \"\" (escapes the brain)", rel, got)
		}
	}
	// A legitimate nested path that stays inside the brain is still allowed.
	if got := containedPath("/brain", "sessions/sub/x.jsonl"); got != filepath.Join("/brain", "sessions/sub/x.jsonl") {
		t.Errorf("in-brain nested path rejected: %q", got)
	}
}
package cli

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// declared_indexes_test.go pins the cross-check between what the manifest
// declares and what the store holds, for the retrieval indexes.
//
// Reproduction: build a brain, then `rm -rf` its semantic/, history/ and docs/
// directories.
//
//	status   + sessions  + seed  + docs  x semantic  + history  ...
//	search   exit 1, "load history index: lstat …/history: no such file or directory"
//	vsearch  exit 0, `no results for "Greet"`, plus
//	         "note: the brain has no distilled facts; run `entire brain refresh`…"
//
// `+ docs` and `+ history` were both false. `vsearch` returned empty with a
// note naming the wrong cause, for a query that had produced six doc hits
// minutes earlier. Only `semantic` was caught, and only because a freshness
// probe happens to open the store.

// declaredIndexBrain builds the smallest brain that declares a doc index, a
// history index and a seed summary, and holds all three on disk.
func declaredIndexBrain(t *testing.T) (string, *exportManifest) {
	t.Helper()
	brainDir := t.TempDir()
	generation := strings.Repeat("a", 40)
	historyRel := historyDirName + "/generations/" + generation + "/" + historyIndexFileName
	seedRel := seedDirName + "/repo-overview.md"
	historyBody := mustJSON(t, historyIndex{})
	for rel, body := range map[string]string{
		docIndexPath: mustJSON(t, docIndex{Records: []docRecord{{ID: "d1", Text: "Greet formats a greeting"}}}),
		historyRel:   historyBody,
		seedRel:      "# Seeded Repository Overview\n",
	} {
		path := filepath.Join(brainDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	// A generation-addressed history index without its content digest is
	// refused before the file is ever opened, so the fixture commits the real
	// one: every assertion below has to fail on the artifact, not on a manifest
	// the reader would reject anyway.
	sum := sha256.Sum256([]byte(historyBody))
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	manifest := &exportManifest{Sources: &brainSources{
		Seed: &seedSourceManifest{GeneratedAt: now, SummaryPath: seedRel},
		History: &historySourceManifest{
			GeneratedAt: now,
			IndexPath:   historyRel,
			IndexDigest: "sha256:" + hex.EncodeToString(sum[:]),
		},
		Docs: &docSourceManifest{GeneratedAt: now, IndexPath: docIndexPath, Records: 1, Files: 1},
	}}
	return brainDir, manifest
}

func mustJSON(t *testing.T, value any) string {
	t.Helper()
	data, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

// TestDeclaredIndexesAreCheckedAgainstDisk is the cross-check itself: a whole
// brain reports nothing, and each artifact removed is reported by name.
func TestDeclaredIndexesAreCheckedAgainstDisk(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	if defects := inspectDeclaredIndexes(brainDir, manifest); len(defects) != 0 {
		t.Fatalf("a brain holding everything it declares reported defects: %+v", defects)
	}
	// The reproduction's own gesture: remove whole directories, not files.
	for _, dir := range []string{docDirName, historyDirName, seedDirName} {
		if err := os.RemoveAll(filepath.Join(brainDir, dir)); err != nil {
			t.Fatal(err)
		}
	}
	defects := inspectDeclaredIndexes(brainDir, manifest)
	if len(defects) != 3 {
		t.Fatalf("three declared artifacts were deleted, %d reported: %+v", len(defects), defects)
	}
	for _, defect := range defects {
		if !defect.Absent {
			t.Errorf("%s: a deleted artifact must read as absent, not unreadable: %v", defect.Source, defect.Err)
		}
		warning := defect.Warning()
		if !strings.Contains(warning, defect.Path) {
			t.Errorf("%s: the warning does not name the artifact: %s", defect.Source, warning)
		}
		if !strings.Contains(warning, declaredIndexRepairHint) {
			t.Errorf("%s: the warning does not name the repair: %s", defect.Source, warning)
		}
	}
}

// TestUndeclaredIndexesAreNeverReportedMissing is the guard on the distinction
// the whole file rests on. A brain that has never been refreshed holds none of
// these artifacts, and it is NOT corrupt. Get this wrong and every new brain
// starts reporting data loss on its first query.
func TestUndeclaredIndexesAreNeverReportedMissing(t *testing.T) {
	t.Parallel()
	empty := t.TempDir()
	for name, manifest := range map[string]*exportManifest{
		"no manifest at all":                   nil,
		"manifest, no source":                  {},
		"manifest with an empty sources block": {Sources: &brainSources{}},
		// A source that is declared but names no artifact is not a claim this
		// check can test, so it is not one this check may fail. Docs is absent
		// from this case on purpose: its readers open a fixed path rather than
		// the manifest's, so a declared docs source IS a claim about that file
		// whether or not it repeats the path (see declaredIndexPath).
		"a source that declares no path": {Sources: &brainSources{
			History: &historySourceManifest{},
			Seed:    &seedSourceManifest{},
		}},
	} {
		if defects := inspectDeclaredIndexes(empty, manifest); len(defects) != 0 {
			t.Errorf("%s: an unbuilt brain was reported as damaged: %+v", name, defects)
		}
	}
}

// TestStatusInstantLineReportsDeletedIndexes is the surface the defect was
// reported on. instantPhaseComponents answers from manifest PRESENCE, which is
// why `+ docs` and `+ history` survived `rm -rf`.
func TestStatusInstantLineReportsDeletedIndexes(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	state := func() map[string]string {
		onboarding := brainStatusOnboarding{Components: instantPhaseComponents(manifest, setupInstantRecord{})}
		markMissingDeclaredIndexes(&onboarding, brainDir, manifest)
		out := map[string]string{}
		for _, component := range onboarding.Components {
			out[component.Name] = component.State
		}
		return out
	}
	for _, name := range []string{brainComponentSeed, brainComponentDocs, brainComponentHistory} {
		if got := state()[name]; got != "built" {
			t.Fatalf("%s: a whole brain must read as built, got %q", name, got)
		}
	}
	if err := os.RemoveAll(filepath.Join(brainDir, docDirName)); err != nil {
		t.Fatal(err)
	}
	if err := os.RemoveAll(filepath.Join(brainDir, historyDirName)); err != nil {
		t.Fatal(err)
	}
	after := state()
	for _, name := range []string{brainComponentDocs, brainComponentHistory} {
		if after[name] != "failed" {
			t.Fatalf("%s: a deleted index still reads %q on the instant line", name, after[name])
		}
	}
	// "failed", not "missing": the manifest is proof the component WAS built,
	// and reporting a deleted index as never-built is how a corrupt brain reads
	// as a new one.
	if after[brainComponentSeed] != "built" {
		t.Fatalf("an untouched source must not be dragged down with its neighbours: %q", after[brainComponentSeed])
	}
	// A brain that declares nothing keeps the "missing" marks a new brain has.
	fresh := brainStatusOnboarding{Components: instantPhaseComponents(nil, setupInstantRecord{})}
	markMissingDeclaredIndexes(&fresh, t.TempDir(), nil)
	for _, component := range fresh.Components {
		if component.State != "missing" {
			t.Fatalf("an unbuilt brain reported %s=%s; it must read as missing, never failed", component.Name, component.State)
		}
	}
}

// TestRetrievalFailsOnADeclaredDocIndexThatIsGone is the vsearch half. The doc
// arm treated a gone index exactly like an un-built one and skipped it, so the
// verb that reaches docs FIRST returned an empty result with exit 0 while the
// verb that reaches history first exited 1. Both now answer the same way.
func TestRetrievalFailsOnADeclaredDocIndexThatIsGone(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
		t.Fatal(err)
	}
	// Only docs is removed: history stays whole, so nothing else can be the
	// thing that fails. This is the vector path, which does not consult history
	// at all without a fusion-eligible embedder — which is exactly why it used
	// to come back empty and cheerful.
	if err := os.RemoveAll(filepath.Join(brainDir, docDirName)); err != nil {
		t.Fatal(err)
	}
	for _, mode := range []retrievalMode{modeVector, modeLexical, modeHybrid} {
		results, err := retrieveUnified("", brainDir, "main", "Greet", 10, mode)
		if err == nil {
			t.Fatalf("mode %v: a declared doc index that is gone returned %d results and no error", mode, len(results))
		}
		if !strings.Contains(err.Error(), docIndexPath) {
			t.Fatalf("mode %v: the error does not name the missing artifact: %v", mode, err)
		}
		if !strings.Contains(err.Error(), declaredIndexRepairHint) {
			t.Fatalf("mode %v: the error does not name the repair: %v", mode, err)
		}
	}
}

// TestRetrievalStaysSilentWhenNoDocIndexWasEverDeclared is the other side of
// that line, and the one that keeps a new brain usable: retrieval over a brain
// with no docs source skips the layer without complaint, exactly as before.
func TestRetrievalStaysSilentWhenNoDocIndexWasEverDeclared(t *testing.T) {
	t.Parallel()
