			return "1 supersede 1 1.0\n", nil
		}
		if strings.Contains(string(input), "marker new") {
			return "project.tooling.stack\tUse Go 1.26.\n", nil
		}
		return "project.tooling.stack\tUse Go 1.20.\n", nil
	}
