	if semantic.Tests.Roots == nil || len(semantic.Tests.Roots) != 0 {
		t.Fatalf("roots = %#v, want non-nil empty slice", semantic.Tests.Roots)
	}
	data, err := json.Marshal(semantic.Tests)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Contains(data, []byte(`"roots":[]`)) {
