		t.Fatalf("current record hidden behind stale capped candidate:\n%s", packet)
	}
	if got := strings.Count(packet, "\ny\t") + strings.Count(packet, "\nsymbol "); got != 1 {
		t.Fatalf("symbol cap = %d, want 1:\n%s", got, packet)
