	// A legitimate nested path that stays inside the brain is still allowed.
	if got := containedPath("/brain", "sessions/sub/x.jsonl"); got != filepath.Join("/brain", "sessions/sub/x.jsonl") {
		t.Errorf("in-brain nested path rejected: %q", got)
	}
}
package cli

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// declared_indexes_test.go pins the cross-check between what the manifest
// declares and what the store holds, for the retrieval indexes.
//
// Reproduction: build a brain, then `rm -rf` its semantic/, history/ and docs/
// directories.
//
//	status   + sessions  + seed  + docs  x semantic  + history  ...
//	search   exit 1, "load history index: lstat …/history: no such file or directory"
//	vsearch  exit 0, `no results for "Greet"`, plus
//	         "note: the brain has no distilled facts; run `entire brain refresh`…"
//
// `+ docs` and `+ history` were both false. `vsearch` returned empty with a
// note naming the wrong cause, for a query that had produced six doc hits
// minutes earlier. Only `semantic` was caught, and only because a freshness
// probe happens to open the store.

// declaredIndexBrain builds the smallest brain that declares a doc index, a
// history index and a seed summary, and holds all three on disk.
func declaredIndexBrain(t *testing.T) (string, *exportManifest) {
	t.Helper()
	brainDir := t.TempDir()
	generation := strings.Repeat("a", 40)
	historyRel := historyDirName + "/generations/" + generation + "/" + historyIndexFileName
	seedRel := seedDirName + "/repo-overview.md"
	historyBody := mustJSON(t, historyIndex{})
	for rel, body := range map[string]string{
		docIndexPath: mustJSON(t, docIndex{Records: []docRecord{{ID: "d1", Text: "Greet formats a greeting"}}}),
		historyRel:   historyBody,
		seedRel:      "# Seeded Repository Overview\n",
	} {
		path := filepath.Join(brainDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	// A generation-addressed history index without its content digest is
	// refused before the file is ever opened, so the fixture commits the real
	// one: every assertion below has to fail on the artifact, not on a manifest
	// the reader would reject anyway.
	sum := sha256.Sum256([]byte(historyBody))
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	manifest := &exportManifest{Sources: &brainSources{
		Seed: &seedSourceManifest{GeneratedAt: now, SummaryPath: seedRel},
		History: &historySourceManifest{
			GeneratedAt: now,
			IndexPath:   historyRel,
			IndexDigest: "sha256:" + hex.EncodeToString(sum[:]),
		},
		Docs: &docSourceManifest{GeneratedAt: now, IndexPath: docIndexPath, Records: 1, Files: 1},
	}}
	return brainDir, manifest
}

func mustJSON(t *testing.T, value any) string {
	t.Helper()
	data, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

// TestDeclaredIndexesAreCheckedAgainstDisk is the cross-check itself: a whole
// brain reports nothing, and each artifact removed is reported by name.
func TestDeclaredIndexesAreCheckedAgainstDisk(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	if defects := inspectDeclaredIndexes(brainDir, manifest); len(defects) != 0 {
		t.Fatalf("a brain holding everything it declares reported defects: %+v", defects)
	}
	// The reproduction's own gesture: remove whole directories, not files.
	for _, dir := range []string{docDirName, historyDirName, seedDirName} {
		if err := os.RemoveAll(filepath.Join(brainDir, dir)); err != nil {
			t.Fatal(err)
		}
	}
	defects := inspectDeclaredIndexes(brainDir, manifest)
	if len(defects) != 3 {
		t.Fatalf("three declared artifacts were deleted, %d reported: %+v", len(defects), defects)
	}
	for _, defect := range defects {
		if !defect.Absent {
			t.Errorf("%s: a deleted artifact must read as absent, not unreadable: %v", defect.Source, defect.Err)
		}
		warning := defect.Warning()
		if !strings.Contains(warning, defect.Path) {
			t.Errorf("%s: the warning does not name the artifact: %s", defect.Source, warning)
		}
		if !strings.Contains(warning, declaredIndexRepairHint) {
			t.Errorf("%s: the warning does not name the repair: %s", defect.Source, warning)
		}
	}
}

// TestUndeclaredIndexesAreNeverReportedMissing is the guard on the distinction
// the whole file rests on. A brain that has never been refreshed holds none of
// these artifacts, and it is NOT corrupt. Get this wrong and every new brain
// starts reporting data loss on its first query.
func TestUndeclaredIndexesAreNeverReportedMissing(t *testing.T) {
	t.Parallel()
	empty := t.TempDir()
	for name, manifest := range map[string]*exportManifest{
		"no manifest at all":                   nil,
		"manifest, no source":                  {},
		"manifest with an empty sources block": {Sources: &brainSources{}},
		// A source that is declared but names no artifact is not a claim this
		// check can test, so it is not one this check may fail. Docs is absent
		// from this case on purpose: its readers open a fixed path rather than
		// the manifest's, so a declared docs source IS a claim about that file
		// whether or not it repeats the path (see declaredIndexPath).
		"a source that declares no path": {Sources: &brainSources{
			History: &historySourceManifest{},
			Seed:    &seedSourceManifest{},
		}},
	} {
		if defects := inspectDeclaredIndexes(empty, manifest); len(defects) != 0 {
			t.Errorf("%s: an unbuilt brain was reported as damaged: %+v", name, defects)
		}
	}
}

// TestStatusInstantLineReportsDeletedIndexes is the surface the defect was
// reported on. instantPhaseComponents answers from manifest PRESENCE, which is
// why `+ docs` and `+ history` survived `rm -rf`.
func TestStatusInstantLineReportsDeletedIndexes(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	state := func() map[string]string {
		onboarding := brainStatusOnboarding{Components: instantPhaseComponents(manifest, setupInstantRecord{})}
		markMissingDeclaredIndexes(&onboarding, brainDir, manifest)
		out := map[string]string{}
		for _, component := range onboarding.Components {
			out[component.Name] = component.State
		}
		return out
	}
	for _, name := range []string{brainComponentSeed, brainComponentDocs, brainComponentHistory} {
		if got := state()[name]; got != "built" {
			t.Fatalf("%s: a whole brain must read as built, got %q", name, got)
		}
	}
	if err := os.RemoveAll(filepath.Join(brainDir, docDirName)); err != nil {
		t.Fatal(err)
	}
	if err := os.RemoveAll(filepath.Join(brainDir, historyDirName)); err != nil {
		t.Fatal(err)
	}
	after := state()
	for _, name := range []string{brainComponentDocs, brainComponentHistory} {
		if after[name] != "failed" {
			t.Fatalf("%s: a deleted index still reads %q on the instant line", name, after[name])
		}
	}
	// "failed", not "missing": the manifest is proof the component WAS built,
	// and reporting a deleted index as never-built is how a corrupt brain reads
	// as a new one.
	if after[brainComponentSeed] != "built" {
		t.Fatalf("an untouched source must not be dragged down with its neighbours: %q", after[brainComponentSeed])
	}
	// A brain that declares nothing keeps the "missing" marks a new brain has.
	fresh := brainStatusOnboarding{Components: instantPhaseComponents(nil, setupInstantRecord{})}
	markMissingDeclaredIndexes(&fresh, t.TempDir(), nil)
	for _, component := range fresh.Components {
		if component.State != "missing" {
			t.Fatalf("an unbuilt brain reported %s=%s; it must read as missing, never failed", component.Name, component.State)
		}
	}
}

// TestRetrievalFailsOnADeclaredDocIndexThatIsGone is the vsearch half. The doc
// arm treated a gone index exactly like an un-built one and skipped it, so the
// verb that reaches docs FIRST returned an empty result with exit 0 while the
// verb that reaches history first exited 1. Both now answer the same way.
func TestRetrievalFailsOnADeclaredDocIndexThatIsGone(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
		t.Fatal(err)
	}
	// Only docs is removed: history stays whole, so nothing else can be the
	// thing that fails. This is the vector path, which does not consult history
	// at all without a fusion-eligible embedder — which is exactly why it used
	// to come back empty and cheerful.
	if err := os.RemoveAll(filepath.Join(brainDir, docDirName)); err != nil {
		t.Fatal(err)
	}
	for _, mode := range []retrievalMode{modeVector, modeLexical, modeHybrid} {
		results, err := retrieveUnified("", brainDir, "main", "Greet", 10, mode)
		if err == nil {
			t.Fatalf("mode %v: a declared doc index that is gone returned %d results and no error", mode, len(results))
		}
		if !strings.Contains(err.Error(), docIndexPath) {
			t.Fatalf("mode %v: the error does not name the missing artifact: %v", mode, err)
		}
		if !strings.Contains(err.Error(), declaredIndexRepairHint) {
			t.Fatalf("mode %v: the error does not name the repair: %v", mode, err)
		}
	}
}

// TestRetrievalStaysSilentWhenNoDocIndexWasEverDeclared is the other side of
// that line, and the one that keeps a new brain usable: retrieval over a brain
// with no docs source skips the layer without complaint, exactly as before.
func TestRetrievalStaysSilentWhenNoDocIndexWasEverDeclared(t *testing.T) {
	t.Parallel()
	brainDir := t.TempDir()
	if err := writeBrainManifestAndReadme(brainDir, exportManifest{Sources: &brainSources{}}); err != nil {
		t.Fatal(err)
	}
	for _, mode := range []retrievalMode{modeVector, modeLexical, modeHybrid} {
		results, err := retrieveUnified("", brainDir, "main", "Greet", 10, mode)
		if err != nil {
			t.Fatalf("mode %v: a brain that declares no doc index must not be an error: %v", mode, err)
		}
		if len(results) != 0 {
			t.Fatalf("mode %v: an empty brain returned %d results", mode, len(results))
		}
	}
}

// TestHistoryIndexReadNamesADeletedGeneration covers `search`'s half. The
// hardened reader lstats every path component, so a deleted history/ surfaced
// as a raw internal path with no condition and no remedy.
func TestHistoryIndexReadNamesADeletedGeneration(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	source := manifest.Sources.History
	if _, err := loadBrainHistoryIndex(brainDir, source); err != nil {
		t.Fatalf("fixture history index is not readable: %v", err)
	}
	if err := os.RemoveAll(filepath.Join(brainDir, historyDirName)); err != nil {
		t.Fatal(err)
	}
	_, err := loadBrainHistoryIndex(brainDir, source)
	if err == nil {
		t.Fatal("a deleted history index must still be an error")
	}
	if strings.Contains(err.Error(), "lstat ") {
		t.Fatalf("the reader still answers with a raw filesystem call: %v", err)
	}
	for _, want := range []string{source.IndexPath, "not on disk", declaredIndexRepairHint} {
		if !strings.Contains(err.Error(), want) {
			t.Fatalf("the error is missing %q: %v", want, err)
		}
	}
	// The FTS payload fast path is the reader `search` actually takes, and a
	// defect named by one reader and left raw by the other is how the same
	// broken brain produced a sentence from one verb and an lstat from another.
	_, _, _, err = rankHistoryLexicalFromSource(brainDir, source, "history", "Greet", 5)
	if err == nil || strings.Contains(err.Error(), "lstat ") {
		t.Fatalf("the FTS fast path must name the same condition: %v", err)
	}
}

// TestDeclaredIndexDefectSeparatesAbsentFromUnreadable keeps the two situations
// apart: a file that is gone needs a rebuild, a file that will not open needs
// looking at. A directory standing where the index belongs is the cheapest
// unreadable case to construct and is a real one (an interrupted publish).
func TestDeclaredIndexDefectSeparatesAbsentFromUnreadable(t *testing.T) {
	t.Parallel()
	brainDir, manifest := declaredIndexBrain(t)
	path := filepath.Join(brainDir, filepath.FromSlash(docIndexPath))
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(path, 0o755); err != nil {
		t.Fatal(err)
	}
	defect := inspectDeclaredIndex(brainDir, manifest, declaredIndexDocs)
	if defect.OK() {
		t.Fatal("a directory where the doc index belongs is not a readable index")
	}
	if defect.Absent {
		t.Fatalf("something IS there; reporting it as absent sends the reader to the wrong repair: %s", defect.Warning())
	}
	if !strings.Contains(defect.Warning(), "cannot be read") {
		t.Fatalf("the unreadable case must keep its own words: %s", defect.Warning())
	}
	if errors.Is(defect.Err, os.ErrNotExist) {
		t.Fatalf("the underlying error contradicts the classification: %v", defect.Err)
	}
}
package cli

import (
	"context"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

// A degenerate repository already exited 1, which was right. What it printed was
// the first git subprocess that happened to notice, verbatim:
//
//	resolve HEAD for semantic index: git [-c core.fsmonitor=false rev-parse HEAD]:
//	exit status 128: fatal: ambiguous argument 'HEAD': unknown revision or path
//	not in the working tree.
//	Use '--' to separate paths from revisions, like this:
//	'git <command> [<revision>...] -- [<file>...]'
//
// Three things are wrong with that. It does not name the condition ("no commits
// yet"), it names no way out, and `-c core.fsmonitor=false` is an argument this
// binary adds for hardening and the reader never typed -- so the one concrete
// detail in the message is about our internals.

// gitAt runs real git, because these conditions are properties of an actual
// repository on disk and a scripted runner cannot express them: the fake keys on
// (name, args) and never on the directory the command runs in.
func gitAt(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v in %s: %v: %s", args, dir, err, out)
	}
}

func TestDegenerateRepositoriesAreNamedRatherThanLeakingGitText(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not installed")
	}
	raw := errors.New("resolve HEAD for semantic index: git [-c core.fsmonitor=false rev-parse HEAD]: exit status 128: fatal: ambiguous argument 'HEAD': unknown revision or path not in the working tree")

	for _, tc := range []struct {
		name  string
		build func(t *testing.T) string
		want  string
	}{
		{
			name: "no commits yet",
			build: func(t *testing.T) string {
				dir := t.TempDir()
				gitAt(t, dir, "init", "-q")
				return dir
			},
			want: "no commits yet",
		},
		{
			name: "bare repository",
			build: func(t *testing.T) string {
				dir := t.TempDir()
				gitAt(t, dir, "init", "-q", "--bare")
				return dir
			},
			want: "bare repository has no working tree",
		},
		{
			name:  "not a repository",
			build: func(t *testing.T) string { return t.TempDir() },
			want:  "not a git repository",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := tc.build(t)
			named := nameDegenerateRepoFailure(context.Background(), ExecRunner{}, dir, raw)
			if named == nil {
				t.Fatal("a failure was swallowed entirely")
			}
			text := named.Error()
			if !strings.Contains(text, tc.want) {
				t.Fatalf("the condition is not named:\n%s", text)
			}
			if !strings.Contains(text, dir) {
				t.Fatalf("the message does not say which repository:\n%s", text)
			}
			// The whole point: git's own text, and the argv this binary added to
			// it, must be gone.
			for _, leak := range []string{"fsmonitor", "fatal:", "exit status 128", "rev-parse"} {
				if strings.Contains(text, leak) {
					t.Fatalf("raw git detail %q survived into the message:\n%s", leak, text)
				}
			}
		})
	}

	// A DETACHED HEAD is deliberately not classified. It builds a brain, the
	// surfaces that care already say branch_tip=stale, and it is also the shape
	// that proves the unborn check needs positive evidence: an unborn HEAD is
	// confirmed by symbolic-ref SUCCEEDING and its branch then failing to
	// resolve, never by `rev-parse HEAD` merely failing -- which is equally what
	// an unavailable git looks like.
	detached := t.TempDir()
	gitAt(t, detached, "init", "-q")
	gitAt(t, detached, "config", "user.email", "t@example.com")
	gitAt(t, detached, "config", "user.name", "t")
	if err := os.WriteFile(filepath.Join(detached, "main.go"), []byte("package main\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	gitAt(t, detached, "add", "-A")
	gitAt(t, detached, "commit", "-qm", "init")
	gitAt(t, detached, "checkout", "-q", "--detach")
	if got := nameDegenerateRepoFailure(context.Background(), ExecRunner{}, detached, raw); !errors.Is(got, raw) {
		t.Fatalf("a detached HEAD was classified as a degenerate repository: %v", got)
	}

	// The control, and the reason this is a classifier rather than a blanket
	// rewrite: in a repository with none of these conditions, the original error
	// is the best thing available and is returned untouched.
	healthy := t.TempDir()
	gitAt(t, healthy, "init", "-q")
	gitAt(t, healthy, "config", "user.email", "t@example.com")
	gitAt(t, healthy, "config", "user.name", "t")
	if err := os.WriteFile(filepath.Join(healthy, "main.go"), []byte("package main\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	gitAt(t, healthy, "add", "-A")
	gitAt(t, healthy, "commit", "-qm", "init")
	if got := nameDegenerateRepoFailure(context.Background(), ExecRunner{}, healthy, raw); !errors.Is(got, raw) {
		t.Fatalf("a healthy repository had an unrelated failure rewritten: %v", got)
	}
}

// TestTheSemanticIndexNamesAnEmptyRepository drives the classifier through the
// call path that actually produced the reported message, so the wiring is
// covered and not just the helper.
func TestTheSemanticIndexNamesAnEmptyRepository(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not installed")
	}
	repoDir := t.TempDir()
	gitAt(t, repoDir, "init", "-q")
	env := semanticTestEnv(t, repoDir)
	env.RepoRoot = repoDir
	opts := Options{Version: "test", Env: env, Runner: ExecRunner{}}

	err := runSemanticIndex(context.Background(), &cobra.Command{Use: "index"}, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir)
	if err == nil {
		t.Fatal("indexing a repository with no commits must fail")
	}
	text := err.Error()
	if !strings.Contains(text, "no commits yet") {
		t.Fatalf("the semantic index did not name the condition:\n%s", text)
	}
	if strings.Contains(text, "fsmonitor") || strings.Contains(text, "fatal:") {
		t.Fatalf("raw git text survived into the semantic index failure:\n%s", text)
	}
}

// TestWorktreeRefreshNamesADegenerateRepository covers the route around that
// classifier.
//
// #238 applied nameDegenerateRepoFailure at the four sites a default run
// reaches. --worktree reaches none of them: it skips the wrapped worktreeDirty
// check in runSeed entirely, and the FIRST git command it then runs is the
// worktree fingerprint, which was wrapped raw. So the same two repositories
// answered well without the flag and leaked with it:
//
//	fingerprint worktree for seed: git [-c core.fsmonitor=false
//	-c core.hooksPath=/dev/null/entire-brain-hooks-disabled status --porcelain
//	--untracked-files=all]: exit status 128: fatal: this operation must be run
//	in a work tree
//
// Note what leaks past git's own text: core.hooksPath, a flag this binary adds
// and no reader ever typed.
func TestWorktreeRefreshNamesADegenerateRepository(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not installed")
	}
	for _, tc := range []struct {
		name  string
		init  []string
		want  string
		verbs [][]string
	}{
		{
			name:  "bare repository",
			init:  []string{"init", "-q", "--bare"},
			want:  "bare repository has no working tree",
			verbs: [][]string{{"refresh", "seed", "--worktree"}, {"refresh", "--worktree"}},
		},
		{
			name:  "no commits yet",
			init:  []string{"init", "-q"},
			want:  "no commits yet",
			verbs: [][]string{{"refresh", "seed", "--worktree"}, {"refresh", "--worktree"}},
		},
	} {
		for _, verb := range tc.verbs {
			t.Run(tc.name+" "+strings.Join(verb, " "), func(t *testing.T) {
				repoDir := t.TempDir()
				gitAt(t, repoDir, tc.init...)
				env := semanticTestEnv(t, repoDir)
				env.RepoRoot = repoDir
				opts := Options{Version: "test", Env: env, Runner: ExecRunner{}}

				out, err := execute(t, NewRootCommand(opts), verb...)
				if err == nil {
					t.Fatalf("a degenerate repository must still fail:\n%s", out)
				}
				text := err.Error()
				if !strings.Contains(text, tc.want) {
					t.Fatalf("the condition is not named:\n%s", text)
				}
				// The hardened argv is the part that is ours, not git's, and it
				// is the part a reader can do least with.
				for _, leak := range []string{"fsmonitor", "hooksPath", "fatal:", "exit status 128"} {
					if strings.Contains(text, leak) {
						t.Fatalf("raw git detail %q survived into the message:\n%s", leak, text)
					}
				}
			})
		}
	}
}
package cli

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// The demo scripts run every `entire` and `entire-brain` verb through a
// sandbox() helper built on `env -i`, which means the sandbox's env block is
// the ONLY place a child's environment comes from. It sets TERM, so under a
// captured pty (`script -q run.log ./scripts/demo-agent-session.sh` — the way
// these demos are recorded and validated) stdout is a real terminal and
// `entire checkpoint list` pages its output through $PAGER. With PAGER unset
// that is `less` (cmd/entire/cli/explain.go: outputWithPager -> buildPagerCmd),
// which blocks on "Press RETURN to continue" and hangs the demo indefinitely
// mid-run — observed twice, at ~42 and ~59 minutes, with no further output.
//
// This is a shell fix with no Go call path, so it has no other regression
// guard: nothing in the build or the test suite notices if the three
// non-blocking env entries are dropped from sandbox() again. Hence this test,
// which reads the shipped scripts and fails if they are.
func REDACTED(t *testing.T) {
	t.Parallel()

	// Set in sandbox()'s `env -i` block, these cover every child and
	// grandchild in one place, rather than a per-command --no-pager flag that
	// the next paging verb would silently miss.
	required := []string{
		"PAGER=cat",             // `entire` reads PAGER; `cat` never waits for input
		"GIT_PAGER=cat",         // same for any git child that pages
		"GIT_TERMINAL_PROMPT=0", // a git child wanting credentials must fail, not block
	}

	for _, name := range []string{"demo-agent-session.sh", "demo-setup.sh"} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			path := filepath.Join("..", "..", "scripts", name)
			raw, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("read %s: %v", path, err)
			}
			body, err := sandboxEnvBlock(string(raw))
			if err != nil {
				t.Fatalf("%s: %v", path, err)
			}
			for _, entry := range required {
				if !strings.Contains(body, entry) {
					t.Errorf("%s: sandbox() `env -i` block does not set %s.\n"+
						"Without it a child of this sandbox can block on the pty and the demo "+
						"hangs forever mid-run instead of finishing unattended.\nblock was:\n%s",
						path, entry, body)
				}
			}
			if name == "demo-agent-session.sh" && !strings.Contains(body, `${PATH:-`) {
				t.Errorf("%s: sandbox() discards the caller's PATH; git and other prerequisites outside system directories become unreachable\nblock was:\n%s", path, body)
			}
		})
	}
}

func TestDemoSetupSerializesConcurrentStubCounters(t *testing.T) {
	t.Parallel()
	path := filepath.Join("..", "..", "scripts", "demo-setup.sh")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	body := string(raw)
	if !strings.Contains(body, `mkdir "$counter_lock"`) || !strings.Contains(body, `rmdir "$counter_lock"`) {
		t.Fatalf("demo stub counter is not protected by an atomic lock")
	}
}

func TestInstallChecksCompilerEvenWhenGoIsMissing(t *testing.T) {
	t.Parallel()
	path := filepath.Join("..", "..", "scripts", "install.sh")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	body := string(raw)
	goCheck := strings.Index(body, "if ! have go; then")
	compilerCheck := strings.Index(body, `if ! have "$go_cc"`)
	problemsCheck := strings.Index(body, `if [ -n "$problems" ]`)
	if goCheck < 0 || compilerCheck < goCheck || problemsCheck < compilerCheck {
		t.Fatalf("compiler prerequisite is not checked independently before preflight exits")
	}
	if strings.Contains(body, `rm -rf "$graph_cache"`) {
		t.Fatal("installer may delete an arbitrary user-supplied cache path")
	}
	if !strings.Contains(body, `-f "$graph_root/$graph_cache_marker"`) {
		t.Fatal("installer refreshes cache checkouts without proving it created them")
	}
}

// Once `entire enable` has run in scripts/demo-agent-session.sh, the demo
// repository carries Entire's git hooks, so EVERY later `git commit` runs
// `entire` as a hook child. Two things then depend on that commit going through
// sandbox():
//
//   - the prepare-commit-msg hook asks "Link this commit to session context?
//     [Y]es / [n]o / [a]lways" on /dev/tty — the CONTROLLING TERMINAL, not
//     stdin — so no input redirection can answer it and the demo blocks forever
//     on a human's terminal. sandbox()'s GIT_TERMINAL_PROMPT=0 is what the CLI
//     reads as "this caller cannot answer prompts"
//     (cmd/entire/cli/interactive/interactive.go, isAgentSubprocessEnv), and it
//     auto-links instead of asking.
//   - an unsandboxed hook child runs against the developer's REAL HOME and
//     ENTIRE_CONFIG_DIR, which is exactly the leak the sandbox exists to stop.
func TestDemoAgentSessionCommitsRunInsideTheSandbox(t *testing.T) {
	t.Parallel()

	path := filepath.Join("..", "..", "scripts", "demo-agent-session.sh")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}

	commits := 0
	for _, line := range logicalShellLines(string(raw)) {
		if !strings.Contains(line, "git commit") {
			continue
		}
		commits++
		if !strings.Contains(line, "sandbox ") {
			t.Errorf("%s: this `git commit` does not run through sandbox(), so its "+
				"Entire git hooks get the real HOME and can block on /dev/tty:\n\t%s", path, line)
		}
	}
	// Guard the guard: if the commits are ever renamed out from under this
	// matcher, an empty sweep must not read as a pass.
	if commits < 2 {
		t.Fatalf("%s: expected at least 2 `git commit` invocations to check, found %d — "+
			"the matcher has drifted from the script", path, commits)
	}
}

// logicalShellLines drops comment lines and joins backslash continuations, so a
// run_step spread over two lines is matched as the single command it is.
func logicalShellLines(script string) []string {
	var out []string
	var pending strings.Builder
	for _, line := range strings.Split(script, "\n") {
		if strings.HasPrefix(strings.TrimLeft(line, " \t"), "#") {
			continue
		}
		trimmed := strings.TrimRight(line, " \t")
		if strings.HasSuffix(trimmed, "\\") {
			pending.WriteString(strings.TrimSuffix(trimmed, "\\"))
			pending.WriteString(" ")
			continue
		}
		pending.WriteString(strings.TrimSpace(line))
		out = append(out, pending.String())
		pending.Reset()
	}
	if pending.Len() > 0 {
		out = append(out, pending.String())
	}
	return out
}

// sandboxEnvBlock returns the text of the `env -i ... "$@")` assignment block
// inside the script's sandbox() helper. Scoping the assertion to that block is
// the point: the same three strings appearing in a comment, or exported for
// one command only, would not protect the other children.
func sandboxEnvBlock(script string) (string, error) {
	const marker = "sandbox() {"
	start := strings.Index(script, marker)
	if start < 0 {
		return "", errNoSandboxHelper
	}
	rest := script[start:]
	envAt := strings.Index(rest, "env -i")
	if envAt < 0 {
		return "", errNoSandboxEnv
	}
	rest = rest[envAt:]
	end := strings.Index(rest, `"$@")`)
	if end < 0 {
		return "", errNoSandboxEnvEnd
	}
	return rest[:end], nil
}

var (
	errNoSandboxHelper = &demoScriptError{"no sandbox() helper found"}
	errNoSandboxEnv    = &demoScriptError{"sandbox() has no `env -i` block"}
	errNoSandboxEnvEnd = &demoScriptError{"sandbox()'s `env -i` block is unterminated"}
)

type demoScriptError struct{ msg string }

func (e *demoScriptError) Error() string { return e.msg }

func TestDemoCleanupPreservesSignalExitAndStopsSandboxChild(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX demo scripts")
	}
	for _, name := range []string{"demo-setup.sh", "demo-agent-session.sh", "trial-setup.sh"} {
		t.Run(name, func(t *testing.T) {
			data, err := os.ReadFile(filepath.Join("..", "..", "scripts", name))
			if err != nil {
				t.Fatal(err)
			}
			text := string(data)
			start := strings.Index(text, "sandbox_processes() {")
			end := strings.Index(text, "trap 'exit 143' TERM")
			if start < 0 || end < start {
				t.Fatal("cleanup block missing")
			}
			block := text[start : end+len("trap 'exit 143' TERM")]
			root := filepath.Join(t.TempDir(), "sandbox")
			script := "set -eu\ndemo_dir=$1\ntrial_dir=$1\nkeep=\nmkdir -p \"$1\"\ncp /bin/sleep \"$1/entire-brain\"\n" + block + "\n\"$1/entire-brain\" 60 &\nsleep 0.1\nkill -TERM $$\n"
			cmd := exec.Command("sh", "-c", script, "test", root)
			out, err := cmd.CombinedOutput()
			if err == nil || cmd.ProcessState.ExitCode() != 143 {
				t.Fatalf("signal exit: %v, %s", err, out)
			}
			if _, err := os.Stat(root); !os.IsNotExist(err) {
				t.Fatalf("sandbox not cleaned after stopping child: %v, %s", err, out)
			}
		})
	}
}

func TestDemoSandboxRefusesExistingUserDirectory(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX scripts")
	}
	for _, name := range []string{"demo-setup.sh", "demo-agent-session.sh", "trial-setup.sh"} {
		data, err := os.ReadFile(filepath.Join("..", "..", "scripts", name))
		if err != nil {
			t.Fatal(err)
		}
		text := string(data)
		start := strings.Index(text, "# Only a directory created by this invocation")
		if start < 0 {
			t.Fatal("sandbox creation guard missing")
		}
		end := strings.Index(text[start:], "sandbox_home=") + start
		if start < 0 || end < start {
			t.Fatal("sandbox creation guard missing")
		}
		root := t.TempDir()
		sentinel := filepath.Join(root, "owned")
		if err := os.WriteFile(sentinel, []byte("keep"), 0600); err != nil {
			t.Fatal(err)
		}
		script := "set -eu\ndemo_dir=$1\ntrial_dir=$1\ndie() { exit 1; }\n" + text[start:end]
		cmd := exec.Command("sh", "-c", script, "test", root)
		if out, err := cmd.CombinedOutput(); err == nil {
			t.Fatalf("%s accepted existing directory: %s", name, out)
		}
		if data, err := os.ReadFile(sentinel); err != nil || string(data) != "keep" {
			t.Fatalf("%s deleted user content: %v", name, err)
		}
	}
}

