package cli

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"testing"
	"time"
)

const distillPipeHelperEnv = "ENTIRE_BRAIN_DISTILL_PIPE_HELPER"

func TestDistillAgentPipeHelper(t *testing.T) {
	switch os.Getenv(distillPipeHelperEnv) {
	case "normal":
		fmt.Print("{}")
		os.Exit(0)
	case "grandchild":
		time.Sleep(15 * time.Second)
		os.Exit(0)
	case "parent":
		self, err := os.Executable()
		if err != nil {
			os.Exit(2)
		}
		child := exec.Command(self, "-test.run=^TestDistillAgentPipeHelper$")
		child.Env = mergeCommandEnv(os.Environ(), map[string]string{distillPipeHelperEnv: "grandchild"})
		child.Stdout = os.Stdout
		child.Stderr = os.Stderr
		if child.Start() != nil {
			os.Exit(3)
		}
		if os.WriteFile(os.Getenv("ENTIRE_BRAIN_DISTILL_HELPER_PID"), []byte(strconv.Itoa(child.Process.Pid)), 0600) != nil {
			os.Exit(4)
		}
		time.Sleep(15 * time.Second)
		os.Exit(0)
	default:
		t.Skip("subprocess helper")
	}
}

func TestDistillAgentTimeoutBoundsInheritedPipes(t *testing.T) {
	t.Setenv(distillPipeHelperEnv, "parent")
	pidPath := t.TempDir() + string(os.PathSeparator) + "child.pid"
	t.Setenv("ENTIRE_BRAIN_DISTILL_HELPER_PID", pidPath)
	t.Cleanup(func() {
		if b, err := os.ReadFile(pidPath); err == nil {
			if pid, err := strconv.Atoi(string(b)); err == nil {
				if process, err := os.FindProcess(pid); err == nil {
					_ = process.Kill()
				}
			}
		}
	})
	self, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	_, err = execDistillAgent(context.Background(), t.TempDir(), []string{self, "-test.run=^TestDistillAgentPipeHelper$"}, nil, 2*time.Second)
	if err == nil || !strings.Contains(err.Error(), "timed out") {
		t.Fatalf("expected timeout, got %v", err)
	}
	if _, err := os.Stat(pidPath); err != nil {
		t.Fatalf("grandchild probe did not start: %v", err)
	}
	if elapsed := time.Since(start); elapsed > 2*time.Second+distillAgentWaitDelay+3*time.Second {
		t.Fatalf("inherited pipes extended a 2s timeout to %s", elapsed)
	}
}

func TestDistillAgentWaitDelayKeepsNormalOutput(t *testing.T) {
	t.Setenv(distillPipeHelperEnv, "normal")
	self, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	out, err := execDistillAgent(context.Background(), t.TempDir(), []string{self, "-test.run=^TestDistillAgentPipeHelper$"}, nil, 5*time.Second)
	if err != nil || out != "{}" {
		t.Fatalf("normal provider: %q %v", out, err)
	}
}
package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

// doc_contract_test.go is the doc-contract lock: user-facing docs, tool
// descriptions, and the CLI/MCP source-mode surface must describe the same
// tested capability matrix. When behavior changes, this test forces the
// documentation to move with it instead of drifting.

func readRepoDoc(t *testing.T, rel string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("..", "..", filepath.FromSlash(rel)))
	if err != nil {
		t.Fatalf("read %s: %v", rel, err)
	}
	return string(data)
}

func TestDocContractCapabilityMatrix(t *testing.T) {
	readme := readRepoDoc(t, "README.md")
	threat := readRepoDoc(t, "docs/recall_threat_model.md")
	guide := readRepoDoc(t, "docs/semantic_mcp_guide.md")

	opts := Options{Version: "test"}

	// Conversation vector support: the README must not describe the CLI
	// conversation vector arm as unsupported, and must document the fusion
	// development flag it references in code.
	if strings.Contains(readme, "`vsearch --source conversation` is unsupported") {
		t.Fatal("README still claims conversation vector search is unsupported")
	}
	for _, want := range []string{
		"ENTIRE_BRAIN_CONVERSATION_FUSION",
		"ENTIRE_BRAIN_BRIEF_CONVERSATION",
		"`--source` (`all` | `fact` |",
	} {
		if !strings.Contains(readme, want) {
			t.Fatalf("README missing %q", want)
		}
	}

	// Privacy/retention claims: retention exists; the threat model must not
	// describe it as unimplemented, and the guide must list every privacy
	// subcommand the CLI registers.
	if strings.Contains(threat, "not yet implemented") {
		t.Fatal("threat model still describes shipped capability as unimplemented")
	}
	if !strings.Contains(threat, "retention") {
		t.Fatal("threat model must describe the retention policy surface")
	}
	if strings.Contains(strings.ToLower(threat), "fail-open") || strings.Contains(strings.ToLower(threat), "fail open") {
		t.Fatal("threat model must not describe tombstone corruption as fail-open")
	}
	for _, want := range []string{"fails closed", "unknown-newer", "lifecycle jobs", "egress"} {
		if !strings.Contains(threat, want) {
			t.Fatalf("threat model missing hardened privacy contract %q", want)
		}
	}
	if strings.Contains(guide, "(`history/projection-state-v1.json`, published through the manifest commit)") {
		t.Fatal("semantic guide still describes the pre-generation projection receipt path")
	}
	for _, want := range []string{"generation-addressed projection receipt", "manifest switches", "present_unproven", "[--repo-key <key>]", "repository identity"} {
		if !strings.Contains(guide, want) {
			t.Fatalf("semantic guide missing current lifecycle contract %q", want)
		}
	}
	privacy := newPrivacyCommand(Options{Version: "test"})
	for _, sub := range privacy.Commands() {
		name := strings.Fields(sub.Use)[0]
		if !strings.Contains(guide, name) {
			t.Fatalf("semantic guide privacy verb list missing %q", name)
		}
	}

	// MCP surface: search/query advertise source + conversation filters;
	// vsearch advertises neither (the guide documents that limit).
	var searchSchema, vsearchSchema map[string]any
	for _, tool := range mcpToolDefinitions() {
		switch tool["name"] {
		case "brain_search":
			searchSchema = tool["inputSchema"].(map[string]any)
		case "brain_vsearch":
			vsearchSchema = tool["inputSchema"].(map[string]any)
		}
	}
	if searchSchema == nil || vsearchSchema == nil {
		t.Fatal("brain_search/brain_vsearch tool definitions missing")
	}
	searchProps, _ := json.Marshal(searchSchema["properties"])
	vsearchProps, _ := json.Marshal(vsearchSchema["properties"])
	// All three retrieval tools share one strict schema (source,
	// structured filters, concepts).
	for _, arg := range []string{"source", "session_id", "agent", "after", "before", "concepts"} {
		if !strings.Contains(string(searchProps), `"`+arg+`"`) {
			t.Fatalf("brain_search schema missing %q: %s", arg, searchProps)
		}
		if !strings.Contains(string(vsearchProps), `"`+arg+`"`) {
			t.Fatalf("brain_vsearch schema missing %q: %s", arg, vsearchProps)
		}
	}
	if !strings.Contains(guide, "Multi-concept session recall") {
		t.Fatal("semantic guide must document multi-concept recall")
	}
	// The multi-get schema advertises the same batch cap the code enforces.
	for _, tool := range mcpToolDefinitions() {
		if tool["name"] != "brain_multi_get" {
			continue
		}
		schema, _ := json.Marshal(tool["inputSchema"])
		if !strings.Contains(string(schema), `"maxItems":`+fmt.Sprint(maxGetBatchIDs)) {
			t.Fatalf("brain_multi_get schema must advertise maxItems %d: %s", maxGetBatchIDs, schema)
		}
	}

	// CLI verbs: --source is registered on search, query, and vsearch.
	for name, cmd := range map[string]*cobra.Command{
		"search":  newSearchCommand(opts),
		"query":   newQueryCommand(opts),
		"vsearch": newVsearchCommand(opts),
	} {
		if cmd.Flags().Lookup("source") == nil {
			t.Fatalf("%s must take --source", name)
		}
	}

	// Every registered MCP tool must appear in the guide's "Available tools"
	// catalog. brain_entity_history previously shipped in mcp.go and README.md
	// but was missing from this catalog; this lock catches the next tool that
	// registers without a matching guide entry.
	for _, tool := range mcpToolDefinitions() {
		name, _ := tool["name"].(string)
		if name == "" {
			continue
		}
		if !strings.Contains(guide, "`"+name+"`") {
			t.Fatalf("semantic_mcp_guide.md tool catalog missing registered tool %q", name)
		}
	}
}
package cli

import (
	"testing"
	"time"
)

func docTestIndex() docIndex {
	return docIndex{
		GeneratedAt: time.Date(2026, 6, 9, 0, 0, 0, 0, time.UTC),
		Records: []docRecord{
			{ID: "d1", Path: "seed/architecture.md", Heading: "Architecture", Line: 1,
				Text: "The brain has multiple sources: seed owns baseline knowledge, export owns session history."},
			{ID: "d2", Path: "seed/docs/feed.md", Heading: "Feed crawler", Line: 1,
				Text: "The feed crawler streams episodes with cursor-based backfill paging."},
		},
	}
}

func TestDocFTSRetrieves(t *testing.T) {
	brainDir := t.TempDir()
	index := docTestIndex()

	scored, ok := rankDocsViaFTS(brainDir, index, "how does the feed crawler backfill", 25)
	if !ok || len(scored) == 0 || scored[0].Record.ID != "d2" {
		t.Fatalf("expected d2 (feed crawler) first, got ok=%v %v", ok, scored)
	}

	// Absent terms: searchable query, no matches.
	if scored, ok := rankDocsViaFTS(brainDir, index, "xylophone zebra quokka", 25); ok && len(scored) != 0 {
		t.Fatalf("expected no matches for absent terms, got %v", scored)
	}

	// Rebuild determinism.
	a, _ := rankDocsViaFTS(brainDir, index, "baseline knowledge sources", 25)
	b, _ := rankDocsViaFTS(brainDir, index, "baseline knowledge sources", 25)
	if len(a) != len(b) {
		t.Fatalf("nondeterministic: %d vs %d", len(a), len(b))
	}
}

func TestDocFTSPrefersCurrentOverHistorical(t *testing.T) {
	brainDir := t.TempDir()
	index := docIndex{
		GeneratedAt: time.Date(2026, 7, 21, 0, 0, 0, 0, time.UTC),
		Records: []docRecord{
			{ID: "a-old", Path: "seed/docs/old.md", Text: "agent benchmark workflow", Historical: true},
			{ID: "z-current", Path: "seed/docs/current.md", Text: "agent benchmark workflow"},
		},
	}
	scored, ok := rankDocsViaFTS(brainDir, index, "agent benchmark workflow", 2)
	if !ok || len(scored) != 2 || scored[0].Record.ID != "z-current" {
		t.Fatalf("current FTS document should rank first, got ok=%v %+v", ok, scored)
	}
}

