		fd, err := unix.Open(path, unix.O_RDWR|unix.O_NONBLOCK, 0)
		if err == nil {
			defer unix.Close(fd)
		}
		t.Fatal("index probe blocked waiting for a FIFO writer")
	}
}

func TestDeclaredDocIndexRejectsAliases(t *testing.T) {
