// The README's own examples must be executable.
//
// Written 2026-09-11, scoring the whole command surface for release readiness.
// There are 34 top-level commands, and eleven were named in the README with no
// test behind them at all:
//
//	bench, inspect blame, inspect dead-code, inspect graph-schema,
//	inspect graph-ui, inspect ingest-traces, inspect trace-path,
//	facts map, facts promote, facts retract, facts eval-compare
//
// That gap is what makes "is it stable?" unanswerable. A documented command
// with no test is a promise nobody has checked, and the promise that matters is
// not deep behaviour — it is the first thing a new user does. They read the
// README, paste a line from it against a brain that does not exist yet, and
// find out from the result whether this project is finished.
//
// So every invocation below is COPIED FROM THE README, at the line noted, with
// only the angle-bracket placeholders filled in. That is the point: this is a
// contract test on the documentation, not an independent guess at how these
// commands are called. Writing the table by hand instead is how the first draft
// of this file "found" a bug that was mine — it invented `facts promote --to`,
// which does not exist, while README line 378 correctly documents `--from`.
//
// The contract is narrow on purpose:
//
//  1. THE README'S INVOCATION IS ACCEPTED. Not "unknown command", not "unknown
//     flag". A renamed flag or a subcommand moved under a different parent
//     silently turns a documented example into a dead end, and nothing else in
//     this repo would notice.
//
//  2. IT DOES NOT PANIC. A panic on an empty brain is the worst first
//     impression available, and most of these read stores, graphs and manifests
//     that are simply absent before the first refresh.
//
//  3. IT SAYS SOMETHING. Success or a real error, never silence. On an empty
//     brain most of these SHOULD fail; what they must not do is fail blankly.
//
// Deliberately NOT asserted: the shape of a successful result. These eleven
// span benchmarking, graph traversal and fact lifecycle, and pinning their
// output here would be a worse test than none — it would break on every honest
// change and teach people to delete it. Behaviour belongs in each command's own
// test. This is the floor beneath all of them.

// documentedCommand is one README example: the command path, the operands and
// flags that follow it, and the README line it was taken from.
type documentedCommand struct {
	path       []string
	args       []string
	readmeLine int
	note       string
}

func (dc documentedCommand) name() string { return strings.Join(dc.path, " ") }

func (dc documentedCommand) invocation() []string {
	return append(append([]string{}, dc.path...), dc.args...)
}

func documentedCommands() []documentedCommand {
	return []documentedCommand{
		// entire brain bench semantic .
		{path: []string{"bench"}, args: []string{"semantic", "."}, readmeLine: 419},

		// entire brain inspect graph-schema --json
		{path: []string{"inspect", "graph-schema"}, args: []string{"--json"}, readmeLine: 320},

		// entire brain inspect graph-ui semantic-graph.html
		{path: []string{"inspect", "graph-ui"}, args: []string{"semantic-graph.html"}, readmeLine: 321},

		// entire brain inspect trace-path "<caller>" "<callee>" --json
		{path: []string{"inspect", "trace-path"}, args: []string{"pkg.Caller", "pkg.Callee", "--json"},
			readmeLine: 322, note: "two symbols that are not indexed yet"},

		// entire brain inspect dead-code --json
		{path: []string{"inspect", "dead-code"}, args: []string{"--json"}, readmeLine: 323},

		// `brain_ingest_traces` / `inspect ingest-traces`
		{path: []string{"inspect", "ingest-traces"}, readmeLine: 342},

		// entire brain inspect blame <fact-id> --json
		{path: []string{"inspect", "blame"}, args: []string{"fact:missing", "--json"},
			readmeLine: 381, note: "a fact id that does not exist — the state before any distill"},

		// entire brain facts promote --from <branch> --strategy keep-both
		{path: []string{"facts", "promote"}, args: []string{"--from", "feature", "--strategy", "keep-both"},
			readmeLine: 378, note: "promoting from a branch that has no active facts"},

		// entire brain facts retract <fact-id>
		{path: []string{"facts", "retract"}, args: []string{"fact:missing"},
			readmeLine: 379, note: "retracting a fact that was never authored"},

		// entire brain facts eval-compare --a <before.json> --b <after.json>
		{path: []string{"facts", "eval-compare"}, args: []string{"--a", "missing-a.json", "--b", "missing-b.json"},
			readmeLine: 418, note: "the README's shape, with absent inputs"},

		// `facts map` — documented in the fact-lifecycle section.
		{path: []string{"facts", "map"}},
	}
}

func TestREADMEExamplesAreExecutable(t *testing.T) {
	for _, dc := range documentedCommands() {
		t.Run(dc.name(), func(t *testing.T) {
			f := newVerifyFixture(t)

			// execute() returns the error rather than exiting, so a panic in
			// the command surfaces here as a failed test rather than a dead
			// process.
			out, err := execute(t, NewRootCommand(f.opts), dc.invocation()...)

			if err != nil && isUnknownCommandOrFlag(err.Error()) {
				t.Fatalf("README line %d documents %q, which the binary rejects: %v\n%s",
					dc.readmeLine, strings.Join(dc.invocation(), " "), err, out)
			}
			if err == nil && strings.TrimSpace(out) == "" {
				t.Fatalf("%q succeeded silently — a user cannot tell whether it did anything", dc.name())
			}
			if err != nil && strings.TrimSpace(err.Error()) == "" {
				t.Fatalf("%q failed with an empty error message", dc.name())
			}
		})
	}
}

// TestDocumentedCommandsExplainThemselves covers the other half of the fresh
// clone: --help must work before anything is built, because it is what a user
// reaches for the moment a command fails. Help is served by cobra without
// touching the brain, so unlike the test above this one expects success every
// time.
func TestDocumentedCommandsExplainThemselves(t *testing.T) {
	for _, dc := range documentedCommands() {
		t.Run(dc.name(), func(t *testing.T) {
			f := newVerifyFixture(t)
			args := append(append([]string{}, dc.path...), "--help")

			out, err := execute(t, NewRootCommand(f.opts), args...)
			if err != nil {
				t.Fatalf("%s --help failed: %v\n%s", dc.name(), err, out)
			}
			if !strings.Contains(out, "Usage:") {
				t.Fatalf("%s --help printed no usage:\n%s", dc.name(), out)
			}
			// The first line is the one-line summary the grouped
			// `entire-brain --help` listing shows. A command with none is
			// invisible in the exact place a user goes looking for it.
			if strings.TrimSpace(strings.SplitN(out, "\n", 2)[0]) == "" {
				t.Fatalf("%s has no short description", dc.name())
			}
		})
	}
}

func isUnknownCommandOrFlag(msg string) bool {
	return strings.Contains(msg, "unknown command") ||
		strings.Contains(msg, "unknown flag") ||
		strings.Contains(msg, "unknown shorthand flag")
}

// TestDocumentedCommandsAreDiscoverable closes the gap between what the docs
// tell a reader to run and what `--help` will admit exists.
//
// `doctor` and `config` were both hidden. Meanwhile scripts/install.sh runs
// `entire brain config init`, runs `entire brain doctor`, and closes by telling
// the reader "re-run checks: entire brain doctor"; the README documents doctor's
// exit-code contract in its own section. A user who follows that advice once and
// later greps `--help` finds nothing, and concludes the command was removed.
//
// Every command named in a fenced block or inline code span of README.md,
// docs/getting-started.md, docs/operations.md or scripts/install.sh must appear
// in `--help`. Hiding one again is fine -- but then it has to stop being
// advertised, and this test says which document to edit.
func TestDocumentedCommandsAreDiscoverable(t *testing.T) {
	root := NewRootCommand(Options{Version: "test"})

	// Only the surfaces a new user is actually pointed at. Design documents and
	// plans describe futures, not the installed binary.
	sources := []string{
		"../../README.md",
		"../../docs/getting-started.md",
		"../../docs/operations.md",
		"../../scripts/install.sh",
	}

	// `entire brain <verb>` is the spelling every one of these documents uses,
	// because all four describe the plugin install.
	mention := regexp.MustCompile(`entire brain ([a-z][a-z-]*)`)

	visible := map[string]bool{}
	for _, c := range root.Commands() {
		if c.Hidden {
			continue
		}
		visible[c.Name()] = true
		for _, alias := range c.Aliases {
			visible[alias] = true
		}
	}

	// Deliberately hidden AND deliberately documented. Each is a developer or
	// machine surface whose reason for hiding is recorded at its registration
	// in root.go and still holds; the documents that name them address that
	// audience, not a new user. Adding to this list is how a decision to keep
	// something hidden gets written down -- a new hidden-but-documented command
	// fails this test until somebody does.
	hiddenOnPurpose := map[string]string{
		"review":           "machine contract for the host CLI's `entire review`, not a human verb",
		"history-eval":     "measurement harness for the retrieval layer; developer tooling",
		"history-eval-gen": "measurement harness for the retrieval layer; developer tooling",
	}

	seen := map[string]string{}
	for _, source := range sources {
		data, err := os.ReadFile(source)
		if err != nil {
			t.Fatalf("read %s: %v", source, err)
		}
		for _, match := range mention.FindAllStringSubmatch(string(data), -1) {
			verb := match[1]
			if _, ok := seen[verb]; !ok {
				seen[verb] = source
			}
		}
	}
	if len(seen) == 0 {
		t.Fatal("no documented commands found -- the test is checking nothing")
	}

	for verb, source := range seen {
		// A word that is not a command at all is a prose false positive
		// ("entire brain from scratch"), not a discoverability failure.
		if cmd, _, err := root.Find([]string{verb}); err != nil || cmd == root {
			continue
		}
		if visible[verb] {
			if reason, ok := hiddenOnPurpose[verb]; ok {
				t.Errorf("`%s` is visible in --help but still listed as hidden on purpose (%s): drop it from hiddenOnPurpose", verb, reason)
			}
			continue
		}
		if _, ok := hiddenOnPurpose[verb]; ok {
			continue
		}
		t.Errorf("%s tells the reader to run `entire brain %s`, but it is hidden from --help: unhide it, or stop advertising it", source, verb)
	}
}
package cli

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// fakePlainEmbedder implements Embedder but NOT queryEmbedder (like Model2Vec).
type fakePlainEmbedder struct{ last string }

func (f *fakePlainEmbedder) Embed(t string) []float32 { f.last = t; return []float32{1, 0} }
func (f *fakePlainEmbedder) Dim() int                 { return 2 }
func (f *fakePlainEmbedder) ID() string               { return "fake-plain" }

// fakeAsymEmbedder implements queryEmbedder (like EmbeddingGemma): a query is
// embedded with a different prefix/vector than a document.
type fakeAsymEmbedder struct{ lastQuery, lastDoc string }

func (f *fakeAsymEmbedder) Embed(t string) []float32      { f.lastDoc = t; return []float32{1, 0} }
func (f *fakeAsymEmbedder) EmbedQuery(t string) []float32 { f.lastQuery = t; return []float32{0, 1} }
func (f *fakeAsymEmbedder) Dim() int                      { return 2 }
func (f *fakeAsymEmbedder) ID() string                    { return "fake-asym" }

func TestEmbedQueryUsesQueryEmbedderWhenAvailable(t *testing.T) {
	fe := &fakeAsymEmbedder{}
	rr := newSemanticReranker(fe)
	v := rr.embedQuery("find facts")
	if len(v) != 2 || v[1] != 1 {
		t.Fatalf("expected the EmbedQuery vector {0,1}, got %v", v)
	}
	if fe.lastQuery != "find facts" || fe.lastDoc != "" {
		t.Fatalf("query should route to EmbedQuery only: q=%q d=%q", fe.lastQuery, fe.lastDoc)
	}
}

func TestEmbedQueryFallsBackToEmbed(t *testing.T) {
	fe := &fakePlainEmbedder{}
	rr := newSemanticReranker(fe)
	v := rr.embedQuery("find facts")
	if len(v) != 2 || v[0] != 1 {
		t.Fatalf("expected the Embed vector {1,0}, got %v", v)
	}
	if fe.last != "find facts" {
		t.Fatalf("query should route to Embed: %q", fe.last)
	}
}

func TestConfiguredEmbedderUsesOllamaWhenReachable(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_ = json.NewEncoder(w).Encode(map[string]any{"embeddings": [][]float32{{0.1, 0.2}}})
	}))
	defer srv.Close()
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "ollama")
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", srv.URL)
	e, warn := configuredEmbedder()
	if _, ok := e.(*ollamaEmbedder); !ok {
		t.Fatalf("expected the ollama embedder when reachable, got %T", e)
	}
	if warn != "" {
		t.Fatalf("no warning expected when reachable, got %q", warn)
	}
}

func TestConfiguredEmbedderFallsBackOnEmptyEmbeddingBody(t *testing.T) {
	// A server that answers 200 but returns no embedding (wrong model / error
	// body) must be treated as not usable, not selected as the embedder.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_ = json.NewEncoder(w).Encode(map[string]any{"embeddings": [][]float32{}})
	}))
	defer srv.Close()
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "ollama")
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", srv.URL)
	e, warn := configuredEmbedder()
	if _, ok := e.(*ollamaEmbedder); ok {
		t.Fatal("a 200 with an empty embeddings array must not select the ollama embedder")
	}
	if e == nil {
		t.Fatal("expected the Model2Vec fallback, got nil")
	}
	if warn == "" {
		t.Fatal("expected a fallback warning")
	}
}

func TestConfiguredEmbedderFallsBackWhenOllamaUnreachable(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "ollama")
	// Port 1 refuses immediately, so the probe fails fast and the selector must
	// fall back to the bundled Model2Vec model rather than returning the (dead)
	// ollama embedder or silently dropping the semantic arm.
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", "http://127.0.0.1:1/api/embed")
	e, warn := configuredEmbedder()
	if e == nil {
		t.Fatal("expected a fallback embedder, got nil")
	}
	if _, ok := e.(*ollamaEmbedder); ok {
		t.Fatal("expected fallback to the static embedder, got the ollama embedder")
	}
	if warn == "" {
		t.Fatal("expected a fallback warning when the opt-in server is unreachable")
	}
}

func TestConfiguredEmbedderDefaultsToStatic(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "")
	e, warn := configuredEmbedder()
	if e == nil {
		t.Fatal("expected the bundled static embedder by default")
	}
	if _, ok := e.(*ollamaEmbedder); ok {
		t.Fatal("default must not select the ollama embedder")
	}
	if warn != "" {
		t.Fatalf("no warning expected on the default path, got %q", warn)
	}
}

func TestOllamaEmbedderURLOverride(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", "http://127.0.0.1:11500")
	if got := newOllamaEmbedder().url; got != "http://127.0.0.1:11500" {
		t.Fatalf("url override = %q", got)
	}
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", "")
	if got := newOllamaEmbedder().url; got != "http://localhost:11434/api/embed" {
		t.Fatalf("default url = %q", got)
	}
}

// REDACTED guards the loopback-guard
// degrade path: a rejected ENTIRE_BRAIN_EMBED_URL must fall back to the
// bundled Model2Vec embedder with a warning — not panic on the nil guard
// result (the exact hardening scenario must not crash retrieval).
func REDACTED(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "ollama")
	t.Setenv("ENTIRE_BRAIN_EMBED_URL", "http://example.com:11434/api/embed")
	e, warn := configuredEmbedder()
	if e == nil {
		t.Fatalf("expected the bundled fallback embedder, got nil (warn: %s)", warn)
	}
	if !strings.Contains(warn, "loopback") || !strings.Contains(warn, "falling back") {
		t.Fatalf("warning should explain the loopback rejection and fallback, got %q", warn)
	}
	if _, ok := e.(*staticEmbedder); !ok {
		t.Fatalf("fallback should be the bundled static embedder, got %T", e)
	}
}
package cli

import (
	"fmt"
	"testing"
	"time"
)

type cachedRankBenchmarkEmbedder struct {
	dim   int
	query []float32
}

func (e *cachedRankBenchmarkEmbedder) Embed(string) []float32      { return nil }
func (e *cachedRankBenchmarkEmbedder) EmbedQuery(string) []float32 { return e.query }
func (e *cachedRankBenchmarkEmbedder) Dim() int                    { return e.dim }
func (e *cachedRankBenchmarkEmbedder) ID() string                  { return "cached-rank-benchmark" }

func BenchmarkRankFactsFusedCachedVectors(b *testing.B) {
	for _, count := range []int{44, 128, 512, 5_000} {
		b.Run(fmt.Sprintf("facts=%d", count), func(b *testing.B) {
			b.Setenv("ENTIRE_BRAIN_FACTS_BM25", "")
			const dim = 512 // the bundled Model2Vec model's embedding dimension
			query := benchmarkRankVector(17, dim)
			e := &cachedRankBenchmarkEmbedder{dim: dim, query: query}
			rr := newSemanticReranker(e)
			facts := make([]factRecord, count)
			base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
			for i := range facts {
				id := fmt.Sprintf("fact:%08d", i)
				facts[i] = factRecord{
					ID:        id,
					Text:      fmt.Sprintf("component %d retry behavior and release policy", i),
					Status:    factStatusActive,
					UpdatedAt: base.Add(time.Duration(i) * time.Second),
				}
				rr.cache[id] = benchmarkRankVector(i+1, dim)
			}

			b.ReportAllocs()
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				if got := rankFactsFused(facts, "retry release behavior", 6, false, rr); len(got) != 6 {
					b.Fatalf("result count = %d, want 6", len(got))
				}
			}
		})
	}
}

func benchmarkRankVector(seed, dim int) []float32 {
	v := make([]float32, dim)
	for i := range v {
		// Deterministic, non-zero, finite vectors with plentiful score ties and
		// near-ties exercise both ranking work and its stable tie semantics.
		v[i] = float32(((seed+11)*(i+17))%257-128) / 128
	}
	return v
}

