		t.Errorf("absent cache should load empty, got %d", len(got))
	}
}

// TestRerankerDiskCacheReusesVectors verifies the disk-backed reranker persists
// embedded vectors and a fresh reranker reads them back (no re-embed needed),
// and that flush prunes a fact that disappears.
func TestRerankerDiskCacheReusesVectors(t *testing.T) {
	e := defaultEmbedder()
	if e == nil {
		t.Skip("embedding backend unavailable")
	}
	dir := t.TempDir()
	now := time.Now()
	facts := []factRecord{
		{ID: "fact:a", Text: "indentation uses spaces", Status: factStatusActive, UpdatedAt: now},
		{ID: "fact:b", Text: "tokens are validated per request", Status: factStatusActive, UpdatedAt: now},
	}
	rr := newSemanticRerankerForBranch(e, dir, "main")
	_ = rankFactsFused(facts, "whitespace policy", 5, false, rr)
	if err := rr.flush(); err != nil {
		t.Fatalf("flush: %v", err)
	}
	// Read back through the same per-build store the reranker writes
	// (vectors.bin on pure-Go builds, the vec0 SQLite store under brain_cgo).
	if got := newVectorStore(dir, "main", factEmbeddingModelID(e.ID()), e.Dim()).load(); len(got) != 2 {
		t.Fatalf("expected 2 persisted vectors, got %d", len(got))
	}

	// A fresh reranker should load both vectors from disk (no dirty embed).
	rr2 := newSemanticRerankerForBranch(e, dir, "main")
	if len(rr2.cache) != 2 {
		t.Fatalf("expected 2 cached vectors loaded, got %d", len(rr2.cache))
	}
	_ = rankFactsFused(facts[:1], "whitespace policy", 5, false, rr2) // touch only fact:a
	if rr2.dirty {
		t.Errorf("ranking cached facts should not mark dirty")
	}
	// Force a prune: only fact:a was touched, so a dirty save would drop fact:b.
	rr2.dirty = true
	if err := rr2.flush(); err != nil {
		t.Fatalf("flush2: %v", err)
	}
	if got := newVectorStore(dir, "main", factEmbeddingModelID(e.ID()), e.Dim()).load(); len(got) != 1 {
		t.Errorf("expected prune to 1 touched vector, got %d", len(got))
	}
}

func TestRerankerFlushDropsInvalidCachedVectorWhenRepairFails(t *testing.T) {
	dir := t.TempDir()
	fact := factRecord{ID: "fact:invalid", Text: "durable checkpoint policy", Status: factStatusActive}
	e := &fakeFusionEmbedder{fail: func(text string) bool { return text == factEmbeddingText(fact) }}
	store := newVectorStore(dir, "main", factEmbeddingModelID(e.ID()), e.Dim())
	present := map[string]struct{}{fact.ID: {}}
	if err := store.savePresent(map[string][]float32{fact.ID: {0, 0}}, present); err != nil {
		t.Fatal(err)
	}

	rr := newSemanticRerankerForBranch(e, dir, "main")
	if vector := rr.factVector(fact); vector != nil {
		t.Fatalf("failed repair returned a vector: %v", vector)
	}
	if err := rr.flush(); err != nil {
		t.Fatal(err)
	}
	if _, ok := store.load()[fact.ID]; ok {
		t.Fatal("flush resurrected the invalid persisted vector")
	}
}

// TestRerankerRetainPreservesOutOfScopeVectors guards the scope-flush fix: a
// scoped run that ranks only a subset must not prune the cached vectors of the
// facts it didn't rank, as long as those facts still exist in the branch.
func TestRerankerRetainPreservesOutOfScopeVectors(t *testing.T) {
	e := defaultEmbedder()
	if e == nil {
		t.Skip("embedding backend unavailable")
	}
	dir := t.TempDir()
	now := time.Now()
	facts := []factRecord{
		{ID: "fact:a", Text: "indentation uses spaces", Status: factStatusActive, UpdatedAt: now},
		{ID: "fact:b", Text: "tokens are validated per request", Status: factStatusActive, UpdatedAt: now},
	}
	// Seed the cache with both vectors.
	rr := newSemanticRerankerForBranch(e, dir, "main")
	_ = rankFactsFused(facts, "whitespace policy", 5, false, rr)
	if err := rr.flush(); err != nil {
		t.Fatalf("seed flush: %v", err)
	}

	// A scoped run ranks only fact:a but retains the full branch set, then
	// embeds a new fact so the flush actually rewrites the file.
	rr2 := newSemanticRerankerForBranch(e, dir, "main")
	scoped := facts[:1] // simulate --scope dropping fact:b
	_ = rankFactsFused(scoped, "whitespace policy", 5, false, rr2)
	rr2.retain(facts)                                              // full branch fact set
	_ = rr2.factVector(factRecord{ID: "fact:c", Text: "new fact"}) // force dirty
	if err := rr2.flush(); err != nil {
		t.Fatalf("scoped flush: %v", err)
	}
	got := newVectorStore(dir, "main", factEmbeddingModelID(e.ID()), e.Dim()).load()
	if _, ok := got["fact:b"]; !ok {
		t.Errorf("retain should preserve out-of-scope fact:b across flush; cache has %d entries: %v", len(got), keysOf(got))
	}
}

// TestRerankerFlushPrunesWithoutDirtyEmbed guards the prune-without-embed fix: a
// run that embeds nothing new (no dirty) but sees fewer facts (one departed the
// branch) must still rewrite the cache to drop the stale vector.
func TestRerankerFlushPrunesWithoutDirtyEmbed(t *testing.T) {
	e := defaultEmbedder()
	if e == nil {
		t.Skip("embedding backend unavailable")
	}
	dir := t.TempDir()
	now := time.Now()
	facts := []factRecord{
		{ID: "fact:a", Text: "indentation uses spaces", Status: factStatusActive, UpdatedAt: now},
		{ID: "fact:b", Text: "tokens are validated per request", Status: factStatusActive, UpdatedAt: now},
	}
	// Seed both vectors on disk.
	rr := newSemanticRerankerForBranch(e, dir, "main")
	_ = rankFactsFused(facts, "whitespace policy", 5, false, rr)
	if err := rr.flush(); err != nil {
		t.Fatalf("seed flush: %v", err)
	}

	// fact:b leaves the branch. This run loads the cache, retains only the
	// remaining fact, and embeds nothing new — so dirty stays false.
	rr2 := newSemanticRerankerForBranch(e, dir, "main")
	rr2.retain(facts[:1])
	if rr2.dirty {
		t.Fatalf("no embed happened; dirty should be false")
	}
	if err := rr2.flush(); err != nil {
		t.Fatalf("prune flush: %v", err)
	}
	got := newVectorStore(dir, "main", factEmbeddingModelID(e.ID()), e.Dim()).load()
	if _, ok := got["fact:b"]; ok {
		t.Errorf("departed fact:b should be pruned even without a dirty embed; have %v", keysOf(got))
	}
	if len(got) != 1 {
		t.Errorf("expected 1 vector after prune, got %d", len(got))
	}
}

func keysOf(m map[string][]float32) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	return ks
}
package cli

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"math"
	"os"
	"testing"

	entirebrain "github.com/ashtom/entire-brain"
)

func testEmbedder(t *testing.T) *staticEmbedder {
	t.Helper()
	e, err := loadStaticEmbedder(entirebrain.EmbedModel)
	if err != nil {
		t.Fatalf("loadStaticEmbedder: %v", err)
	}
	return e
}

// cosine aliases the production helper so the tests exercise the same code.
func cosine(a, b []float32) float64 { return cosineFloat32(a, b) }

// TestEmbedGoldenParity is the load-bearing correctness check: the pure-Go
// tokenizer + pooling must reproduce the reference Model2Vec embeddings (up to
// int8 quantization). A tokenizer bug would drop cosine far below the floor.
func TestEmbedGoldenParity(t *testing.T) {
	raw, err := os.ReadFile("testdata/embed_golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var golden struct {
		Dim     int         `json:"dim"`
		Texts   []string    `json:"texts"`
		Vectors [][]float32 `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	e := testEmbedder(t)
	if e.Dim() != golden.Dim {
		t.Fatalf("dim mismatch: embedder %d golden %d", e.Dim(), golden.Dim)
	}
	for i, text := range golden.Texts {
		got := e.Embed(text)
		want := golden.Vectors[i]
		if text == "" {
			// empty input has no token signal: expect the zero vector.
			var norm float64
			for _, v := range got {
				norm += float64(v) * float64(v)
			}
			if norm > 1e-9 {
				t.Errorf("empty text should embed to zero vector, got norm %v", norm)
			}
			continue
		}
		if c := cosine(got, want); c < 0.995 {
			t.Errorf("text %q parity cosine %.5f < 0.995 (tokenizer/pooling mismatch)", text, c)
		}
	}
}

// TestEmbedSemanticOrdering sanity-checks that the model captures paraphrase —
// the property that lets it reach term-disjoint relevant facts. A query should
// be closer to its paraphrase than to an unrelated sentence.
func TestEmbedSemanticOrdering(t *testing.T) {
	e := testEmbedder(t)
	cases := []struct{ query, related, unrelated string }{
		{"use spaces for indentation", "the code is indented with space characters, not tabs", "the deployment pipeline runs nightly"},
		{"how is authentication handled", "tokens are validated before each request", "the cat sat on the mat"},
	}
	for _, c := range cases {
		q := e.Embed(c.query)
		rel := cosine(q, e.Embed(c.related))
		unrel := cosine(q, e.Embed(c.unrelated))
		if rel <= unrel {
			t.Errorf("query %q: related cosine %.3f should exceed unrelated %.3f", c.query, rel, unrel)
		}
	}
}

func TestWordPieceDecomposition(t *testing.T) {
	e := testEmbedder(t)
	// A rare/long compound should decompose into multiple subword pieces (more
	// ids than whole words) rather than collapsing to a single [UNK].
	ids := e.tokenize("supercalifragilistic")
	if len(ids) < 2 {
		t.Errorf("expected subword decomposition, got %d ids", len(ids))
	}
	for _, id := range ids {
		if id == e.unkID {
			t.Errorf("unexpected [UNK] in decomposition of a Latin word: %v", ids)
		}
	}
	// Punctuation is isolated: trailing "." becomes its own token, so
	// "tabs." has exactly one more id than "tabs".
	if got, base := len(e.tokenize("tabs.")), len(e.tokenize("tabs")); got != base+1 {
		t.Errorf("expected punctuation isolated as one extra token: %d vs base %d", got, base)
	}
}

func TestStripAccent(t *testing.T) {
	cases := map[rune]rune{'é': 'e', 'ñ': 'n', 'ü': 'u', 'č': 'c'}
	for in, want := range cases {
		got, ok := stripAccent(in)
		if !ok || got != want {
			t.Errorf("stripAccent(%q) = %q,%v; want %q,true", in, got, ok, want)
		}
	}
	if _, ok := stripAccent('a'); ok {
		t.Errorf("stripAccent('a') should report not-an-accent")
	}
	if got, ok := stripAccent('́'); !ok || got != 0 {
		t.Errorf("combining mark should be dropped, got %q,%v", got, ok)
	}
}

func TestDefaultEmbedderLoads(t *testing.T) {
	if defaultEmbedder() == nil {
		t.Fatal("bundled embed model failed to load")
	}
}

// encodeTestModel builds a minimal valid embedmodel.bin byte layout (matching
// the format in scripts/convert_embedmodel.py) so the header-validation paths
// can be exercised without the 32 MB bundled asset.
func encodeTestModel(vocab []string, dim int, unkID uint32) []byte {
	var b bytes.Buffer
	b.WriteString(embedModelMagic)
	_ = binary.Write(&b, binary.LittleEndian, uint32(1)) // version
	_ = binary.Write(&b, binary.LittleEndian, uint16(len("test")))
	b.WriteString("test")
	_ = binary.Write(&b, binary.LittleEndian, uint32(dim))
	_ = binary.Write(&b, binary.LittleEndian, uint32(len(vocab)))
	_ = binary.Write(&b, binary.LittleEndian, uint32(1)) // dtype int8
	_ = binary.Write(&b, binary.LittleEndian, uint32(0)) // flags
	_ = binary.Write(&b, binary.LittleEndian, unkID)
	_ = binary.Write(&b, binary.LittleEndian, uint16(len("##")))
	b.WriteString("##")
	for _, tok := range vocab {
		_ = binary.Write(&b, binary.LittleEndian, uint16(len(tok)))
		b.WriteString(tok)
	}
	for i := 0; i < dim; i++ {
		_ = binary.Write(&b, binary.LittleEndian, math.Float32bits(1.0)) // scales
	}
	b.Write(make([]byte, len(vocab)*dim)) // zero int8 matrix
	return b.Bytes()
}

func TestLoadStaticEmbedderRejectsBadUnkID(t *testing.T) {
	vocab := []string{"[UNK]", "hello", "world"}
	// A valid unkID loads cleanly.
	if _, err := loadStaticEmbedder(encodeTestModel(vocab, 4, 0)); err != nil {
		t.Fatalf("valid model should load: %v", err)
	}
	// An out-of-range unkID must fail the load rather than panic later in Embed
	// (out-of-bounds matrix slice) on an unknown token.
	if _, err := loadStaticEmbedder(encodeTestModel(vocab, 4, uint32(len(vocab)))); err == nil {
		t.Fatal("expected out-of-range unkID to be rejected at load")
	}
}

func TestLoadStaticEmbedderRejectsOversizedHeader(t *testing.T) {
	// Patch the dim field (offset 14: magic[4] + version[4] + nameLen[2] +
	// "test"[4]) to a value far larger than the file, simulating a corrupt
	// header. The preflight must reject it rather than attempt a giant
	// allocation before take() discovers the truncation.
	raw := encodeTestModel([]string{"[UNK]", "a"}, 4, 0)
	binary.LittleEndian.PutUint32(raw[14:], 1<<30)
	if _, err := loadStaticEmbedder(raw); err == nil {
		t.Fatal("expected oversized header to be rejected before allocation")
	}
}

