		t.Fatalf("fact count = %d, want %d: got=%v want=%v", len(got), len(want), got, want)
	}
	for i := range got {
		if got[i].ID != want[i].ID {
			t.Fatalf("rank %d = %s, want %s", i+1, got[i].ID, want[i].ID)
		}
	}
}
