// TestCanonicalFieldTableMatchesStructTags is the drift guard: the normative
// field table in canonical.go must name exactly the JSON tags declared in
// contract.go, with `omitempty` present exactly where the table says a default
// is omitted. Tags are the contract, so a mismatch is a bug in the table, never
// a reason to change a tag.
func TestCanonicalFieldTableMatchesStructTags(t *testing.T) {
	cases := []struct {
		spec *canonicalType
		typ  reflect.Type
	}{
		{canonicalArtifact, reflect.TypeOf(BrainArtifact{})},
		{canonicalManifest, reflect.TypeOf(BrainManifest{})},
		{canonicalContentRef, reflect.TypeOf(ContentRef{})},
		{canonicalSnapshotRef, reflect.TypeOf(SnapshotRef{})},
		{canonicalOverlayRef, reflect.TypeOf(OverlayRef{})},
		{canonicalFactsRef, reflect.TypeOf(FactsRef{})},
	}

	for _, tc := range cases {
		t.Run(tc.spec.Name, func(t *testing.T) {
			if tc.spec.Name != tc.typ.Name() {
				t.Fatalf("field table name %q does not match Go type %q", tc.spec.Name, tc.typ.Name())
			}
			if got, want := len(tc.spec.Fields), tc.typ.NumField(); got != want {
				t.Fatalf("field table has %d fields, struct has %d", got, want)
			}
			for i := 0; i < tc.typ.NumField(); i++ {
				sf := tc.typ.Field(i)
				parts := strings.Split(sf.Tag.Get("json"), ",")
				name := parts[0]
				hasOmitempty := false
				for _, p := range parts[1:] {
					if p == "omitempty" {
						hasOmitempty = true
					}
				}

				var spec *canonicalField
				for j := range tc.spec.Fields {
					if tc.spec.Fields[j].Key == name {
						spec = &tc.spec.Fields[j]
						break
					}
				}
				if spec == nil {
					t.Fatalf("struct field %s has JSON tag %q with no entry in the canonical field table", sf.Name, name)
				}
				if got := spec.Omitted != omitNever; got != hasOmitempty {
					t.Fatalf("%s.%s: table says omitted=%v, struct tag omitempty=%v", tc.spec.Name, name, got, hasOmitempty)
				}
			}
		})
	}
}

// TestCanonicalKeySortIsUTF16 pins the RFC 8785 ordering rule for the unknown
// keys a future minor could introduce: sorting is by UTF-16 code unit, so a
// non-BMP key sorts BEFORE a high-BMP one even though its UTF-8 bytes are
// larger.
func TestCanonicalKeySortIsUTF16(t *testing.T) {
	// U+1F9E0 (surrogate pair 0xD83E,0xDDE0) < U+FB00 in UTF-16 order, but its
	// UTF-8 bytes (0xF0...) sort after U+FB00's (0xEF...).
	raw := "{\"ﬀ\":1,\"\U0001F9E0\":2}"
	got := mustCanonicalize(t, raw)
	iAstral := strings.Index(got, "\U0001F9E0")
	iBMP := strings.Index(got, "ﬀ")
	if iAstral < 0 || iBMP < 0 {
		t.Fatalf("keys missing from output: %s", got)
	}
	if iAstral > iBMP {
		t.Fatalf("keys sorted by UTF-8 bytes, not UTF-16 code units: %s", got)
	}
}

// TestCanonicalizeRejectsDuplicateKeys proves canonical form refuses duplicated
// object members instead of inheriting Go's last-wins decode: a signature over
// re-canonicalized bytes must never validate transported bytes whose
// first-occurrence values a first-wins parser would read instead.
func TestCanonicalizeRejectsDuplicateKeys(t *testing.T) {
	base := `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"}}`
	if _, err := Canonicalize([]byte(base)); err != nil {
		t.Fatalf("baseline artifact must canonicalize: %v", err)
	}
	for name, doc := range map[string]string{
		"top level": `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"},` +
			`"manifest":{"repo_key":"evil","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"}}`,
		"nested known object": `{"manifest":{"repo_key":"evil","repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"}}`,
		"unknown object": `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"},` +
			`"future":{"k":1,"k":2}}`,
		"object inside array": `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"},` +
			`"facts":[{"branch":"main","branch":"other","content":{"digest":"sha256:aa","size":1}}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if _, err := Canonicalize([]byte(doc)); err == nil {
				t.Fatalf("duplicate member accepted: %s", doc)
			} else if !strings.Contains(err.Error(), "duplicate object member") {
				t.Fatalf("wrong error for duplicate member: %v", err)
			}
		})
	}
}

// TestCanonicalTimeAcceptsLowercaseSeparators proves the RFC 3339 forms Go's
// time.Parse rejects but section 5.6 permits — lowercase 't' and 'z' — verify.
func TestCanonicalTimeAcceptsLowercaseSeparators(t *testing.T) {
	doc := `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-06-01t12:00:00z"}}`
	got, err := Canonicalize([]byte(doc))
	if err != nil {
		t.Fatalf("lowercase RFC 3339 separators must canonicalize: %v", err)
	}
	if !strings.Contains(string(got), `"generated_at":"2026-06-01T12:00:00Z"`) {
		t.Fatalf("lowercase separators not normalized: %s", got)
	}
}

// TestCanonicalizeBoundsNestingDepth proves attacker-controlled nesting is an
// error, not a runtime stack overflow: Canonicalize is an entry point for
// untrusted bytes and must never kill the verifying process.
func TestCanonicalizeBoundsNestingDepth(t *testing.T) {
	deep := strings.Repeat("[", 100000) + strings.Repeat("]", 100000)
	doc := `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"},"future":` + deep + `}`
	if _, err := Canonicalize([]byte(doc)); err == nil {
		t.Fatal("pathological nesting must be rejected")
	} else if !strings.Contains(err.Error(), "nesting deeper") {
		t.Fatalf("wrong error for pathological nesting: %v", err)
	}
	// A handful of levels — beyond any real artifact but under the bound — is fine.
	ok := `{"manifest":{"repo_key":"r","brain_schema_version":"1.0","generated_at":"2026-01-01T00:00:00Z"},"future":` +
		strings.Repeat("[", 40) + "1" + strings.Repeat("]", 40) + `}`
	if _, err := Canonicalize([]byte(ok)); err != nil {
		t.Fatalf("legitimate nesting rejected: %v", err)
	}
}
package brainwire

import (
	"bytes"
	"encoding/json"
	"reflect"
	"strings"
	"testing"
	"time"
)

// representativeArtifact builds a BrainArtifact that exercises every wire type
// and both provider and reference fields. GeneratedAt is parsed (not
// constructed with time.Date) so it uses the exact internal representation that
// json decoding produces, keeping reflect.DeepEqual reliable after a round trip.
func representativeArtifact(t *testing.T) *BrainArtifact {
	t.Helper()
	ts, err := time.Parse(time.RFC3339, "2026-06-01T12:00:00Z")
	if err != nil {
		t.Fatalf("parse timestamp: %v", err)
	}
	return NewBrainArtifact("gh/org/repo", "main", ts).
		SetProvider("entire-graph", "0.1.0", "1.1").
		AddSnapshot(SnapshotRef{
			Commit: "abc123",
			Tree:   "tree789",
			Content: ContentRef{
				Digest:    "sha256:1111111111111111111111111111111111111111111111111111111111111111",
				Size:      2048,
				MediaType: "application/json",
				Path:      "semantic/snapshots/abc123/snapshot.json",
			},
		}).
		AddOverlay(OverlayRef{
			BaseCommit: "abc123",
			HeadCommit: "def456",
			Branch:     "feature-x",
			Content: ContentRef{
				Digest:    "sha256:2222222222222222222222222222222222222222222222222222222222222222",
				Size:      512,
				MediaType: "application/json",
				Path:      "semantic/overlays/abc123..def456.json",
			},
		}).
		AddFacts(FactsRef{
			Branch: "main",
			Content: ContentRef{
				Digest:    "sha256:3333333333333333333333333333333333333333333333333333333333333333",
				Size:      4096,
				MediaType: "application/x-ndjson",
				Path:      "facts/main/facts.ndjson",
			},
		})
}

func TestBrainArtifactRoundTrip(t *testing.T) {
	original := representativeArtifact(t)

	b1, err := json.Marshal(original)
	if err != nil {
		t.Fatalf("marshal original: %v", err)
	}

	var decoded BrainArtifact
	if err := json.Unmarshal(b1, &decoded); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}

	// (a) deep-equality: the decoded artifact matches the original exactly.
	if !reflect.DeepEqual(*original, decoded) {
		t.Fatalf("round-trip changed the artifact:\n original=%#v\n decoded=%#v", *original, decoded)
	}

	// (a) byte-stability: re-marshaling the decoded artifact reproduces the
	// exact original bytes (declaration-ordered fields, ordered slices, no maps).
	b2, err := json.Marshal(decoded)
	if err != nil {
		t.Fatalf("marshal decoded: %v", err)
	}
	if !bytes.Equal(b1, b2) {
		t.Fatalf("marshal is not byte-stable:\n first=%s\nsecond=%s", b1, b2)
	}

	// The stamped version must be the local wire schema version.
	if decoded.Manifest.BrainSchemaVersion != BrainSchemaVersion {
		t.Fatalf("brain_schema_version = %q, want %q", decoded.Manifest.BrainSchemaVersion, BrainSchemaVersion)
	}
}

func TestCheckCompatibility(t *testing.T) {
	cases := []struct {
		name     string
		remote   string
		wantOK   bool
		wantWarn bool // whether warn should be non-empty
		wantErr  bool
	}{
		{name: "same version", remote: "1.0", wantOK: true},
		{name: "same major higher minor warns", remote: "1.7", wantOK: true, wantWarn: true},
		{name: "unknown greater major errors", remote: "2.0", wantErr: true},
		{name: "unknown lesser major errors", remote: "0.9", wantErr: true},
		{name: "missing minor errors", remote: "1", wantErr: true},
		{name: "too many components errors", remote: "1.0.0", wantErr: true},
		{name: "non-numeric errors", remote: "1.x", wantErr: true},
		{name: "empty errors", remote: "", wantErr: true},
		{name: "negative errors", remote: "-1.0", wantErr: true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ok, warn, err := CheckCompatibility(tc.remote)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("CheckCompatibility(%q) = (ok=%v, warn=%q, err=nil), want error", tc.remote, ok, warn)
				}
				if ok {
					t.Fatalf("CheckCompatibility(%q): ok must be false on error", tc.remote)
				}
				return
			}
			if err != nil {
				t.Fatalf("CheckCompatibility(%q) unexpected error: %v", tc.remote, err)
			}
			if ok != tc.wantOK {
				t.Fatalf("CheckCompatibility(%q) ok = %v, want %v", tc.remote, ok, tc.wantOK)
			}
			if gotWarn := warn != ""; gotWarn != tc.wantWarn {
				t.Fatalf("CheckCompatibility(%q) warn=%q; hasWarn=%v, want %v", tc.remote, warn, gotWarn, tc.wantWarn)
			}
		})
	}
}

// TestTolerantReaderIgnoresUnknownFields proves a reader on schema 1.0 decodes an
// artifact produced by a hypothetical newer minor that added fields at every
// level. This is the tolerant-reader guarantee: a plain json.Unmarshal (no
// DisallowUnknownFields) drops unknown fields instead of failing.
func TestTolerantReaderIgnoresUnknownFields(t *testing.T) {
	// A superset payload: valid 1.0 fields plus unknown additive fields a
	// future 1.x minor might introduce, at the manifest, artifact, and
	// reference levels.
	payload := `{
		"manifest": {
			"repo_key": "gh/org/repo",
			"default_branch": "main",
			"generated_at": "2026-06-01T12:00:00Z",
			"brain_schema_version": "1.4",
			"provider": "entire-graph",
			"provider_version": "0.2.0",
			"provider_schema_version": "1.2",
			"future_manifest_field": {"nested": ["anything", 1, true]}
		},
		"snapshots": [
			{
				"commit": "abc123",
				"tree": "tree789",
				"content": {
					"digest": "sha256:1111",
					"size": 10,
					"media_type": "application/json",
					"future_content_field": "ignored"
				},
				"future_snapshot_field": 42
			}
		],
		"facts": [
			{"branch": "main", "content": {"digest": "sha256:3333"}}
		],
		"future_top_level_field": ["ignored"]
	}`

	var decoded BrainArtifact
	if err := json.Unmarshal([]byte(payload), &decoded); err != nil {
		t.Fatalf("tolerant decode failed: %v", err)
	}

	// Known fields survived.
	if decoded.Manifest.RepoKey != "gh/org/repo" {
		t.Fatalf("repo_key = %q, want gh/org/repo", decoded.Manifest.RepoKey)
	}
	if decoded.Manifest.BrainSchemaVersion != "1.4" {
		t.Fatalf("brain_schema_version = %q, want 1.4", decoded.Manifest.BrainSchemaVersion)
	}
	if decoded.Manifest.ProviderSchemaVersion != "1.2" {
		t.Fatalf("provider_schema_version = %q, want 1.2", decoded.Manifest.ProviderSchemaVersion)
	}
	if len(decoded.Snapshots) != 1 || decoded.Snapshots[0].Commit != "abc123" {
		t.Fatalf("snapshots not decoded: %#v", decoded.Snapshots)
	}
	if decoded.Snapshots[0].Content.Digest != "sha256:1111" {
		t.Fatalf("snapshot content digest = %q", decoded.Snapshots[0].Content.Digest)
	}
	if len(decoded.Facts) != 1 || decoded.Facts[0].Branch != "main" {
		t.Fatalf("facts not decoded: %#v", decoded.Facts)
	}

	// And such a newer-minor artifact is compatible with a warning.
	ok, warn, err := CheckCompatibility(decoded.Manifest.BrainSchemaVersion)
	if err != nil || !ok {
		t.Fatalf("CheckCompatibility(1.4) = (ok=%v, err=%v), want ok, no error", ok, err)
	}
	if !strings.Contains(warn, "tolerant reader") {
		t.Fatalf("expected tolerant-reader warning, got %q", warn)
	}
}

// TestLocalSchemaVersionParses guards the package invariant that the local
// BrainSchemaVersion constant is itself a valid "major.minor" version.
func TestLocalSchemaVersionParses(t *testing.T) {
	if _, _, err := parseSchemaVersion(BrainSchemaVersion); err != nil {
		t.Fatalf("BrainSchemaVersion %q is not valid major.minor: %v", BrainSchemaVersion, err)
	}
	ok, warn, err := CheckCompatibility(BrainSchemaVersion)
	if err != nil || !ok || warn != "" {
		t.Fatalf("CheckCompatibility(local) = (ok=%v, warn=%q, err=%v), want (true, \"\", nil)", ok, warn, err)
	}
}
package factmerge

import (
	"bytes"
	"errors"
	"reflect"
	"strings"
	"testing"
	"time"
)

// The fact-set NDJSON blob is the shared, cross-member wire format (factsync
// pulls it from the hosted head and parses it with ParseNDJSON), so it becomes
// untrusted input the moment the brain is shared. These harnesses assert the two
// properties that matter for it: arbitrary bytes never panic, and anything the
// writer emits the reader can read back.
//
//	go test ./internal/factmerge -run xxx -fuzz FuzzParseNDJSON

func FuzzParseNDJSON(f *testing.F) {
	f.Add([]byte(`{"id":"fact:aa","paths":["a.b.c"],"text":"t","branch":"main","origin":"distilled","status":"active","provenance":[{"session_id":"s"}],"created_at":"2026-01-02T03:04:05Z","updated_at":"2026-01-02T03:04:05Z"}` + "\n"))
	f.Add([]byte("\n\n\n"))
	f.Add([]byte(`{"id":`))
	f.Add([]byte("\x00\x01 not json"))
	f.Add([]byte(`{"created_at":"not-a-time"}`))
	f.Add([]byte(`{"text":"` + strings.Repeat("<", MaxLineBytes/6+1) + `"}`))
	f.Add(append([]byte(`{"id":"`), append(bytes.Repeat([]byte("x"), 70*1024), []byte(`"}`)...)...))

	f.Fuzz(func(t *testing.T, data []byte) {
		records, err := ParseNDJSON(bytes.NewReader(data))
		if err != nil {
			return
		}
		// Re-encoding can expand a compact input through HTML escaping and
		// required fields. A size refusal is valid, but a successful write
		// must always be readable.
		var buf bytes.Buffer
		if err := WriteNDJSON(&buf, records); err != nil {
			if errors.Is(err, ErrRecordTooLarge) {
				if buf.Len() != 0 {
					t.Fatal("size refusal wrote a partial batch")
				}
				return
			}
			t.Fatalf("WriteNDJSON rejected records ParseNDJSON accepted: %v", err)
		}
		again, err := ParseNDJSON(bytes.NewReader(buf.Bytes()))
		if err != nil {
			t.Fatalf("ParseNDJSON rejected its own WriteNDJSON output: %v", err)
		}
		if len(again) != len(records) {
			t.Fatalf("round trip changed the record count: %d -> %d", len(records), len(again))
		}
	})
}

// FuzzNDJSONWriteReadRoundTrip drives the round trip from the STRUCT side: any
// record the store is willing to write must be readable back. A writer that can
// emit a line its own reader rejects is a store that bricks itself — and on the
// shared head, one member's oversized fact would brick every other member's sync.
func FuzzNDJSONWriteReadRoundTrip(f *testing.F) {
	f.Add("fact:aa", "a.b.c", "short text", "main", 1)
	f.Add("fact:bb", "a.b.c", strings.Repeat("x", 100*1024), "main", 1)
	f.Add("fact:cc", "a.b.c", "   unicode  ", "main", 3)

	f.Fuzz(func(t *testing.T, id, path, text, branch string, anchors int) {
		if anchors < 0 || anchors > 8 {
			return
		}
		rec := Record{
			ID:        id,
			Paths:     []string{path},
			Text:      text,
			Branch:    branch,
			Origin:    "distilled",
			Status:    StatusActive,
			CreatedAt: time.Unix(0, 0).UTC(),
			UpdatedAt: time.Unix(0, 0).UTC(),
		}
		for i := 0; i < anchors; i++ {
			rec.Provenance = append(rec.Provenance, Anchor{SessionID: "s"})
		}
		var buf bytes.Buffer
		if err := WriteNDJSON(&buf, []Record{rec}); err != nil {
			return // a record the writer refuses never reaches the store
		}
		got, err := ParseNDJSON(bytes.NewReader(buf.Bytes()))
		if err != nil {
			t.Fatalf("the reader rejected a record the writer emitted (%d bytes): %v", buf.Len(), err)
		}
		if len(got) != 1 || !reflect.DeepEqual(got[0], rec) {
			t.Fatalf("round trip changed the record:\nwant %#v\ngot  %#v", rec, got)
		}
	})
}

// FuzzRecordIdentity pins the content-addressing helpers: normalization must be
// idempotent and the derived id must be a pure function of the normalized form.
func FuzzRecordIdentity(f *testing.F) {
	f.Add("Some Fact Text", "a.b.c,d.e.f")
	f.Add("  spaced   out  ", "A.B.C,,zzz")
	f.Add("  ", "x")
	f.Fuzz(func(t *testing.T, text, rawPaths string) {
		paths := NormalizePaths(strings.Split(rawPaths, ","))
		if got := NormalizePaths(paths); !reflect.DeepEqual(got, paths) {
			t.Fatalf("NormalizePaths is not idempotent: %#v -> %#v", paths, got)
		}
		if NormalizeText(NormalizeText(text)) != NormalizeText(text) {
			t.Fatalf("NormalizeText is not idempotent for %q", text)
		}
		if RecordID(text, paths) != RecordID(NormalizeText(text), paths) {
			t.Fatalf("RecordID is not a function of the normalized text: %q", text)
		}
	})
}

