package cli

import (
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// promotableCorpusDir builds a brain dir containing a corpus with one
// promotable, corroborated deploy:release consolidation, and returns the dir.
func promotableCorpusDir(t *testing.T, now time.Time) string {
	t.Helper()
	brainDir := t.TempDir()
	transcriptPath := filepath.Join(brainDir, "sessions", "main", "x.jsonl")
	if err := os.MkdirAll(filepath.Dir(transcriptPath), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(transcriptPath, []byte("deploy release\nmise build\nmise deploy\nverify release\ndone\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	path, err := prepareBrainRelativeSQLiteFile(brainDir, patternCorpusPath)
	if err != nil {
		t.Fatal(err)
	}
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		t.Fatal(err)
	}
	for _, s := range patternCorpusSchema {
		if _, err := db.Exec(s); err != nil {
			t.Fatalf("schema: %v", err)
		}
	}
	for i := 0; i < 12; i++ {
		id := fmt.Sprintf("episode:d%d", i)
		insertCorpusEpisode(t, db, id, "deploy:release", "success", 2, now)
		insertCorpusShape(t, db, id, "mise build", "mise deploy")
		if _, err := db.Exec(`INSERT INTO episode_facts (episode_id, fact_id, kind, paths, weight) VALUES (?,?,?,?,2)`,
			id, "fact:deploy", "architecture", "ops/deploy.go"); err != nil {
			t.Fatal(err)
		}
	}
	for i := 0; i < 200; i++ {
		id := fmt.Sprintf("episode:u%d", i)
		insertCorpusEpisode(t, db, id, "other:thing", "neutral", 2, now)
		insertCorpusShape(t, db, id, "ls", "cat")
	}
	if err := buildPatternCandidates(db, "gh/acme/cli", now); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	return brainDir
}

func TestBriefConsolidationsTaskGated(t *testing.T) {
	brainDir := promotableCorpusDir(t, time.Now())

	// Matching task → the deploy consolidation surfaces, anchored and actionable.
	match := loadBriefConsolidations(brainDir, brainBriefFileMatchTerms("deploy a release to production"), 5)
	if len(match) == 0 {
		t.Fatal("expected the deploy:release consolidation for a matching task")
	}
	got := match[0]
	if got.Type != "task" {
		t.Errorf("type = %q, want task", got.Type)
	}
	if len(got.Workflow) == 0 {
		t.Error("consolidation should carry the workflow")
	}
	if got.Anchor == nil {
		t.Error("consolidation should carry a source anchor")
	}

	// Unrelated task → no ambient pattern noise.
	none := loadBriefConsolidations(brainDir, brainBriefFileMatchTerms("rename a css variable in the theme"), 5)
	if len(none) != 0 {
		t.Errorf("unrelated task must return no consolidations, got %d: %+v", len(none), none)
	}
}

func TestBriefConsolidationsSuppressRejected(t *testing.T) {
	brainDir := promotableCorpusDir(t, time.Now())
	db, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(`UPDATE dossiers SET verdict='rejected'`); err != nil {
		t.Fatal(err)
	}
	db.Close()

	got := loadBriefConsolidations(brainDir, brainBriefFileMatchTerms("deploy a release"), 5)
	if len(got) != 0 {
		t.Errorf("a rejected consolidation must not surface, got %d", len(got))
	}
}

func TestBriefConsolidationsGracefulWithoutCorpus(t *testing.T) {
	// No corpus on disk → empty, not error/panic.
	if got := loadBriefConsolidations(t.TempDir(), brainBriefFileMatchTerms("anything"), 5); len(got) != 0 {
		t.Errorf("missing corpus should yield no consolidations, got %+v", got)
	}
}

func TestStrongestConsolidationsForOverview(t *testing.T) {
	brainDir := promotableCorpusDir(t, time.Now())
	got := strongestConsolidations(brainDir, 3)
	if len(got) == 0 {
		t.Fatal("expected at least one strong consolidation for the overview")
	}
	// Ordered by confidence, capped, all current and not rejected.
	for i := 1; i < len(got); i++ {
		if got[i-1].Confidence < got[i].Confidence {
			t.Errorf("consolidations not ordered by confidence: %v", got)
		}
	}
	if len(got) > 3 {
		t.Errorf("overview must cap consolidations, got %d", len(got))
	}

	// Stale dossiers are excluded from the overview (they no longer hold).
	db, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(`UPDATE dossiers SET status='stale'`); err != nil {
		t.Fatal(err)
	}
	db.Close()
	if got := strongestConsolidations(brainDir, 3); len(got) != 0 {
		t.Errorf("stale consolidations must not surface in the overview, got %d", len(got))
	}
}

func TestGetConsolidationByPatternID(t *testing.T) {
	brainDir := promotableCorpusDir(t, time.Now())
	db, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	var pid string
	if err := db.QueryRow(`SELECT pattern_id FROM dossiers LIMIT 1`).Scan(&pid); err != nil {
		t.Fatal(err)
	}
	db.Close()

	found, missing, err := getUnifiedBatch("", brainDir, "main", []string{pid, "pattern:does-not-exist"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 1 || found[0].Source != "consolidation" || found[0].ID != pid {
		t.Fatalf("expected one consolidation result for %s, got %+v", pid, found)
	}
	if len(found[0].Text) == 0 {
		t.Error("consolidation get result should render text")
	}
	if len(missing) != 1 || missing[0] != "pattern:does-not-exist" {
		t.Errorf("expected the unknown pattern id reported missing, got %+v", missing)
	}
}
package cli

import (
	"context"
	"database/sql"
	"encoding/json"
	"strings"
	"testing"
	"time"
)

// seedAcceptedDeepDossier builds a deepDossierRecord with the given fields, marks
// it accepted (with required edits), and stores it in deep_dossiers for patternID.
func seedAcceptedDeepDossier(t *testing.T, db *sql.DB, patternID string, rec deepDossierRecord, requiredEdits []string) {
	t.Helper()
	rec.PatternID = patternID
	blob, _ := json.Marshal(rec)
	verdict := dossierVerdict{Verdict: "accepted", Reason: "coherent repo-specific task", RequiredEdits: requiredEdits}
	vblob, _ := json.Marshal(verdict)
	if _, err := db.Exec(`INSERT INTO deep_dossiers (pattern_id, fingerprint, json_redacted, verifier_json_redacted, verdict, status, created_at, updated_at)
		VALUES (?,?,?,?, 'accepted','current','t','t')`, patternID, rec.Fingerprint, string(blob), string(vblob)); err != nil {
		t.Fatal(err)
	}
}

func deployDeepDossier() deepDossierRecord {
	return deepDossierRecord{
		SchemaVersion: deepSchemaVersion,
		Title:         "deploy:release — mise build ▷ mise deploy",
		Trigger:       "recurring intent: deploy:release",
		Workflow:      []string{"mise build", "mise deploy"},
		Verification:  []string{"go test"},
		Parameters:    []string{"mise deploy --env staging"},
		FailureModes:  []deepFailureMode{{Episode: "s1", Failure: "failed: mise deploy (missing STAGING_TOKEN)", Recovery: "re-ran go test to verify"}},
		Facts:         []string{"fact:deploy (architecture) @ ops/deploy.go"},
		SourceAnchors: []dossierAnchor{{SessionID: "s1", Outcome: "corrected", Excerpt: "ZEBRA_GOTCHA: set the staging toggle before mise deploy"}},
		Confidence:    0.7,
	}
}

// SR1+SR3: skill synthesis input is built from the verified deep dossier and
// carries the dossier's failure modes, verification, parameters, evidence refs,
// and the gotcha that lives only in the transcript span.
func TestDeepSkillEvidenceFromDossier(t *testing.T) {
	in := deepSkillInput{rec: deployDeepDossier(), verdict: dossierVerdict{Verdict: "accepted", RequiredEdits: []string{"document the STAGING_TOKEN precondition"}}}
	ev := buildDeepSkillEvidence(in)
	for _, want := range []string{
		"mise build", "mise deploy", // exact workflow commands
		"go test",                    // verification
		"mise deploy --env staging",  // parameters
		"failed: mise deploy",        // failure mode
		"recovery:",                  // recovery
		"ZEBRA_GOTCHA",               // gotcha from the transcript span excerpt
		"document the STAGING_TOKEN", // verifier required edit
		"fact:deploy",                // evidence/fact ref
	} {
		if !strings.Contains(ev, want) {
			t.Errorf("deep skill evidence missing %q:\n%s", want, ev)
		}
	}
}

// SR1: a promotable task with no accepted deep dossier cannot be formed from
// shallow evidence — the form must require deep verification first.
func TestFormRequiresAcceptedDeepDossier(t *testing.T) {
	brainDir := promotableCorpusDir(t, time.Now())
	db, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	var pid string
	db.QueryRow(`SELECT id FROM patterns WHERE type='task' AND intent_sig='deploy:release'`).Scan(&pid)
	db.Close()

	// No accepted deep dossier → form refuses (and never calls the agent).
	if _, ok := loadAcceptedDeepDossier(brainDir, pid); ok {
		t.Fatal("setup: expected no accepted deep dossier yet")
	}

	// With an accepted deep dossier, the dossier-driven synthesis runs and the
	// agent receives the dossier (not shallow snippets).
	db2, _ := openPatternCorpusMutableDB(brainDir)
	seedAcceptedDeepDossier(t, db2, pid, deployDeepDossier(), nil)
	db2.Close()
	in, ok := loadAcceptedDeepDossier(brainDir, pid)
	if !ok {
		t.Fatal("expected the accepted deep dossier to load")
	}
	var gotInput string
	run := func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
		gotInput = string(input)
		return "---\nname: deploy-release\ndescription: Deploy a release. Use when shipping a tagged build.\n---\n# Workflow\n1. mise build\n2. mise deploy\n## Verification\ngo test\n## Gotchas\nset staging toggle\n", nil
	}
	res, err := synthesizeSkillFromDossier(context.Background(), t.TempDir(), in, "codex", "", "", run)
	if err != nil {
		t.Fatal(err)
	}
	if !res.IsSkill {
		t.Errorf("expected a skill from the accepted dossier, got NOT_A_SKILL: %s", res.Reason)
	}
	if !strings.Contains(gotInput, "VERIFIED SKILL DOSSIER") || !strings.Contains(gotInput, "ZEBRA_GOTCHA") {
		t.Errorf("synthesis input was not the verified dossier:\n%s", gotInput)
	}
}

// SR3 golden: a generic git dossier yields NOT_A_SKILL (the writer still refuses
// non-skill-worthy material even though it was nominally accepted).
func TestDeepSkillSynthesisRejectsGeneric(t *testing.T) {
	in := deepSkillInput{rec: deepDossierRecord{
		Title:    "commit:push — git push ▷ git status",
		Trigger:  "recurring intent: commit:push",
		Workflow: []string{"git push", "git status"},
	}, verdict: dossierVerdict{Verdict: "accepted"}}
	run := func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
		return "NOT_A_SKILL: generic git push/status, nothing repo-specific", nil
	}
	res, err := synthesizeSkillFromDossier(context.Background(), t.TempDir(), in, "codex", "", "", run)
	if err != nil {
		t.Fatal(err)
	}
	if res.IsSkill {
		t.Error("a generic git dossier must yield NOT_A_SKILL")
	}
}
